INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1029572-math201', 'stk-user7238', 'MATH 201', 'info', '{"desc": "الكورس سهل اذا فهمت الكونسبت لانه كله تطبيق مباشر تقريباً\nبس يبي له واحد عنده تخيل والافضل تنزل مع مدرس شرييح (انصح بـ رياض غنام اذا موجود)\n\nعيب الكورس ان فيه قواانيين واجد تحفظها\nفاذا بديت انصحك تاخذ ورقه وتكتب القوانين المهمه الي تحتاجها\nعلشان وقت الميجر تاخذ مراجعه سريعه عليها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/3", "user": "user7238", "ts": 1335614093000, "tid": 120615, "pn": 3}}', 1335614093000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1041214-math201', 'stk-user5643', 'MATH 201', 'info', '{"desc": "انا اشوفه من اسهل كورسات الماث\n\nكورس حلو و مهم خصوصا للي تخصصهم ميكانيكال\n\nاشياء كثيره في الكورس راح ترجع لها بـ ماث 301\n\nالكتاب + نوت شودري ( في موقعه ) يكفون للمذاكره", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/5", "user": "user5643", "ts": 1337631288000, "tid": 120615, "pn": 5}}', 1337631288000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1171878-math201', 'stk-s2010xxxxx', 'MATH 201', 'info', '{"desc": "جودة المقرر بشكل عام : سهل\nالمواضيع التي يغطيها المقرر : سهله وما يبيلها دكتور فاهم , سلف ستدي يكفي .\nالكتاب المستخدم للمقرر : الافضل\nالأسئلة والأمثلة المستخدمة في المقرر : مفيييييده\n\nاهم شي تذاكر الاسئله اللي نهاية كل تشابتر لانها مفيد جدا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/7", "user": "s2010xxxxx", "ts": 1359388126000, "tid": 120615, "pn": 7}}', 1359388126000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1200349-math201', 'stk-chemist', 'MATH 201', 'info', '{"desc": "أصعب كورس ماث مر علي لأني ما حب Three dimensions\nوالكورس أغلبه يتكلم عن Three dimensions\nهذا هو الكورس الوحيد اللي عادة يكون دكاترته لك عليهم من ناحية الشرح فشد حيلك من اول 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/8", "user": "Chemist", "ts": 1363479592000, "tid": 120615, "pn": 8}}', 1363479592000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1208045-math201', 'stk-computist', 'MATH 201', 'info', '{"desc": "الكورس يتكلم في البداية عن parametric equations و polar equations اللي لو يلاحظ الدارس إنه مر عليهم في كورسات الفيزكس و vectorsفي 2d و 3d ثم يتكل عن المستويات ومن ثم الأشكال الهندسية من الدرجة الثانية، ثم يتكلم عن الدوال متعددة المتغيرات، على سبيل المثال حجم الـ cylinder\nV(r,h) = pi*r^2*h\n\nففي الحقيقة الدالة تعتمد على كل من r و h\n\nالنهايات والإتصال والإشتقاق لهذه الدوال و من ثم التكامل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/9", "user": "Computist", "ts": 1365523737000, "tid": 120615, "pn": 9}}', 1365523737000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1231930-math201', 'stk-abo_ali', 'MATH 201', 'info', '{"desc": "ترم 122\n\nجودة المقرر بشكل عام\nجيدة جدا\n\nالمواضيع التي يغطيها المقرر\nيغطي المنهج اشياء كثيرة منها بولار كوردنيت والمعادلات بمجهول واحد واثنين وثلاثة وكيفية اشتقاقهم وتكاملهم\n\nالكتاب المستخدم للمقرر\nممتاز\n\nالأسئلة والأمثلة المستخدمة في المقرر\nممتازه وكافية\n\nمدى فائدته في الناحية التطبيقية\nلكل درس له تطبيقات مناسبة إلا اخر المنهج , ما عرفت وش يبغى في الحياة\n\nاضافات :\n\nالاختبار الاول يكون عادة كتابة والثاني كذلك عليهم 100 لكل اختبار\nاما الفاينل يكون نصه كتابه -للمنهج الجديد- 70 درجة, وخيارات لمنهج ميجر 1 و 2 وعليه 70 = 140 للفاينل\nو كالعادة 60 للكلاس وورك\n\nالدكتور مهم في ذي المادة في وجهة نظري لانه هو اللي بيصحح الاختبارات , فأنصح بالبحث عن الدكتور المناسب\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/10", "user": "Abo_Ali", "ts": 1370367945000, "tid": 120615, "pn": 10}}', 1370367945000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1294808-math201', 'stk-ffaahhd', 'MATH 201', 'info', '{"desc": "انا حاليا في سمستر 131 عندي هذا الكورس وهو سهل جداً ما اتوقعته يكون للدرجة هذي الماتيريال أقل من الكورسات السابقة 102 و 101 وأسهل أيضا.\n\nأي دكتور كويس يناسب وقتك نزل معه مو شرط يكون شررريح وفنان لانك اذا شديت حيلك فيه سلف ستدي راح تجيب درجات عالية بالمياجر .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/14", "user": "ffaahhd", "ts": 1385493158000, "tid": 120615, "pn": 14}}', 1385493158000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1310921-math201', 'stk-legend22', 'MATH 201', 'info', '{"desc": "دائما كنت اسمع انه سهل و خفيف\nكله كلام فاضي قسما بالله\n\nكورس غثيث و دمه ثقيل جدا و الدكاترة ولا أسوء\nالــ 102 أسهل منه بمراحل . نهاية الكالكولس من ازفت ما يمكن . كورس يعبر عنه بالبيضة باختصار", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/17", "user": "Legend22", "ts": 1388270146000, "tid": 120615, "pn": 17}}', 1388270146000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1313719-math201', 'stk-guest', 'MATH 201', 'info', '{"desc": "صراحة ما عجبني الكورس نهائيا 😞 طويل بشكل ممل جدا و مليان قوانين لازم تحفظها ، صحيح أن الكورس مو بذيك الصعوبة لكني أشوفه مافيه أي متعة عكس 102 ، عموما نصيحة ضبط في المياجر لأن الفاينل ما تضمن ايش يجيك، احنا جانا متيريل الميجر الاول ريتن في الفاينل! و متيريل الفاينل كان التركيز عليه أقل شي! موفقين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/19", "user": "Guest", "ts": 1388687874000, "tid": 120615, "pn": 19}}', 1388687874000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1318309-math201', 'stk-user8713', 'MATH 201', 'info', '{"desc": "أخذت هذا الكورس في 131، طبعا بعض الجامعات تسمي الكالكولس الثالث multi variables calculus\nيعني باختصار بتدرس 101 & 102 في أكثر من متغير.مع شوي متجهات.\n\nو تأخذ أحداثيات غير (x,y) في 2D، يسمى الأحداثي القطبي.\n\nأما في 3D تأخذ غير (x,y,z) نظامين الأحداثي الأسطواني و الأحداثي الكروي.\n\nالكورس سهل جدا, أسهل من 101 & 102. بس اختباراته كله كتابة فانتبه.\n\nالشباب يقولو 201 في قوانين واجد,و أشوف أنهم ماب واجد.\n\nعشان تجيب أ+ شتسوي؟؟\n\nحل الواجب اذا مشت أمورك فيه 100% خلاص بس لا قرب الأختبار حل كثر ما تقدر old exams.\nاذا ما مشت أمورك في الواجب حل زيادة من الكتاب أو study plan, وإذا قرب الأختبار حل كثر ما تقدر old exams.\n\nشباب أهم شيء old exams حل 6 أو 8 أو 10.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/20", "user": "user8713", "ts": 1389472413000, "tid": 120615, "pn": 20}}', 1389472413000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1371898-math201', 'stk-medoalkebsi', 'MATH 201', 'info', '{"desc": "الكورس هذا غثيث بشكل مو طبيعي , مافيه اي نوع من انواع المتعه مثل ماث 102.\n\nمع اني الحمدلله جايب درجات جيده , لكن الكورس ما اعجبني , هو خفيف وتقدر تضمن فيه a+ لكن الكورس غثيث . وانصح بأن الي يبغى ينزل الكورس يروح مع دكتور يصحح كويس ويدف درجات.لان الكورس مايحتاج دكتور يشرح .سلف ستدي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/24", "user": "Medoalkebsi", "ts": 1401094853000, "tid": 120615, "pn": 24}}', 1401094853000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1389865-math201', 'stk-emadba7', 'MATH 201', 'info', '{"desc": "زي ما قالو بعض الشباب الكورس غثيث ما اتوقعته كدا … النص الاول منه كان حلو صراحة … الثاني غثثثيث ويكون انت جهدك بدأ يقل مع الوقت … كورس تخيلات 3d … لو فهمت الكونسبت كويس خلاص يسير سهل", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/27", "user": "Emadba7", "ts": 1408045185000, "tid": 120615, "pn": 27}}', 1408045185000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1420439-math201', 'stk-user8581', 'MATH 201', 'info', '{"desc": "المادة بشكل عام سهلة لكن بعد الميجر الأول تصير غثيثة وتكثر القوانين ولأن الميجر الأول كله ريتن والثاني نصه ريتن والفاينل نفس الشي فحاول تنزلها مع دكتور متساهل في التصحيح + خل مصدر في المذاكرة اسئلة الكتاب + نوتة الرصاصي لأن فيها الزبدة وبس الي عليك تحل بعض الاسئلة من الكتاب وقبل الميجر افتح الاولداقزام وراح تاخذ قريد عالي إن شاء الله\nاسئلة الكتاب مهمة لأن اكثر من مرة جاء سؤال من الكتاب في الميجر …\n\nOld Exams and Quizzes\nhttp://aisys.kfupm.edu.sa/MATH_ONLY/Search_Courses1.aspx\n\nهذي نوتة الرصاصي ( راح ارفعها على KFUPMRESOURCES ) إن شاء الله\nhttps://www.mediafire.com/?hxofm5qqju9up9k", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/28", "user": "user8581", "ts": 1421626610000, "tid": 120615, "pn": 28}}', 1421626610000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456331-math201', 'stk-user9893', 'MATH 201', 'info', '{"desc": "أغلب الناس اللي يقولون عنه سهل على نوعين :\n\n1-دوافير وما تفرق معهم .\n\n2-طالب جاب في 101 و 102 C وجاب في 201 C+ ولاحظ التطور وقال سهل 😆.\n\nكورس غير منطقي ولا يخش العقل , قعدت احفظ بس بدون فهم والحمدلله جبت B+.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/36", "user": "user9893", "ts": 1472689560000, "tid": 120615, "pn": 36}}', 1472689560000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466720-math201', 'stk-mkd', 'MATH 201', 'info', '{"desc": "102 أحلى منه بكثير وأمتع بمراحل ، جزء الـ Planes والأمور هذي كان شي بشع ومن أسوء دروس الماث اللي درستها مع إني أحب الماث بشكل كبير\n\nأفضل جزء كان الـ Triple integrals in spherical coordinates ( الماتيريال الأخير بشكل عام رهيب )\n\nالكتاب جدا ممتاز لين آخر ماتيريال ميجر 2 ، تبع الفاينل نوتة الرصاصي أفضل وأوضح بكثير وأسهل بمراحل لأن الكتاب يبدا يستهبل بالشرح 😃", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/37", "user": "MKD", "ts": 1485018186000, "tid": 120615, "pn": 37}}', 1485018186000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1479250-math201', 'stk-user10578', 'MATH 201', 'info', '{"desc": "ماث 201 ترم صيف 163\n\nالكورس مشابه و بمستوى للكورسين اللي قبله بتلقى دروس سهلة و دروس غثيثة\nلكن الدروس الغثيثة قليلة ممكن ثلاث من اصل 25 اما البقية سهالات\nالكورس عموماً سهل و احسه اسهل من 102 من بعض النواحي خصوصاً ان الاخير مخربته السيريسز اللي بنهاية الكورس\nو اللي يميز الكورس ايضاً هو ان المياجر ريتين و نص الفاينل ريتن ايضاً أي ان فرصتك بحصول درجة اعلى اكبر\nلكن ايضاً من النقاط السلبية بالكورس هي الرسم خصوصاً اذا كان 3D ( حسب السؤال )\n\nاخذت الكورس بالصيف و بصراحة الكورس بالصيف حلو و سريع خاصة ان معظم دروسه لها علاقة ببعضها\nوما عليك من اللي يقول بالصيف الافرج عالي ، صحيح عالي و افرجنا كان 290 لكن توزيع القريدات ما يختلف كثير عن الترم العادي\n\nنصحية اخيرة حاول انك تأخذ الكورس بالترم التالي بعد ما اخذت 102 لانه فيه مواضيع و اساليب كثيرة مستخدمة في 102 تحتاج تستخدمها في 201\nخصوصاً الديرفيف و الانتيجرال ، يعني مثلاً جا لنا بالميجر و الفاينل سؤالين طريقة حلهم بأحد اساليب الانتجيرال و هذه الطريقة غير موجودة بكل اسئلة الكتاب\nولا حتى الدكتور تطرق لها و جات بالميجر و الفاينل و نص الشعب جاب العيد فاذا اجلت اكثر ممكن تنسى اشياء كثيرة بالديرتيف و الانتيجرال .\n\nطريقة المذاكرة :\nذاكر من الكتاب و حل اسئلة الكتاب و خذ معك مانويل سلوشن حق الكتاب ( تلقاه بالريسورس او بالنت ) و اخر شيء اولد اقزام اكثر و خلاص .\nو اذا تبي تأخذ نوته تساعدك للدروس اللي ما فهمتها لا بأس ، يمدحون بنوت الرصاصي بالنسبة لي اخذت عبيد لا بأس فيها\nو عندك بعد فيديوهات البلاك البورد بس مشكلتها طويلة و تضيع وقت و يكررون كلام الكتاب .\n\nالزبدة شكلي طولت بالتوفيق و تحياتي سوبرمان .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/38", "user": "user10578", "ts": 1503576296000, "tid": 120615, "pn": 38}}', 1503576296000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1486044-math201', 'stk-abdullah2015', 'MATH 201', 'info', '{"desc": "ترم 171\n\nماتيريال الميجر الأول في هذا الكورس راح يكون عن مواضيع متفرقة Parametric Equations و Polar Equations وكذلك بتتطرق للVectors وكيف تسوي الDot Product والCross Product لمتجهات 2D و 3D (أشياء أخذتها في الفيزكس).\n\nبالنسبة لماتيريال الميجر الثاني والفاينل، فمعظمه يعتبر إعادة لما درسته في MATH101 و MATH102 لكن على Function من متغيرين وثلاثة متغيرات، يعني في MATH101 و MATH102 كنت تتعامل مع Functions زي كذا\nF(x) = x\n\nفي MATH201 الFunctions اللي بتشوفها بتكون بهالشكل.\n\nF(x,y) = x + y\nF(x,y,z) = x + y + z\n\nطبعًا الاشتقاق والتكامل لهذا النوع من الFunctions شبيه جدًا بالاشتقاق والتكامل لFunction من متغير واحد، فلذلك استيعابك واستحضارك لماتيريال MATH101 و MATH102 مهم جدًا.\n\nطبعًا زي ما هو مُلاحظ ، جزء كبير من الماتيريال يعتبر إعادة لما أخذته في كورسات سابقة لكن مع شيء من التوسع، لذلك بالنسبة للأغلبية الكورس يعتبر أسهل من MATH102، لكن الشيء اللي يخلي الكثير يقول إنه كورس غثيث (رغم سهولته) إنه فيه قوانين كثيرة لازم تحفظها، وفيه مسائل صعب تتخيلها لأنها 3D فبتضطر مكرها إنك تحفظ خطوات الحل بدل ما تفهم ليش سويت خطوات الحل أو على أي أساس.\n\nإذا كنت مهتم بال3D وتحب الرسم راح تسمتع بهذا الكورس 🙂 (عن نفسي أشوف أغلبه ماتيريال حلو وممتع، خاصة الماتيريال الأخير، بعكس أغلب الشباب اللي هنا، رغم إني مو مهتم بالرسم ولا بال3D).\n\nفي الأخير بما إن المياجر والفاينل في الكورس ريتن، أنصح إنك تنزله مع دكتور متساهل ويدف في التصحيح، راح يفرق في قريدك النهائي أو على الأقل مجموعك النهائي.\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/39", "user": "Abdullah2015", "ts": 1515866298000, "tid": 120615, "pn": 39}}', 1515866298000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1517953-math201', 'stk-aomab', 'MATH 201', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nmath 201 ترم 191\n\nطبعا الزملاء ما قصروا في شرح المادة وايش تتكلم عنه\nبس من تجربتي فيه كم شيء ممكن يفيدك اشياء جربتها\nواشياء كنت اتمنى ان احد دلني عليها قبل.\n\nقبل ما ابدأ لازم تعرف ان الكورس يحتاج انك تفهم اكثر من حل المسائل.\n\nمن تجربتي:\n1. الفهم ثم الفهم ثم الفهم\n2. بعض الافكار تكون موجودة في الاسئلة( والكثير من الدكاترة ما يشرحها)\n3. الواجب طويل حاول انك تحل من كل نوع سؤال\nوركز على الاسئلة ذات الافكار الغريبة (احتمال كبير تجي في الاختبار)\n(المقصد تحلها بنفسك والباقي تنقشه 🚬)\n3. الكورس سهل فيه القريد العالي بس في نفس الوقت A+ اصعب من اول بسبب الكورس +\nالتوزيع الجديد للدرجات الا في حالة ال A+ تصير افرج.\n4. طبعا الاولد اغزام لا غنى عنه\n\nطبعا لتحقيق اول نقطة وهي الفهم عندك خيارات كثير:\n1. الكورس اون لاين\n2. دكتورك\n3. الكتاب :no_entry_sign:\nبس اللي انا استفدت منه شخصيا واشوفه افادني كثير(بس للاسف ما اكتشفته الا بعد الميجر الاول)\nهي قناة Professor Leonard\nهذا انسان شرح المتيريال تبعنا بالتفصيل وبطريقه مميزه فديوهاته مابين ساعة الى ثلاث ساعات (بس تقدر تسوي سكب لانه يستطرد كثير)\n\nالكورس مختلفة الاراء فيه بشكل كبير 🤪 بس في النهاية كل انسان وقدراته\n\nاسف على الاطالة وفالك A+ 👍", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/41", "user": "AOMAB", "ts": 1576268670000, "tid": 120615, "pn": 41}}', 1576268670000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1522355-math201', 'stk-nasalmz', 'MATH 201', 'info', '{"desc": "الآن وصلت مرحلة انك تنسى النوتات ودخلت مرحلة انك محد بينفعك الا الكتاب ثم الكتاب ثم الكتاب.\nالكونسبت في الكورس غريب جدا يعني حتى المواضيع ترابطها ضعيف جدا.\n\nمن بعد تجربة الكورس:\n\nحاول قدر المستطاع انك تفهم الكونسبت من الكتاب لأن شرح الكتاب واضح جدا.\nحل تمارين الكتاب كلها لأن افكار الكورس محدودة جدا بس انها متنوعة.\nالأونلاين كورس جميل جدا اذا واجهت صعوبة من الكتاب.\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/42", "user": "Nasalmz", "ts": 1590419974000, "tid": 120615, "pn": 42}}', 1590419974000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1528033-math201', 'stk-kjl90', 'MATH 201', 'info', '{"desc": "أخذت الكورس هذا ترم181\n\nالكورس غثيث ما راح تستفيد منه لا حاضرا ولا مستقبلا\nأنا جبت B+ وكان يمديني اجيب A+ بس ما عرفت طريقة المذاكرة إلا متأخر,كانت طريقتي كالآتي:\n1- الأونلاين كورس وأهم شي تكتب القوانين وتلخصها ورقة\n2- نوتات الرصاصي شيك عليها وحل المسائل اللي فيها\n3- الأسئلة المقترحة تحصلها بالسيلابس\n4- خش عالأولد اقزام سكشن باي سكشن وفالك الفل مارك 👍\n\nوبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/43", "user": "kjl90", "ts": 1611209348000, "tid": 120615, "pn": 43}}', 1611209348000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1533294-math201', 'stk-abdulrahman.m', 'MATH 201', 'info', '{"desc": "Math201-211\n\nالكورس المنفوخ 🤣.\n\nالكورس الكونسبت فيه مو صعب لكن المشكلة كلها تكمن في الانتقريشن، اخذته بعد فتره طويله من ماث ١٠٢ -تقريبا سنتين بينهم- لهذا شوي تعبتني هالناحيه.\n\nالاختبارات: متيريال ميجر ١ بالنسبه لي كان اصعب من متيريال ميجر ٢ ، متيريال الفاينل يبيله شغل شوي ولازم تدرب يدك كثير فيه .\n\nافرج ميجر ١ : ٥٦.٢٩ ٪\nافرج ميجر٢: ٧٠.٨٦ ٪\nافرج الفاينل: ٥٠.٩٣ ٪\n\nتوزيع القريدات بالمرفقات.\n\nانصح بانك تبدا ب مقاطع ابوزهره باليوتيوب موجودة ، ثم تروح الى السجستد بروبلمز بالكتاب تراها جدا جدا جدا مهمه بالكورس.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-calculus-iii/120615/44", "user": "Abdulrahman.m", "ts": 1641309152000, "tid": 120615, "pn": 44}}', 1641309152000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p821981-math201', 'stk-user5212', 'MATH 201', 'srcU', '{"html": "السلام عليكم …<br>في المرفقات …<br>مجموعة من القوانين جمعتها من السكاشن المطلوبة<br>10.1 - 10.4<br>12.1 - 12.4<br>…<br>أتوقع اني جمعت جميع القوانين التي نحتاجها … لكن … لا أجزم بذلك …<br>فأعتذر عن النقص … وسوء التنسيق …<br>لكن لعلها تكون مفيدة للمراجعة السريعة … 🙂<br><br>ومرة وحدة … تجدون ضمن الملف … إختبارات سابقة وحلولها لميجر 1 …<br><br>​<span data-fid=\"stk-f821981-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f821981-0": {"name": "Math 201 Major 1 formula sheet.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/c92ef4de1b7fd892f7f0157a45a8f80729348fe892b65fbe0e0aee421cb7daad"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-major-1-formula-sheet/105453/1", "user": "user5212", "ts": 1300824280000, "tid": 105453, "pn": 1}}', 1300824280000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p957007-math201', 'stk-ant_s_brain', 'MATH 201', 'srcP', '{"html": "رد<br><br>المشكلة أنه كله خيارات ((يعني ما في أسئلة ريتن))<br><br>ولا تنسون إن فاينال الماث هذا الترم (111) نصه ريتن والنصف الثاني خيارات<br><br>يعني نصيحتي لكم اكتبوا طريقة الحل في مذاكرتكم واتدربوا على الريتن<br><br>أما الخيارات فأعتقد أنه هذه الاختبارات كفاية وزيادة<br><br>+ كل الاختبارات المرفقة (Master Versions) يعني الخيار A هو الصحيح<br><br>+ هذه الاختبارات هي أقرب 5 اختبارات للترم الحالي - ذاكروها عدل<br><br>شدو حيلكم وموفقيييييين 👍 👍 👍 👍 👍<br><br>​<span data-fid=\"stk-f957007-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957007-1\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957007-2\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957007-3\" class=\"src-fchip\" contenteditable=\"false\"></span>​<br><br>​<span data-fid=\"stk-f957007-4\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f957007-0": {"name": "FINAL MATH 201 (102).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a0e74b7dbbf8021dc1832dc0c256cb7dae102e9ff3ded175a7890845f412d5cb"}, "stk-f957007-1": {"name": "FINAL MATH 201 (101).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/295a953711777c7c350a4eeaee4dff41e8d6dc4936c3813f2c7d71793662820e"}, "stk-f957007-2": {"name": "FINAL MATH 201 (093).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/a26063c2e69d9b2a661d9a1f1cbcd146c64070d9cda447a5f65cfb541b4cb234"}, "stk-f957007-3": {"name": "FINAL MATH 201 (092).pdf", "v": "data:application/pdf;base64,"}, "stk-f957007-4": {"name": "FINAL MATH 201 (091).pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/2c9fc49d7cd259b1e8754a6559583c8759b6e4c99d0406fadd8210c87aa23c4b"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-old-exam/117305/3", "user": "ant_s_brain", "ts": 1325430720000, "tid": 117305, "pn": 3}}', 1325430720000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p837528-math201', 'stk-_hlali', 'MATH 201', 'srcP', '{"html": "السلام عليكم<br><br>هذا سيلوشن ماث 201 الاختبار الثاني<br><br>والكل ان شاء الله بيطلع مبسوط لان<br><br>الاختبار كان سهل ولافيه لف ولا دوران .<br><br>في المرفقات.<br><br>​<span data-fid=\"stk-f837528-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f837528-0": {"name": "MATH201_102_E2_Solution.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/e62348b6cf2d7f48bcc3cbcede3b91298595e94a442af54a78790232e25ad583"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/exam-2-solution-math-201/106833/1", "user": "_HLALI", "ts": 1303854775000, "tid": 106833, "pn": 1}}', 1303854775000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p963573-math201', 'stk-abu_mnahe', 'MATH 201', 'srcP', '{"html": "السلام عليكم<br><br>هاذا السليوشن لـ Math 201 لـ written part<br><br>مع تمنياتي لكم بالتوفيق 🌹 🌹<br><br>​<span data-fid=\"stk-f963573-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f963573-0": {"name": "Sol M-201 F-Exam.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/95f51f0338053d22efa5a234ea4102f805a32cfbbd6b3da85d8b44503d482ec1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/final-math-201-solution/117860/1", "user": "ABU_MNAHE", "ts": 1326199078000, "tid": 117860, "pn": 1}}', 1326199078000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1066549-math201', 'stk-user7909', 'MATH 201', 'srcP', '{"html": "تفضل من المرفقات<br><br>​<span data-fid=\"stk-f1066549-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1066549-0": {"name": "112 math 201 solved all term.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/f63924e75e1736479424c15bc595f23703d5f7cd593feef416aabae0d6e6f0f1"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/201-2-112/128690/2", "user": "user7909", "ts": 1342098024000, "tid": 128690, "pn": 2}}', 1342098024000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1122963-math201', 'stk-user7553', 'MATH 201', 'srcP', '{"html": "في المرفقات …<br><br>دعواتكم بالتوفيق ،،<br><br>​<span data-fid=\"stk-f1122963-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1122963-0": {"name": "Major 2 Solutions.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/fa6dbd1eb890b76e261d120962420c7b142ace58ab30c93c4fa124ad1021e9ca"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-major-2-solutions/135330/1", "user": "user7553", "ts": 1353773303000, "tid": 135330, "pn": 1}}', 1353773303000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1162013-math201', 'stk-isengineer210', 'MATH 201', 'srcP', '{"html": "صبااح الخيير ❤️<br><br>الف مبروووكك الاجاازة للجميع ويا عساهاا دووووم 🤠<br><br>هذا السلوشن مانيوال لفاينل ماث 201<br><br>وطبعاً أسئلة المالتيبل تشويز الدرجة على حسب اختيارك ومالهم شغل بخطوات الحل<br><br>ومثل ماهو موضح بأول صفحة ،،<br><br>السؤال اللي كان فيه خطأ الكل أخذ علامة كاملة فيها &lt;&lt; آخر شي كنت اتوقعهم يسوونه 😆<br><br>وفيه كم شغلة موضحينها للانستركتورز بخصوص بعض الأسئلة<br><br>بالتوفيق جميعاً 🌹<br><br>.<br><br>​<span data-fid=\"stk-f1162013-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1162013-0": {"name": "RelativeResourceManager.pdf", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/5a27661acf8595dda219eb645195c672fdb5bac06aa3d08e325d47365d6dc6e9"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/math-201-final-exam-solution/138181/1", "user": "ISEngineer210", "ts": 1357874926000, "tid": 138181, "pn": 1}}', 1357874926000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-something-math201', 'stk-something', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68348", "n": "Dr. Abdallah Laradji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "لااااااااااااااااااااااا يفوووووووووووووووتكم\n\nking of math 201\n\nواحد من أفضل الدكاترة اللي مروا علي ، علم وشرح و تواضع و أخلاااااااااااااااااااااااااااااااااااااااااق ، يذكرني ببعد قلبي الدكتور شوقي ، إلا اثنينهم زي بعض .\n\nبس عاااادل جدا مع الطلاب و منصف بشكل مو طبيعي ، لكن ما ينلام في الشي هذا لأنه هذا هو الصح 🙂\n\nيحضر يوميا و كويزاته سهلة والكلاسوورك جدا جدا عادل فيه و يعطيك على قد شغلك.\n\nأنصح فيه وبقوة شديدة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p458219-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-laradji/68348/9", "user": "something", "ts": 1252669811000, "tid": 68348, "pn": 9}}]}', 1252669811000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr_3lol-math201', 'stk-mr_3lol', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68348", "n": "Dr. Abdallah Laradji", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : متشدد\nطريقة الشرح :يشرح من نوته ., ونوته لا باس فيه\nالكويزات : عطانا للحين كوزين و اشوف انها مقاربه لصعوبة المياجر\nالمياجر:كومن ( كلها رتن)\nالفاينلات :كومن( أختيارات)\nالقريد النهائي:c\nالصوت:ممتاز\nإضافات :\nمدرس شرحه عادي جدا .\nتصحيحه بالمياااجر ., F بالعربي لازم يكون حلك نفس حل السلوشن .\nانا كنت من محبي الماث . اما هالحين لا والسبب هو . 😐\n\nتقسيم الكلاس ورك ( 3 درجات للهوم ورك و 4درجات للتحضير و 8 درجات ع الكوزات)\n\nنصيحه للي يبي ينزل ماث 201 . دور ع المدرس الي ما يحضر ويعطي كلاس ورك عالُ 👍", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p745229-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdallah-laradji/68348/17", "user": "MR_3LOL", "ts": 1292518458000, "tid": 68348, "pn": 17}}]}', 1292518458000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user1939-math201', 'stk-user1939', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68364", "n": "Dr. Fiazuddin Zaman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معاه قبل لا يصير الماث 201 كومن\n\nطريقة الشرح : متوسطة\n\nالكويزات : سهلة مره ! من النوت حقه\n\nالمياجر: من النوت ! اسئلة مباشرة\n\nالفاينلات : زي المياجر\n\nالقريد النهائي: ممتاز\n\nالصوت: كويس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p343564-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fiazuddin-zaman/68364/3", "user": "user1939", "ts": 1230203276000, "tid": 68364, "pn": 3}}]}', 1230203276000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yazeed_7-math201', 'stk-yazeed_7', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68364", "n": "Dr. Fiazuddin Zaman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا عنده هالسمستر 111 في ماث 201\n\nالتحضير في ورقة تمر على الطلاب، واعتقد انه سهالات،\n\nيتساهل بالهومووركات اذا تأخرت فيها يقولك خلاص جبها لمكتبي بكرا الصباح، او اذا غبت عن كويز تحاول فيه يخليك تجي تختبر بالأوفيس اور\n\nبعكس باقي الدكاترة الهنود الصوت عنده عالي،\n\nالشرح لو تركز ممتاز، لكن مشكلته في الأكسنت للأسف سيء\nحتى انه يبلشنا بالكلاس بكلمة ( سكوير ) ينطقها سكير 🙂\n\nمممممم وش بعد؟\n\nايه مايحاسب عالتأخير وبأي وقت تدخل الكلاس عادي\n\nارشح فيه اذا مالقيت مدرس معروف وشرحه أحسن", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p910117-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/fiazuddin-zaman/68364/24", "user": "yazeed_7", "ts": 1317230400000, "tid": 68364, "pn": 24}}]}', 1317230400000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_04-math201', 'stk-_04', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه ترم 101 ماث 201 … وأبدا ما أنصح به\n\nالتحضير: في بداية الترم كان ما يحضر بس بعدين حس أنه الوضع مهزلة فصار يحضر .\n\nطريقة الشرح: أتوقع أنه يحل اقزامبل الكتاب .\n\nالكويزات: سهله الى متوسطة .\n\nالمياجر: كومن … والتصحصح عادي الى جيدجدا مرتفع هههههه .\n\nالفاينلات: كـــــــــــومن .\n\nالقريد النهائي: سي وأحس اني معطيه اكثر من حقه … احس نفسي قوي ههههههه .\n\nالصوت: ممتاز\n\nإضافات: لا تاخذ عنده الا اذا حدتك ظروف خارجه السيطرة … يعني خذه على أساس الوقت واعرف انك ما راح تستفيد حاجه .\n\nبس ما أقول الا الله يرضي على مستر أيمن اللي يفهمني الماث من أيام الفرشمان ههههههه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p748428-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/18", "user": "_04", "ts": 1292883786000, "tid": 68366, "pn": 18}}]}', 1292883786000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-harry_potter-math201', 'stk-harry_potter', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - 101\nالتحضير : اول السمستر ما يحضر بعدين شاف اننا ما ننعطا وجه صار يمرر ورقه\nالشرح : يدخل معاه نوت و يكتبه على السبوره فقط + ابلشنا بخان اكادمي + يحاول انه يوصلك المعلومه\nبس لا حياة لمن تنادي 😆\nالمياجر: كومن\nالفاينل : كومن\nالكويزات : سهله عطانا 5 كوزات و اخذها كلها\nكلاس وورك : يعطيك حقك\nالهوم ورك : لو تسلمها له قبل الفاينل بيوم اخذها منك\nالتصحيح : على ال KEY بالظبط\nالصوت : 10/10\nالاخلاق : 100/100 محترم جدا و طيب طيبه ما شفتها بغيروه\nالقريد النهائي : C+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p775054-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/19", "user": "harry_potter", "ts": 1296042839000, "tid": 68366, "pn": 19}}]}', 1296042839000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-scientist1-math201', 'stk-scientist1', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 101 - Math 201\n\nالتحضير : في البداية ما يحضر وبعدين قام يمرر ورقة وتحضر اللي تبي\nطريقة الشرح : الشرح مش ولا بد… بالعربي أنا ما فهمت عليه أبدد\nالكويزات : سهلة وعادةً يرسل لك سؤال على الإيميل ويجيب زيه في الكوز…طبعاً يفتح لك المجال للغش\nالمياجر: كوووومن\nالفاينلات : كوووومن\nالقريد النهائي: D\nالصوت: ممتاز\nإضافات : أبعد عنه الا اذا بتموت اذا ما نزلة عنده\nأكثر شي تندمت عليه في حياتي الجامعية اني نزلت عنه…من جد كرهني في الماث بعد ان كنت أعشقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p780804-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/22", "user": "Scientist1", "ts": 1296684363000, "tid": 68366, "pn": 22}}]}', 1296684363000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6202-math201', 'stk-user6202', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201\nSemester 102\n\nالتحضير : شبه يومي … في البداية كانت ورقة تدور على الطلاب لكن بعدها صار يحضر في بداية الكلاس بالأسماء …\nطريقة الشرح : متوسطة وعادية … اذا بتركز وتكتب نوت وراه تفهم … لكن اذا حالك مثل أكثر الطلاب تجي متأخر ومفوت دروس واجد هنا يمكن تواجه صعوبه شوي في شرحه\nالكويزات : في السمستر كله ما أعطانا الا خمس كويزات وكانت سهلة جدا(ن) << طبعا(ن) للي مذاكر\nالدكتور هذا ما عنده مانع يفتح المجال للغش 😐 وأحيانا يقول open book quiz\nالمياجر: كومن وتصحيحه يعتبر نسبيا(ن) ممتاز 👍\nالفاينلات : كومن + multiple choice 😞\nالقريد النهائي: B+\nالصوت: واضح … وأحسن شي اذا قال NOoo ! 😆\nإضافات : المدرس حبوب وخلوق جدا(ن) … يفضل الطلاب اللي يشاركون وأحيانا اذا جاء يشرح ما يناظر الا هم 😐 والباقين الله بالخير 🤠\nعنده مشكلة انه احيانا(ن) يعطيك نظرة على ان المادة صعبة جدا(ن) 😐", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p861120-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/26", "user": "user6202", "ts": 1309330857000, "tid": 68366, "pn": 26}}]}', 1309330857000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-math201', 'stk-student_nz', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم 102\n\nالتحضير :\nما تدري عنوو\nساعات يحظر وساعات ورقة\nوساعات اسم\nواصلا تحسوو ضايع\n\nطريقة الشرح :\nعلى السبورة\nطبعا ما نفع لي\n\nالكويزات :\nعلى كل سكشنين او 3\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nاعطيه سي\n\nالصوت:\nواضح\n\nإضافات :\nحاول تخليه يعررررفك عشان تاخذ كلاس ورك عالي\nيعني اكتب معاه\nمع انه ممل شوي\nويكتب كثيييييييييييييييييييييييييييييييييييييييييييييييييييييييييير\nلكن اصببر عشان تاخذ كلاس ورك عالي\n+\nهو يصحح لك مياجرك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p880053-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/27", "user": "student_NZ", "ts": 1312517850000, "tid": 68366, "pn": 27}}]}', 1312517850000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6452-math201', 'stk-user6452', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201-سمستر 102\nنزلت معه عشان واحد مدح تصحيحه\nلكن\nوالله اعلم ان القسم شددوا عليه بخصوص التصحيح فصار تصحيحه لك عليه\nيعني لا تصحيح ولا شرح\nالحسنه الوحيده هو الكلاس وورك لانه يعتمد على الكويزات وهي سهله غالبا\nوفي الكلاس خذ راحتك ما يدري عنك\nوبالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p899830-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/30", "user": "user6452", "ts": 1315812780000, "tid": 68366, "pn": 30}}]}', 1315812780000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aflatoon-math201', 'stk-aflatoon', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 - ترم 102\n\nالتحضير : على مزاجه … اذا شاف السكشن مليان ماحضر … واذا شافه فاضي حضر !!\n\nطريقة الشرح : على السبورة … الرجال مجتهد في الشرح بس ماحولك احد … شرحه مش ولابد يعني 🙂\n\nالكويزات : سهلة , وتكون غالبا من النوت … طول السمستر 4 او 5 كويزات …\n\nالمياجر : كومون , بس تصحيحه جيد , ويمشي كم خطوة …\n\nالصوت : واضح\n\nالقريد النهائي : اعطيه b\n\nاضافات : اصلا كورس 201 من اسهل الكورسات في الماث … واغلب الشباب يذاكرون من نوت ايمن … بصراحة اشوفها ممتازة فقط في 201", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p901115-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/31", "user": "AFLATOON", "ts": 1315954987000, "tid": 68366, "pn": 31}}]}', 1315954987000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6966-math201', 'stk-user6966', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه ماث201 ترم 111\nالتحضير :لو تجي بآخر عشر دقايق توقع ع الورقة عادي, يمكن يسألك “ليش تاخرت ؟” فتصرفه وتقول ازدحام مروري او اي بطيخة تصرفها عليه ويمشيها لك .\nالشرح : زبآآآآآآآآآآلة , ممل لأبعد حدووود , اتعرفت على شباب بالفصل من الملل الي احسه , والساعة تتوقف معاه بالفصل . مدري هو الساعة تخرب ولا ه عنده قوة غريبة تخلي الزمن يوقف .\n\nالنوت : كله اخطاء , الطلاب يطلعون اغلاطه, يعني يبغالك تحضر للدرس عشان لو اخطا تنتبه لخطأه وتعلمه عشان ما تنقل من نوته وتنّكب بعدين . نوته هو ما ياخذه من اكزامبل الكتاب لأن امثلة الكتاب سهلات على كلامه, فهو يجيب من اولد اكزامز وكذا .\n\nالصوت : الأكسنت حقته واضحة ومفهومة رغم انها هندية\nالتصحيح : خرافي , يعطيك اكثر من حقك بزيااااااااااااااااااااااااااادة , لولا الله ثم تصحيحه كان يمكن ارسب بشرف . والكلاس وورك يدفففك دفففففففف\n\nالكويزات : سهلة\nاضافة : لا تخليه يعرفك نصيحة !! ترى ان عرفك بيقعد يسألك انت لحالك بالفصل لأن اغلبية الفصل مطنشينه , فبتكون انت الوحيد الي يعطيه وجه وبكذا راح يسألك واذا طلعت مو فاهم يقعد يقولك Why don’t you study at home ? you have to study and practice\nالقريد النهائي : D >> عشان تصحيحه بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p965299-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/34", "user": "user6966", "ts": 1326355444000, "tid": 68366, "pn": 34}}]}', 1326355444000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-deep_al_l3eep-math201', 'stk-deep_al_l3eep', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا نزلت معاه ماث 201 في ترم 131…من افضل الاساتذة الي مرو عليا في الجامعة من دون مبالغة والله لانو قمة في الاخلاق ويضحك مع الطلاب وشرحو جدا بطل والاكسنت حقو مزبوط يعني تفهم غصبن عنك وعلى قول بعض الشباب حسسوا انك مهتم واجلس قدام كل كلاس واكتب معاه وحتاخد فل مارك في الكلاس ورك\n\nكويزاتو من اسالة الكتاب وسههههههههلة جدا\n\nالتحضير في اخر الترم بس شدد لانو الطلاب الي في الكلاس زودوها لدرجة انو ماسار يحضر الا عشرة طلاب\n\nالتصحيح يزودك بس مو قدي كدة بس لو كتبت حاجة حيدك عليها كذة درجة لانو في اساتذة لو بس شافو الحل غلط ينقصوك السؤال كولو وهدا تفكير غلط زي (الرصاصي)\n\nالقريد النهائي a+\nان شاء الله اني منزل معاه 202 في الترم الجاي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312146-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/38", "user": "deep_al_l3eep", "ts": 1388447170000, "tid": 68366, "pn": 38}}]}', 1388447170000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8624-math201', 'stk-user8624', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - Term: 131\n\nالتحضير : في البداية ما كان يهتم بالتحضير … لكن نهاية الترم صار يحضر\nطريقة الشرح : على السبورة … ويحل مسائل كثيرة من الكتاب … شرحه ممتاز إذا مستواك كويس ف الماث…\nالكويزات : سهلة , وتكون غالبا من أسئلة الكتاب … 4 او 5 كويزات ف السمستر …\nالمياجر : كومون\nالصوت : واضح\nالقريد النهائي : A+\n\nالرجل متواضع وطيب لأبعد الحدود …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1312479-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/39", "user": "user8624", "ts": 1388510975000, "tid": 68366, "pn": 39}}]}', 1388510975000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-immortal_vertcl-math201', 'stk-immortal_vertcl', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طبعا هذا المدرس اخذت معه ماث 201 ترم 131 و ماث 202 ترم 132\nالتحضير :\nفي 201 كان المدرس في البداية مايحضر بعدين صار يحضر على نهاية الترم , اما في 202 كان يحضر دايما + المدرس مايحاسب على التاخير ابدا , تعال الكلاس وقت ماتبغى , والمدرس متساهل من ناحية الغيابات\nطريقة الشرح :\nانا اشوف ان شرحه عادي جدا مو مرة كويس\nالمياجر : common\nالفاينلات : common\nالكويزات :\nيعطيك خمسة الى ستة كويزات كلها سهلة جدا\nاضافات :\nالمدرس طيب جدا و تصحيحه خورااااااااااااافي جدا والكلاس ورك يزودك كثيييييييير\nالقريد النهائي :\n+b", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1375201-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/40", "user": "immortal_vertcl", "ts": 1401597568000, "tid": 68366, "pn": 40}}]}', 1401597568000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hammmod-math201', 'stk-hammmod', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 term 151\n\nالتحضير : ورقة تمر على الطلاب وأحيانا ينسى، ما يهتم كثير للتحضير.\n\nطريقة الشرح : يجيب نوتة جاهزه معه ويكتب عالسبورة، مشكلته شوي ملخبط صراحة، ويملأ السبورة مدري كم مرة، لكن بشكل عام جيد وكافي في توصيل الكونسبت، بس مشكلته في أحيان كثيرة يطولها وهي قصيرة، تحسب الموضوع معقد من كثر ما يعبي السبورة بس تكتشف انه سهالات.\nالكويزات : 5 كويزات أغلبها سهلة ونفس كويزاته اللي في موقع الديبارتمنت\nالمياجر:\nالفاينلات :\nالقريد النهائي: يمشي الحال مهوب سيء b\nالصوت: واضح وآكسنت ممتازة.\n\nإضافات : مدري ليه الجو العام في الكلاس كان تسليك يعني ما فيه الا 5-6 مركزين والباقين ساحبين، هو عادي ما يهمه كثير.\nأحسن ما فيه تصحيحه ممتاز جدا والله، يعطيك حقك وزيادة، بس ما يزودك لو تجي تناقشه الا نادر بس الدرجة اللي يكون معطيك اياها أكثر من حقك.\nيحب يستظرف وفعلا أحيانا يقول أشياء تضحك\nالدكتور عنده طرق غير عن حقت الكتاب وكانت مفيدة والله، خصوصا آخر الدروس في 201 طريقة الكتاب تتطلب انك ترسم في الثري دي، ما أحتجت أرسم ثري دي أبد.\nآخر شيء ما زودنا في الكلاس وورك ولا حذف ولا كويز. المدرس الوحيد اللي ما قد زودني، على الرغم من ان الافرج كان اقل من 30 بس هو ما زودنا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1436892-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/41", "user": "hAmMmOd", "ts": 1451074466000, "tid": 68366, "pn": 41}}]}', 1451074466000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-adg2015-math201', 'stk-adg2015', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68366", "n": "Dr. Hasan Azad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 - 162\nالتحضير :\nورقه وتمشي واخر السمستر صار ما يحضر\n7 في الكلاس والي موقعين 30 🚬\nطريقة الشرح :\nما ادري صراحه بس سيئه\nالكويزات :\nمتوسطه واحيانا سهله\nالقريد النهائي:\nC\nالصوت:\nواضح والاكسنت هندي\nإضافات :\nتصحيحه كويس وغالبا يعطيك اكثر من حقك شوي\nاذا نزلت معه اعرف ان الكورس بيكون سيلف ستدي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474196-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hasan-azad/68366/42", "user": "Adg2015", "ts": 1496179580000, "tid": 68366, "pn": 42}}]}', 1496179580000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mujtaba_alsaleh-math201', 'stk-mujtaba_alsaleh', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 - 122\n\nيحضر يوميا اول الكلاس في البداية يقول ارقامكم بعدين خلاص يحفظهم بس يطالع ويحضر والتأخير اذا تتأخر كلاسين ورى بعض يقولك اختار واحد منهم ابسنت لدرجة اني قمت اتاخر كلاس واحضر على الوقت الكلاس الي بعده خخ امزح\n\nالشرح بالنسبة لي سيييء جدا عنده نوت وبس ينقلها على السبورة ولاتدري بشي لو تشيل النوت من يده مايعرف يحل شي مرة كان في ايكزامبل في النوت خطا ماعرف يصحح الخطا وترك السؤال والطامة الكبرى في نهاية السمستر قال الي بيجيب لي سؤال يجيبه لي مع الحل واشرح له مب احل اسئلة\n\nوالنوت حقه مكتوب بيده وخطه سيء بتتعب معاه\n\nالتصحيح يقولون جيد بالنسبة لي اشوفة سيء لاني حليت سؤال صح والجواب النهائي صح وخصم علي درجات يوم رحت له قالي خطواتك مب نفس السلوشن مانوال المهم ثار اعصابي ويالله يالله طلعت بحقي معاه\n\nبالنسبة لي اعطيه F ولو مافي غيره أأجل الكورس ولا انزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1356205-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/33", "user": "Mujtaba_AlSaleh", "ts": 1398215513000, "tid": 68375, "pn": 33}}]}', 1398215513000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_faddagh-math201', 'stk-m_faddagh', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا اعارض من يقول لاتزل عنده ابد\n\nهو ميزته بالتصحيح ، بالميجر الثاني بدون مبالغة زادني تقريبا 15 !! في math 201\nكويزاته سهلة , نسخ لصق من نوتاته\n\nصحيح ان شرحه سيء لكن الكورس سهل جدا ولو تقرا نوتاته وتحل امثلة واولد اكزامز تفهم ويغنيك عن شرحه\n\nباختصار اذا كنت تذاكر فالبيت اول باول فانصح به وبشدة عشانتصحيحه المتساهل جدا\nاما اذا كنت من النوع اللي ما يذاكر الا قبل المياجر فحاول تدور غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1425724-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/37", "user": "m_faddagh", "ts": 1440531909000, "tid": 68375, "pn": 37}}]}', 1440531909000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sabfas-math201', 'stk-sabfas', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 - Term 141\nالدكتور شرحه سئ من ناحيتين : مايوصل المعلومة بالشكل المطلوب + ممل جداً لدرجة انه سهل جداً تفقد تركيزك من البداية\nيكره شئ اسمه جوال … كان كلاسه أغثّ كلاس مرّ علي في مسيرتي الجامعية… لأن شرحه سئ ولاتفهم معه, ولاعندك شئ تسوي طوال هالخمسين دقيقة غير انك تسرح بخيالك.\nنزلت عنده لأن الشباب قالوا ان تصحيحه ممتاز… للأمانة انا أشوف ان تصحيحه لدرجاتي عادي… يعني في الميجرين مازادني شئ يذكر… عطاني حقي وبس\nقد يكون هالشئ حصل فقط معي… تصحيحه في الكويزات كان افضل شوي ويدف درجة او درجتين من 10… بس كان يدف الكل وبالكلاس وورك افرج فما راح تستفيد بالنهاية :d\n\nالتحضير عنده كان يومي… يحفظ اسمك من ثاني اسبوع هههه\nفي آخر الترم كان يحضّر بدون مايفتح فمه اصلاً… بمعنى يمسك ورقة التحضير ويقعد يحضر من نفسه لأنه يعرف اسماء جميع الطلاب هههه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1440873-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/38", "user": "sabfas", "ts": 1454054221000, "tid": 68375, "pn": 38}}]}', 1454054221000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-modywahab-math201', 'stk-modywahab', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - 152\n\nالتحضير :\nيومي وبالارقام ، والتأخير أحيانا يسجله بعد ١٠ دقايق\n\nطريقة الشرح :\n(*يحاول يخلي العاطفه على جنب*) الدكتور يعتمد على النوت حقته بشكل أساسي، النوته يكتبها بخط يده ويرفعها PDF في البلاك بورد، إذا كنت تفكر إنك تستفيد من شرحه بدون ما تطبع النوته وتجيبها معك فأنت واهم، ولو جبتها بتفهم من النوته،ما راح تفهم من شرحة إلا بنسبة %40، لأن النوته ممتازة لكن شرحة ماله حل. يكلم الصبورة ويغطي عليك وين ما كنت جالس في الكلاس، أحياناً يقعد يحل مسألة عشر دقايق ولا تشوف من الشرح إلا ظهره،.\n\nالكويزات :\nمع إحترامي ،يتخذ أحد أساليب دكاترة الماث الوسخة في نظري عشان يوازن الأڤرج. يخلي نموذج صعب ونموذج سهل. أنت وحظك.\nالتصحيح يمشي كثير لكن أحيانا يقهرك وما يمشي لك، بس عموماً يعطيك حقك.\n\nالمياجر والفاينلات:\nكومن، لكن التصحيح يمشي على تصحيح الكوردينيتر فإذا كان الكوردنيتر شديد يكون شديد زيه، والعكس صحيح. إذا كنت بتاخذه عشان التصحيح فما يسوى صراحتاً\n\nالقريد النهائي:\nC\n\nالصوت:\nواضح ومفهوم\n\nإضافات :\nيومياً ومن بداية الفصل لازم يجيب سيرة الإڤاليوويشن، وكيف إن الطلاب ظالمينه فيه، عادي فجأة يقطع المحاضرة ٥-٧ دقايق كلها تحلطم(تذمر)، وهذا يسوي ربشة ويشتت الطلاب كثير، والمشكلة إن كل الأشياء إلي يقول إن الطلاب ظلموه فيها أشوفها فيه. لا تغلط وتقعد أخر واحد في الكلاس لأنه بيعطيك جرعه إضافيه من الحلطمه. وبعد كل ميجر ينسب فضل إرتفاع درجاتنا إلى نفسه مع إن الأفرج النهائي حقنا أقل من باقي السكاشن 🤔.\nلكن في الأخير الماث شئت أم أبيت هي مادة سلف ستدي، ما راح يأثر الدكتور كثير فيها عشان كذا يوم شفت التقييمات ما أهتميت كثير وأخذته عشان الوقت. لكن عشان النقطة الأخيرة إلي ذكرتها تحسفت يوم أخذت عنده.\nEX1 Sec Avg: 71.59 Overall Avg: 73.23\nEX2 Sec Avg: 55.96 Overall Avg: 56.05\nCLW Sec Avg: 28.22 Overall Avg: 28.43\nHWT Sec Avg: 15.26 Overall Avg: 16.29\nFEX Sec Avg: 89.26 Overall Avg: 91.82\nTOT Sec Avg: 260.30 Overall Avg: 265.89", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1450316-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/40", "user": "modywahab", "ts": 1464127467000, "tid": 68375, "pn": 40}}]}', 1464127467000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-math201', 'stk-khdsa2022', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم - منقول عبر واتساب\n\nاسم المدرس : Taleb Kurdi\nالمادة : Math201\nالترم: 183\n\nالتحضير : يسمح تأخير عشر دقايق لكن مايدخلك الكلاس بعدها و يحضر كل يوم نهاية المحاضرة\n\nطريقة الشرح : يشبك الايباد على البروجيكتر ويحل بسرعة وبطريقة مو مفهومة لكن اذا سألته يجاوبك و ممكن يعيد السؤال عشانك اهم شي اسأل\n\nالكويزات : كويزين بلاكبورد و كويزين رتن\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: كويس\nإضافات :\nيشرح لآخر ثانية وممكن يأخرك دقيقتين عشان يخلص الدرس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513673-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/15", "user": "Khdsa2022", "ts": 1565782702000, "tid": 175799, "pn": 15}}, {"id": "stk-dr-m172449", "n": "Dr. Yassir Khalid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم - منقول عبر واتساب\n\nاسم المدرس : ياسر خالد\nالمادة : math201\nالترم: 171\n\nالتحضير : يمرر ورقة على الطلاب وتوقع\n\nطريقة الشرح : على السبورة من نوته الخاصة واحيانا يشرح من الكتاب ويحل بعض الاسئلة منه\nنادرا يستعمل البروجكتر\n\nالكويزات : متوسطة وعادتا تكون اثنين قبل الميجر وتغطي ماتريال الميجر نفسه\n\nالمياجر: common\nالفاينلات :common\n\nالقريد النهائي:A\n\nالصوت: منخفض اذا جلست ورا\n\nإضافات : الرجال متعاون مع الشباب حيل من ناحية الحضور اولا يسمح بالميكب اب الا بيوم الكويز ثانيا تصحيحه حلو ويزود درجات ويعطيك فوق حقك باعمال السنة ومتواجد بالاوفيس اور ومتفهم للمشاكل الطلاب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513677-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yassir-khalid/172449/10", "user": "Khdsa2022", "ts": 1565783352000, "tid": 172449, "pn": 10}}, {"id": "stk-dr-m68375", "n": "Dr. Abd-Ur-Rahim Khan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "منقول عبر واتس\nاسم الدكتور : عبدالرحمن خان\nالمادة: math201\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير :شديد ويحفظ الارقام ويسجل فيها ما يمدي خويك يحضرك\nطريقة الشرح : سيء جدا جدا جدا لا لهجه كويسه ولا خط كويس ولا نوتات كويسه طلامس تقعد تترجمها.\nالكويزات :سهله متوسطه صعبه هذا اغبي شيء عند الدكتور كل كويز ٦ نماذج وانت وحظك حرفيا تجيك نماذج تخذ فل تجيك نماذج تخذ ٠\nالمياجر: كومن\nالفاينلات :كومن\nالقريد النهائي:D\nالصوت: عالي\nإضافات : الدكتور مهتم واخلاق وطول الترم ينصح تركز معه مشكلته يتهم شكل بس اما نوتات الخ ما يتعب فيها ولا شيء. كان بداية الترم يخليني العب ورا ولا يكلم بس نشب لي مو قصة زحف بس كنت اذاكر ورا لحالي اصرف لي طلعت بسبب انه الكل ضايع معه بكلاس وورك ٢٦ وطلعت من الكورس بB+ صراحه لو دكتور ٢ ممكن اطلع بA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518740-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abd-ur-rahim-khan/68375/44", "user": "Khdsa2022", "ts": 1578207563000, "tid": 68375, "pn": 44}}, {"id": "stk-dr-m83632", "n": "Dr. Khalid Al-Anezy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور :\nKHALID ALANEZY\n\nالمادة: Math 201\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\nالتحضير : التحضير بداية الكلاس\n\nطريقة الشرح : من النوتات ويحل الأسئلة على السبورة. شرح ممتاز جدا ويشرح كونسبت ويحل الأسئلة بتوازن. أسئلة النوتات ممتازة.\n\nالكويزات : متوسطة. شبيهة بالنوتات وأحيانا أصعب شوي\n\nالمياجر: من الديبارتمنت\nالفاينلات : من الديبارتمنت\nالقريد النهائي: الدكتور يستاهل A+++\nالصوت:واضح وممتاز\n\nإضافات : الدكتور أول مرة يدرس 201 وكان متمكن من المادة ما شاء اللّه. محترم جدا وطيب. المشكلة أنه يتأخر شوي بداية الكلاس وممكن ياخذ وقت زيادة بعد ما يخلص الوقت. نصيحة سجل معاه وماراح تندم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518851-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khalid-al-anezy/83632/33", "user": "Khdsa2022", "ts": 1578296433000, "tid": 83632, "pn": 33}}, {"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATSAPP\nاسم الدكتور : Adel khalfallah\nالمادة: Math 201\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : احضر وشوف بنفسك بس من هالناحية لا تخاف\nطريقة الشرح : سريع الدكتور بالشرح بس اشوفه كويس وكنت افهم معه. الدكتور يتقبل اي سؤال مهما كان السؤال تافه بجدية وما عنده مشكلة.\nالكويزات : اختبرنا خمس كويزات تقريباً متوسطة الصعوبة و للأمانة ما ادري اذا حذف شيء او لا.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : كورسات الماث بشكل عام تحتاج تحل كثير عشان تجيب جريد حلو وذا الكورس تقدر تخليه سلف ستدي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518864-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/31", "user": "Khdsa2022", "ts": 1578313288000, "tid": 118563, "pn": 31}}]}', 1565782702000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-everest-math201', 'stk-everest', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201\nTerm: 101\n\nالتحضير: أحيانا ورقة تمر على الطلاب وأحيانا ينادي على الاسماء، المتاخرين ما يقول لهم شي.\n\nطريقة الشرح: يكتب نوت ممتاز جدا ومرتب وشامل وينزله على الويب سي تي، بس مشكلته إن\nمعظم الأمثلة اللي يحلها عادية يعني لا هي صعبة ولا هي سهلة، يقول أهم شي الكونسبت. ادا الدرس في رسم وتخيل كيثر يجيب سلايدات عشان الرسمات تكون أوضح.\n\nالكويزات(10%): سهلة من أسئلة الهومورك الي موجودة في السيلابس ، في النهاية أخد أحسن أربعة من سته.\n\nالواجبات(5%): عطانا أربعة واجبات وتكون خمسة أو ستة أسئلة سهلة نفس أفكار الكتاب، أخد أحسن ثلاثة.\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالصوت: واضح والاكسنت ممتاز مع أنه شرق آسيوي.\n\nإضافات: مدرس أخلاق ممتازة ودائما مبتسم ومتساعد مع الطلاب، ما عنده مشكلة أنه يأجل الكويز أو الهوم ورك ادا كان في ضغط على الطالب. شرحه جيد جدا يميل إلى الممتاز بس عادي لأن المادة أسهل من 102. يدف في التصحيح.\n\nأنصح فيه وبشدة.\n\nالقريد النهائي: A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p779318-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/23", "user": "EvErEst", "ts": 1296430834000, "tid": 68383, "pn": 23}}]}', 1296430834000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5771-math201', 'stk-user5771', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 سمستر 102\n\nخلاصة الكلام اذا تبغا دكتور يعطيك في التصحيح في المياجر فوق حقك بما لايقل عن 10 درجات وتبغا دكتور اخلاق جدا والتحضير يحظرك ومايقلك شي لو جيت آخر دقيقه او سويت ميك اب ويسمح تسوي ميك اب للكوزات لو تخليها اخر السمستر وسريع في التصحيح ولو تاخذ دي ان يمشيك وكوزاته هي نفسها اسئلة الهوموورك بالنص يقول حلوها في بيوتكم وتعالو اختبروا هنا وآخر السمستر يختار احسن 4 كوزات من 6 نزل مع خيروووووووووول\n\nدكتور بطل جدا اشوف افضل الموجود والماده مايبغالها دكتور شريح ابدا لانها استكمال لماث 102\nيعني نزل عند دكتور تصحيحه بطل وتوكل على الله\n\nبالنسبه للكلاس وورك بيدك حل اسئلة الهوموورك وتعال حلها في الكوز وخذ فل مارك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852208-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/24", "user": "user5771", "ts": 1307961070000, "tid": 68383, "pn": 24}}]}', 1307961070000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a-mubarak-math201', 'stk-a-mubarak', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ماث 201 تيرم 111\nبصراحه الدكتور ممتاز وطيب لأبعد الحدود ومتساهل في التحضير مره\n\nشرحه ممتاز ويوصل المعلومه ولكن عيبه ما يعطي امثله زياده\nبالنسبه للهوموركات يعطيك اسئله معينه تحلها ومتساهل كثير في التسليم وبعد يعطيك اسئله ثانيه تحلها عشان الكوزات …يجيب كوزات قريبه مره من الأسئله الي تحلها\n\nبصراحه دكتوررر ما يتفوت انا الحين سجلت عنده ماث 202", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p973051-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/26", "user": "A-Mubarak", "ts": 1327402890000, "tid": 68383, "pn": 26}}]}', 1327402890000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-unkhaled-math201', 'stk-unkhaled', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - 151\n- الدكتور اخلآق لأبعد درجة … وابتسامته طول الترم ( بالكلاس ، الاوفس ، الممرات … ) .\n- يعطي لمحة سريعة عن الدرس ويكون مجهز سلايدات فيها اسئله متسلسله الافكار والصعوبه .\nيحلها بشكل مفصل ع البورد … وشرحه جدا بطل للي بيركز ، ويتقبل اي سؤال بصدر رحب .\n- التصحيح اذا م ساعدك ما يظلمك .\n- الكوزات متنوعة … سهله لمتوسطة وشبه صعبه نادرا .\n- الكوزات 5 او 6 … ويحذف اسوأ واحد .\n- التحضير يوميا بنفسه ، وصار يحفظ اسمائنا ويحضر بدون م ندري .\n- يسمح بالميك آب لو طول الترم عادي .\n------\nملاحظة : وصلت لـ9 غيابات واعطاني 3.2 من 5 ف الحضور … وربي بطللل هالآدمي .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437805-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/37", "user": "unkhaled", "ts": 1451763995000, "tid": 68383, "pn": 37}}]}', 1451763995000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cs_scientist-math201', 'stk-cs_scientist', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201-151\n\nالتحضير : ما يدقق على التأخير، بس لاحظت صار ينزعج منه في نص الترم تقريبًا، و يسمح بالميك أب\n\nطريقة الشرح : شرحه حلو و مفهوم و يوصل المعلومة، بس صوته هااادي و يجيب النوم 😆\n\nالكويزات : بعضها متوسطة و بعضها، آفرج كويزاتي أقل من درجات المياجر 😆\nعطانا ست كويزات و حذف أسوأ اثنين منهم\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالصوت: كلام واضح بس صوت هادي و منخفض\n\nإضافات : الدكتور طيب و متساعد و الابتسامة ما تفارق وجهه، جدًا حبيب الله يسعده\nالأوفيس أور ما يقصر معك، بالنسبة للتصحيح حسيت إنه ما يدف زي ما الطلاب وصفوا قبل، عندي احساس إن القسم شدد عليه لأنه صار يمشي على السلوشن\nيعني ممكن في كل ميجر دفني درجتين بس\nخويي مرة غاب عن كويز، راحله بالأوفيس أور قاله ليه غبت؟ خويي قال كنت نايم، ضحك الدكتور و عطاه الكويز (عدل فيه شوي) و اختبر و حضّره بعد\nجدًا متساعد مع الطلاب\n\nالقريد النهائي: B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437911-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/38", "user": "CS_Scientist", "ts": 1451838637000, "tid": 68383, "pn": 38}}]}', 1451838637000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10218-math201', 'stk-user10218', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 t-151\n\nالتحضير :\n\nيحضر نهاية الكلاس حتى لو كنت متأخر\nيسمح بالميك اب\n\nطريقة الشرح :\n\nسلايدات تحتوي على اسئله سهلة جدا الا ما ندر\n\nما يهيئك للمياجر أو الأختبار النهائي\n\nوشرحه عادي الى سيئ\n\nالكويزات :\n\nاعلى من مستوى شرحه (متوسطةالى صعبه)\n\nخذنا 6 كويزات وقال بيحذف أسوء كويزين\n\nالمياجر:\n\nكومن\n\nالفاينلات :\n\nكومن\n\nالقريد النهائي:\n\nC\n\nالصوت:\n\nواضح لكن ضعيف و هادئ جدا\n\nإضافات :\n\n* ما عطى ولا واحد فل في الكلاس ورك (صورة مرفقه )\n\n* التصحيح يعطيك حقك (عادي) + لو تراجع ممكن يغير درجتك\n\n* ما أنصح تنزل عنده 😦 لان ما في اي سبب يخليك تنزل عنده الا اذا الوقت مناسب !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437915-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/39", "user": "user10218", "ts": 1451840596000, "tid": 68383, "pn": 39}}]}', 1451840596000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-math201', 'stk-abdullah2015', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201 - Term171\nMATH202 - Term172\n\nالتحضير :\nنهاية الكلاس، وما يهتم للمتأخرين.\n\nطريقة الشرح :\nعن طريق السلايدات، ويحل المسائل على السبورة، طريقة شرحه ممتازة جدًا بالنسبة لي.\n\nالكويزات :\nمتوسطة الصعوبة في الغالب.\nيعطي 6 كويزات في السمستر ويحذف أسوأ كويزين.\n\nالمياجر:\nكومون\nتصحيحه للمياجر جدًا ممتاز، يعني إذا كان عندك أخطاء حسابية فقط وخطوات الحل تتجه إلى الحل الصحيح، راح تأخذ Partial Credit عالي على السؤال، لكن إذا حلك ما له علاقة بالحل الصحيح للسؤال راح يعطيك درجة نازلة على السؤال.\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nB+\n\nالصوت:\nمنخفض نوعًا ما، لكن مسموع.\n\nإضافات :\n1- بحكم إني درست عنده كورسين، ماث201 وماث202، بصراحة أحسه متمكن في ماث201 أكثر. هذا لا يعني أنه ما كان كويس في ماث202، ولكن كل ما في الأمر أنه متمكن من ماث201 أكثر.\n2- الميكب عنده سهالات، أيام ماث201 كان عنده 3 سكاشن وكنت أحضر مع سكشن ثاني كثير من المرات والوضع كان حبيب وعادي، أهم شيء بعد الكلاس تقول له إنك من سكشن ثاني وراح يحضرك.\n3- نظام الدكتور إن إذا ما كان عندك غيابات لك بونص، لكن اللي حصل في ماث201 وماث202 إن ما كان فيه مجال للبونص، لأن أفرج السكشن واصل للحد الأقصى.\n4- ينزل السلايدات اللي يشرح منها في البلاك بورد، بالإضافة إلى نوتات فيها ملخص للدروس.\n5- الدكتور ممتاز جدًا من ناحية الأخلاق والتعامل، والابتسامة ما تفارقه دائمًا 🙂 ، وكلمته الشهيرة إذا شاف مثال صعب:\n“Hopefully they will not put it in the exam”\n🙂\nختامًا أقول\nأنصح به 🙂\n\nبالتوفيق…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492845-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/41", "user": "Abdullah2015", "ts": 1526930053000, "tid": 68383, "pn": 41}}]}', 1526930053000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-math201', 'stk-guest', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت عنده مرة ثانية ماث 201 بعد ما اخذت معاه 102 لأن وقته كان يناسبني ، التصحيح ممتاز الكويزات كانت 4 وأخذ أحسن 2 الشرح ما كنت أركز معاه كثير الصراحة ، زي ماذكرت سابقا الرجال أخلاق و محترم و يعاملك بشكل راقي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316735-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/14", "user": "Guest", "ts": 1389107818000, "tid": 92906, "pn": 14}}, {"id": "stk-dr-m181956", "n": "Dr. Dhaker Kroumi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 191\nالتحضير : يقرا لاسماء واحيانا يسحب اخر الترم سوا سكب للتحضير.\nطريقة الشرح : ياخذ اقزامبل من الكتاب ويفصفصه ويتاكد من ان الكل فاهم ويروح للي بعده + شرحه متوسط موبذاك الزود.\nالكويزات : متوسطة الى سهلة + تصحيحة عسل جدا جدا …\nالمياجر:كومون\nالفاينلات :كومون\nالقريد النهائي:A+\nالصوت: عادي\nإضافات : يعني وش نقول وش نخلي, اخلاق توب التوب اسلوبه ممتاز متساعد جدا مع طلابه لدرجة يحل اولد اقزامز الاترام الي قبل ويرسلها بلاكبورد كانت حركة جدا مفيدة وساعدت طلاب كثير حتى الي مايدرسهم ايضا الاوفيس ارسله ايميل اذا الوقت مو مناسب لك يضبطك بوقت و يسوي قروب للطلاب للمساعدة… + ماث 201 ماتوقع ان فيه دكتور ممتاز في الشرح فيه لانه كورس مليان ويحتاج سلف ستدي وكذا. الصراحة اسطورة ولاتتردد وشكرا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521958-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhaker-kroumi/181956/3", "user": "Guest", "ts": 1589155073000, "tid": 181956, "pn": 3}}, {"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201- term 181\nبدون تقييم اسوء دكتور في حياتك تدرس عنده. تحسه ينتقم 50 سؤال واجب و تحل له ميجرين ثلاثه من الاولدات قبل كل ميجر و غير الهوموركات الكومن.\nالشرح يفتح الكمبيوتر و حرفيا يقعد يقرأ من الكمبيوتر الين مايخلص الكلاس.\nانسى يبتسم و انسى يبدل بدلته.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522574-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/17", "user": "Guest", "ts": 1591128170000, "tid": 176969, "pn": 17}}, {"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - 201\nمن فيديوهات الاونلاين!!!\n\nطريقة الشرح : الدكتور واضح انه فاهم المادة حيييييل زين، شرحه ممتاز، بس بعض الدروس يكون في دكتور ثاني يدرس لا اصيده .\nبس الرصاصي عيني عليه بااااااردة\n\nالصوت : صوته خفيف حيييييل، يعني اذا في ازعاج ببيتك ما بتسمعه كويس، وعنده مشكلة بخلي كل واحد يقراها الحين يركز فيها طول عمره الا وهي انه يعيد كل كلمتين كل شوي\n\nاضافات : النوتات حقته مفيده، لو تستخدمها تذاكر منها بتساعدك\n\nالتقييم: لما يكون هو اللي يشرح الدرس A\nلما خويه يشرح الدرس F لا اصيده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1526400-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/71", "user": "Guest", "ts": 1603743521000, "tid": 68569, "pn": 71}}, {"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم الاون لاين 201\nmath 201\n\nالتحضير: التحضيرتلقائي بالتيمز وما يدقق ابدا وتقدر تحضر اي شعبة عادي. التحضير(10/10).\n\nطريقة الشرح: يشرح على سلايداته الخاصة ويكون مافيها حلول ولا شي ويبدأ يحل الاسئله اللي فيها معانا وبعدين يرفع لنا السلايدات بالحلول وكل شي. الدكتور يجاوب على كل اسئلة الطلاب وما عنده مشكله يعيد الشرح من البداية. الشرح (10/9.5).\n\nالكويزات: اربع كوزات, اللي مذاكر بيحلها بسهولة والاسئلة كانت متوسطة. (في الكوزات يخلينا نفتح الكاميرات وهذي ميزة انا اشوفها).\n\nالمياجر: كومن.\n\nالفاينلات: كومن.\n\nالقريد النهائي: دكتور خيرول A+\n\nالصوت: واضح.\n\nاضافات: الدكتور اخلاق ومن افضل الدكاترة في التعامل ومسهل على الطلاب بشكل كبير لدرجة ان ما حسيت اني ادرس ماث وفي شي اسطوري سواه لنا جمع اسئلة اولد اقزام وحلها بشكل مرتب على كل الدروس وكانت جدا مفيدة لدرجة ان اللاختبار النهائي اغلب الافكار جات منها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527662-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/44", "user": "Guest", "ts": 1609938587000, "tid": 68383, "pn": 44}}, {"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 Term 201 (online)\n\nالشرح : ما اتوقع اللي يسويه اسمه شرح ممكن نسميه قراءة السلايدات. بالنسبة لقراءة السلايدات نعطيه سيء بعد للأسفز\n\nالتحضير : بعض المرات يحضر بداية المحاضرة لكن أغلب الأيام يحضر بنص المحاضرة.\n\nالكويزات : 6 كويزات واخذ افضل 5 بالنسبة لمستواها اول اثنين كانوا صعبين وبعدها يوم تحولت الكويزات الى Webassign صارت جدا سهلة والافرج دايما مرتفع.\n\nملاحضات عامة :\n- الدكتور صوته مزعج جدا ودايم يصارخ.\n- بعد كل دقيقة يقول clear شباب ولازم ترد عليه وتقول clear عشان يكمل شرح. “يعني بالكلاس الواحد يقولها اكثر من 20 مرة”\n- عن نفسي حضرت معه اول اسبوع وكملت الترم كله سيلف ستدي والحمدلله طلعنا بقريد عالي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527816-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/53", "user": "Guest", "ts": 1610450058000, "tid": 68471, "pn": 53}}]}', 1389107818000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.m-math201', 'stk-abdulrahman.m', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201-211\n\nالتحضير :\nنهاية الكلاس واحيانا بدايته، وما يهتم للمتأخرين ، لو تاخرت وكان ماخذ الحضور تروح له نهايه الكلاس ويحضرك.\n\nطريقة الشرح :\nعن طريق السلايدات، ويحل مسائل كثير وهذا الشي ممتاز ، السلبيه الوحيده ان صوته منخفض ويجيب النوم احيانا، لكن اذا ركزت معاه بتفهم شرحه ممتاز للامانه.\n\nالكويزات :\nسهله-متوسطة لو كنت مذاكر بتحلها.\nيعطي 6 كويزات في السمستر ويحذف أسوأ كويزين.\n\nالمياجر:\nMCQ\n\nالفاينلات :\nMCQ\n\nالقريد النهائي:\nA\n\nالصوت:\nمنخفض ويجيب النوم كما ذكرت.\n\nإضافات :\n-الدكتور جدا متعاون وخلوق ويستقبل اي سؤال مهما كان تافه ويجاوبك ويحاول يوصل لك المعلومه، حريص جدا على ان الطالب اللي يركز معاه يفهم وعادي يعيد ويكرر بالنقطة لين ماتفهم.\n-متعاون خارج الكلاس ايضا اذا ارسلت له تيمز يرد ويجاوبك على سؤالك واحيانا اذا كان سؤالك يحتاج شرح يتصل عليك ويشرحه لك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533295-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/45", "user": "Abdulrahman.m", "ts": 1641309605000, "tid": 68383, "pn": 45}}]}', 1641309605000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-math201', 'stk-user12137', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68383", "n": "Dr. Khairul Saleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201-222\n\nالتحضير :\nفي وسط ونهاية الكلاس واحيانا بدايته عن طريق الباركود، وما يهتم للمتأخرين ، لو تاخرت وكان ماخذ الحضور تروح له نهايه الكلاس ويحضرك.\n\nطريقة الشرح :\nعن طريق السلايدات، ويحل مسائل كثير وهذا الشي ممتاز ، السلبية الوحيده ان صوته منخفض ويجيب النوم احيانا، لكن اذا ركزت معاه بتفهم شرحه ممتاز للأمانة, وأحد إيجابياته أن عنده ملف كبير لمسائل ما قبل الميجر (من الكتاب واظن الاولدز) بنسختين محلول وغير محلول فيها أسئلة كثيرة وتجي في المياجر يعطيها لك لكي تحل منها تجهزا للميجر او الفاينل\n\nالكويزات :\nسهله-متوسطة لو كنت مذاكر بتحلها.\nيعطي 6 كويزات في السمستر ويحذف أسوأ كويزين ومرن جدا في تحديد أوقاتهم.\n\nالقريد النهائي:\nA\n\nالصوت:\nمثلما قال الي فوق منخفض ويجيب النوم.\n\nإضافات :\n-الدكتور حبيب وطيب وجدا متعاون ويستقبل اي سؤال مهما كان تافه ويجاوبك ويحاول يوصل لك المعلومه، حريص جدا على ان الطالب اللي يركز معاه يفهم وعادي يعيد ويكرر بالنقطة لين ماتفهم ويزبط الطلاب الي دائما يشاركوا معاه ويقعدوا قدام ولا يمسكوا الجوال.\n-الدكتور بيخليك تستعمل الجوال بس بيزعل وكذا يكسر الخاطر مادري كيف فلا تستعمله\n-يستاهل تنزل عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536920-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/khairul-saleh/68383/46", "user": "user12137", "ts": 1693316433000, "tid": 68383, "pn": 46}}]}', 1693316433000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-math201', 'stk-chemist', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68390", "n": "Dr. Ahmad Al-Dweik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اخذت معه math 201 ترم 101\n\nالتحضير:\nنادر مايحضر وان حضر حضر على ورقه حضر ربعك معك\n\nالشرح:\nطريقة شرحه سيئه جدا يشرح على نوتهpdf (كوبي بيست من الكتاب ) ويعرضه على البروجيكتر ولا ماتقدر تشوفه سواء\nكنت اول الفصل او اخره انا اعتقد في وجهة نظري لو يشرح على السبوره\nاحسن لانه قد شرح كذا مره على السبوره وكان شرحه كويس\n\nالصوت:\nلغته لك عليها بس مفهومه وصوته مسموع\n\nالكويزات:\nسهله واغلبها من النوت وامثله الكتاب بس في كويز واحد صعب\n\nالمياجر والفاينال:\nكومون\n\nاضافات:\n1) الدكتور متعاون واخلاقه عاليه ويدف في الكلاس ورك ودرجات الطلاب كان كويسه في الكلاس ورك\n2) انصحك تنزل معاه لان اغلب دكاترة 201 شرحهم لك عليه\n\nالقريد النهائي:\n1) في الشرح C\n2) في الاخلاق والتعاون A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p788237-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-dweik/68390/28", "user": "Chemist", "ts": 1297582706000, "tid": 68390, "pn": 28}}]}', 1297582706000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hassana-math201', 'stk-hassana', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68390", "n": "Dr. Ahmad Al-Dweik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "انا معه math 201 ترم 101التحضير:\nتقريبا السمستر كله ما حضر الا عشره كلاسات وعليهم درجات\nوالورقة تمر وانت تحضر\n\nالشرح:\nطريقة شرحه على نوتهpdf والامثله اللي في النوته مش محلوله\n\nيحل الامثلة مالت الكتاب على السبورة\nالصوت:\nصوته واطي مره\n\nالكويزات:\nكوزاته يعطيك اربعه اسئله ويقول لك حل سؤالين بس\nوغالبا تكوون ايزي ايه\n\nالمياجر والفاينال:\nكومون\n\nاضافات:\n1) الدكتور متعاون واخلاقه عاليه\n2) تساهله مع الطلاب يخلي الطلاب ماخذين راحتهم\nفتشوف الطلاب يجوون آآآخر عشر دقايق للتحضير وهذا يزعجني انا هع\n\nالقريد النهائي:\n1) A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p817295-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-al-dweik/68390/29", "user": "HassanA", "ts": 1300442014000, "tid": 68390, "pn": 29}}]}', 1300442014000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9133-math201', 'stk-user9133', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68391", "n": "Dr. Halic M", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ماث 201 ترم 121 وباعطيكم الزبدة\nالتحضيير : ورقه تمر على الطلاب\nالشرح : يشرح على السبورة ويكتب وفيه نوتات على الويب سي تس كويسه\nالمياجر : كومن\nالفاينلات : كومن\nالصوت : لا هو عالي ولا واطي\nالقريد النهائي: A\nاضافات\nالمدرس هذا في الشرح لاهو ممتاز ولا هو سيء والمادة اصلا self study\nلاكن في الكلاس وورك والله اعطاني درجه ما كنت احلم اني اوصلها ابدا ابدا (يعني ممتازة جدا)\nما عليك الا انك تحضر الكلاس حقه وتحاول انك ما تلعب اثنناء الكلاس وتحل اقل شيء نص الكوزات (الكوزات اون لان) وتحل الهوموركات وابشر باسعدك\nالمدرس اخلاق جدا وفوق ذا كل كوز (اون لان ) يخلي عليه من محاولتين الى ثلاث مرات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1149257-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/halic-m/68391/14", "user": "user9133", "ts": 1356689606000, "tid": 68391, "pn": 14}}]}', 1356689606000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7462-math201', 'stk-user7462', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68395", "n": "Dr. Mohammad Abu-Sbeih", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني ماث 201 ترم 121\n\nالتحضير : اغلب الايام يحضر بس مايخصم درجات معك لين الدي ان\nطريقة الشرح : يشغل نوت ع البور بوينت ويشرح واذا جينا مثال يحله على السبوره طريقه حلوه\nالكويزات : متوسطه اشوفها\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: اعطيه 7/10\nالصوت: واضح جدا\nإضافات : ببداية الكورس مدري المشكله مني والا منه ماكنت افهم معه ابد ابد بس تحديدا يوم وصلنا الانتقريشن مدرس قمممه في الشرح يدخل المعلومه غصبن عنك يعني اتوقع لو ياخذ 102 يصير ملك فيها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1173354-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-abu-sbeih/68395/37", "user": "user7462", "ts": 1359532808000, "tid": 68395, "pn": 37}}]}', 1359532808000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-don_corleone-math201', 'stk-don_corleone', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68405", "n": "Dr. Assane Lo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست معاه ماث 201 ترم 072\n\nمافي تحضير\n\nكويزاته … سهله\n\nالشرح … كان يحوووس شوي … يشرح فقره و يوقف يهنق\n\nالميجر … سهل\n\nالفاينل سهل\n\nاعطيه B+\n\nالصوت … فيه بحه … لكن راح تتعود عليه\n\nأنصح فيه إذا كانت الآختبارات ماهي Common\n\nهذا الكلام بالنسبة لـ 201\n\nما ادري عن 102 أو 101\n\nتحيتي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p355493-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/assane-lo/68405/8", "user": "Don_Corleone", "ts": 1232884455000, "tid": 68405, "pn": 8}}]}', 1232884455000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4459-math201', 'stk-user4459', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68405", "n": "Dr. Assane Lo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "091-201\n\nالتحضير :\n\nكان من اول الترم ما يحضر بس جاء في اخر 3 اسابيع وقام يمرر الورقه على الطلاب بس تقدر تحضر معاه اي وقت في اي كلاس , يعني في ناحية الحضور هو احسن واحد.\n\nطريقة الشرح :\n\nجيده اذا تنتبه معاه صح ان صوته مو مفهوم مره لكن راح تتعود عليه واحسن ما فيه انه يشرح لك كل حاجه في المنهج صغيره وكبيره .\n\nالكويزات :\n\nمتوسطه وكنت معاه في ماث 201 وكانت تدور حول افكار الاختبار.\n\nالمياجر والفاينلات :\n\nكومن\n\nالقريد النهائي:\n\na\n\nاضافات :\n\nالدكتور هذا طيب ومتساعد مررره وخاصه في التصحيح وفي الاكسيكيوزات وما الى ذلك, راح تستفيد من شرحه كثير اذا كنت مركز معاه وهو ما يقصر يقدم لك كل اللي يقدر عليه واخلاقه ممتازه ومحترم للغايه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p601192-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/assane-lo/68405/19", "user": "user4459", "ts": 1273195601000, "tid": 68405, "pn": 19}}]}', 1273195601000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-the_old-math201', 'stk-the_old', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68405", "n": "Dr. Assane Lo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه (summer 113)\n\nMATH 201\n\nالتحضير : نادراً.\n\nطريقة الشرح : ممتازة جداً و النوت إللي يكتبه في السبورة رهيب مرة.نصيحة حاول تكتب معاه.\n\nالكويزات : سهلة >>> من الشرح حقه لكن يغير الأرقام. (3 كويزات)\n\nالقريد النهائي: A\n\nالصوت: واطي بعض الشيء. لهجته بالنسبة لي واضحة.\n\nإضافات: بطيء بعض الشيء في الشرح و يعيد حتى الطلاب يفهموا, وهذي تعتبر ميزة حلوة. لكن في الصيف إللي أخذته معاه كان نفس الشيء (بطيء جداً) فكان يعطينا حصص زيادة في الليل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1078810-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/assane-lo/68405/39", "user": "the_old", "ts": 1344795504000, "tid": 68405, "pn": 39}}]}', 1344795504000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-f9hrb-math201', 'stk-f9hrb', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 211|Math-201\nالتحضير : ما يحضر لأنه يثق في الطلاب\nالشرح: أفضل دكتور في الشرح من يوم دخلت الجامعة\nالتصحيح: ممتاز و يعطي كل واحد حقه\nالتعامل: طيب جدًا و خلوق و يحاول يساعد الطلاب قد ما يقدر و يمزح في الكلاس عشان محد يطفش من الكلاس\nالصوت : جدا واضح\nالتقييم: A+++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531845-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/90", "user": "f9hrb", "ts": 1631556233000, "tid": 68406, "pn": 90}}]}', 1631556233000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-math201', 'stk-ahmed1', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68406", "n": "Dr. Bader Al-Humidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201- Term 211\nالتحضير :ما كان يحضر طول الترم\nالشرح : عنده نوتة على الون نوت يبدا بالكونسبت وبعدها يحل مسائل وشرحه جدا جدا ممتاز، غير انه في دروس كان يعلمنا طرق سريعة و غير موجودة الكتاب عشان تسهل عليك الحل ويعطينا عدد من المسائل من الكتاب نحلها و يسوي معانا هلب سشن قبل كل ميجر وتجي اسئلة نفس افكارها في الميجر 👏\nالكويزات :كويزاته كانت متوسطة الصعوبة ياخذ الاسئلة من الكتاب ويجيبها و تصحيحه حلو يعطيك فوق حقك حتى لو الجواب النهائي غلط، مع ذلك الافرج كان في الخمسين ودفنا في النهاية\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A++++++\nالصوت:واضح جدا\nإضافات : دكتور بدر جدا ممتاز ويتعب في الشرح والدليل على ذلك افرج كلاسه اللي هو الاعلى في الميجر الاول والثاني والدكتور اول مرة يدرس 201 في الجامعة :muscle: فإذا قدرت تنزل عنده فأنت محظوظ هالترم كان كلاسه المغرب ومع ذلك سكشنه مقفل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533113-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bader-al-humidi/68406/91", "user": "Ahmed1", "ts": 1639971707000, "tid": 68406, "pn": 91}}]}', 1639971707000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed3005-math201', 'stk-mohammed3005', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68413", "n": "Dr. Naseer-Eddine Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "من باب الإضافة:\n\n- الدكتور كويزاته ماتفيد الواحد بشكل كبير، أخر كويز قال لنا ذاكروا دروس (15.2 الى 15.7) بماث 201\n- لما جاء الكويز، قال لنا اختاروا سكشن أجيب لكم منه سؤال. والطلاب اختاروا 15.2 او 15.3 اظن\n\n1 ) السؤال الي جابه الدكتور يرتكز بشكل كبير على مفاهيم 102 ، حتى لما شرح خطوات الحل على السبورة كلها كانت تتضمن:\n- Integration by Parts\n- Substitution.\n- Improper Integral.\nوكل هذه الاشياء مو من ضمن الـ Learning outcomes تبع التشابتر 15 ، تقدر تقول أنه مؤلف الكتاب وضع السؤال من باب مراجعة المفاهيم حقت 102 لا اكثر .\n\n2) عموماً الي اريد اقوله انه السؤال مايقيس مدى فهمي للدروس حقت التشابتر ، كيف تبغا تقيس فهمي للدروس من 15.2 - 15.7 بسؤال من درس واحد فقط ؟!! ما استفدت شيء ولا عرفت اخطائي بالدروس الاخرى وين …. فما اشوفه شيء عادل من الدكتور بصراحة\n\nوللمعلومية هذا كان السؤال الوحيد بالكويز وعليه 10 درجات وwritten … الدكتور حاول يبرر لنفسه ويقول: مالي شغل، هذا السؤال موجود بدرس 15.2 او 15.3 ودامكم درستوه المفروض تعرفوا تحلوه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534260-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/naseer-eddine-tatar/68413/48", "user": "Mohammed3005", "ts": 1652221205000, "tid": 68413, "pn": 48}}]}', 1652221205000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sanad_hussein-math201', 'stk-sanad_hussein', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68418", "n": "Dr. Bilal Chanane", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "التحضير : ما فيه تحضير الا نادرا. خمس مرات في الترم تقريبا\nالشرح : يضيع وقت المحاضر على الكونسبت ويشرحها بضمير .نادرا حل الاسئلة\nاذا بتنزل معاه المادة بتصير سيلف ستدي\nعطانا كويزين اثنين طول السمستر واخر اسبوعين كل كلاس كويز واخذ احسن سته\nالتصحيح حقاني ويدف شوي + روحله الاوفيس وهو راح يضبطك ان شاء الله\n\nترم 132 ماث 201", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1414618-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/bilal-chanane/68418/35", "user": "sanad_hussein", "ts": 1416676668000, "tid": 68418, "pn": 35}}]}', 1416676668000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user7646-math201', 'stk-user7646', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68465", "n": "Dr. S. Messaoudi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "يسعدككم جميعا … انا درست عنده ماث 201 ترم 122 تقريبا …\n\nالتحضير :\nينادي في نهاية الكلاس … اوقات يركز انك ليت و اوقات ما يلاحظ\nطريقة الشرح :\nيكتب نوت … حاول تكتب معاه و تستفيد … بس مو مرتب مرة\nالكويزات :\nمتوسطة\nالمياجر:\nكومون\nالفاينلات :\nكومون\nالقريد النهائي:\nc+\nالصوت:\nواضح و عالي ماشا ءالله\nإضافات :\nامممم … الدكتور اخلاق … بس حاول تخليه يعرفك … عشان يكون معاك تمام\nالنوت حقه مو مرة مرتب … حاول تفهم معاه و تكتب … ولو ما قدرت مالك غير النوت الخارجي\nحاول تبحث عن افضل … واذا ما لقيت غيره … الدكتور متمكن … بس ركز معاه و الامور طيبة ان شاء الله", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1389185-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-messaoudi/68465/12", "user": "user7646", "ts": 1407755065000, "tid": 68465, "pn": 12}}]}', 1407755065000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10610-math201', 'stk-user10610', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - 181\nقفيني العسل النويتلا القشششششطة . دكتور أخلاق وحبيب والكلاس حقه خفيف وظريف , يشرح شوي وينكت مع الطلاب شوي لكن يمشي مع السيلابوس وما يتأخر. آخر كلاسين قبل الميجر تكون كلها اولد اقزام .\n\nفي الشرح يعتمد على نوتته ( بسييييطة جدا توصل لك المعلومة وكثر خيرها ) ولكن فيها اسئلة حلوة اذا بتتابع وتكتب معه . لكن لا ترمي نفسك للنوته فقط ! لازم تكمل شغل وحدك تحل اسئلة الكتاب وتبحث في النت عن المواضيع اللي ما فهمتها .\n\nالكوزات سهلة تميل الى المتوسط , يعني يمديك تجمع درجات بالراحه فيها .\n\nالخلاصة : اذا تبي دكتور حبيب جدا جدا وكوزاته يجي منها والشرح وسط , قفيني الخيار الأفضل . لكن لكن لكن !!! لازم تشتغل برا الكلاس زيادة على نفسك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1503896-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/24", "user": "user10610", "ts": 1545464505000, "tid": 92906, "pn": 24}}, {"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math-201-182\n\nالشرح : عنده نوته خاصه فيه لطيفة وخفيفة لكن مليانة اسئلة من شتى الأماكن, الأسئلة اللي في النوته يحلها في الكلاس ويعين شخص مسوؤل عن تصوير السبورة ويرسلها للقروب ( وبذلك نستنتج أن جوالك ممنوع تطلعه :slightly_frowning_face: ). الدكتور من زمن جدتي في الجامعة , كان في المجتمع ثم الاوريا ثم طلع الجبل , لذلك تشوفه فاهم طلاب الkfupm و حريص على إنك تحل اسئلة وتبدع في المياجر . وكذلك وقت الشرح يشرح لك شوي ثم يقول هذي لازم تجي وهذي طريقتها كذا في الميجر. وهكذا…\n\nالكوزات: قبل كل كوز يرسل لك اول اقزام و اسئلة كتاب على متيريال الكوز, والكوز يجي منها قص لزق. المشكلة أنه يقول لنا ترا الكوز بيجي منها وحنا ما نصدقه , وفعلا تجي منها 😁2:\n\nالتحضير: نار وشرار كل كلاس يحضر بنفسه نهاية الكلاس والتأخير خلال خمس دقايق تدخل مع محاظرة خفيفة , بعد 10 دقايق كنسل الفكرة أو قل له بدخل عشان استفيد بس.\n\nالصوت : وااااااضح جدا , جسلت في الزاوية او قدام او برا الكلاس بتسمعه معليك ( الدكتور اردني او فلسطيني ما أدري والله , لكن اللغة واللهجة وااااضحه) .\n\nإضافات : الدكتور حبييب جدا ويهمه إنك تشد حيلك , لذلك اذا رحلت له المكتب وكذا متفاااااااهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509342-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/47", "user": "user10610", "ts": 1556986568000, "tid": 68471, "pn": 47}}]}', 1545464505000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11848-math201', 'stk-user11848', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم : 191 - Math 201\n\nالتحضير : يوميا بالسيريال نمبر ومسموح تاخذ ميكب ب بشرط تبلغه بأي طريقة كانت , يكره التأخير جدا\n\nطريقة الشرح : من نوتاته وهي مشابهه للكتاب ويحل كم سؤال اولد اقزام\nالكويزات : من اسئلة الكتاب ومن النوتات\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: B+\n\nالصوت: واضح بس اللغة الانجليزية خذ وخل\n\nإضافات : الدكتور متعاون على الواتس , وأفضل شي انه يفهمك ويجهزك للميجر , أفضل كورس تاخذه معه هو ماث 201", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525996-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/52", "user": "user11848", "ts": 1601629403000, "tid": 68471, "pn": 52}}]}', 1601629403000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad_albori-math201', 'stk-ahmad_albori', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 Term 201 (online)\n\nالتحضير: في نصف الحصة بالأرقام التسلسلية\nطريقة الشرح: يشرح المفهوم أو النظرية على السريع ثم يحل عليها مسائل كثيرة\nالكويزات: مستوى الكويزات أشوفه متوسط نفس طريقة الأمثلة الي يحلها. كل أحد في الليل كويز MCQ أو Fill-in لكن كثير من الطلاب اشتكوا تعارض أوقات الكويزات مع اختبارات ثانية او مياجر في منتصف الترم فصار يختبرنا وقت الحصة\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: A\nالصوت: أحيانا غير مفهوم لأنه يتكلم بسرعة وإنجليزيته رايحة فيها لكن تعودت عليه\nإضافات:\n\nحضرت له help session واحد وكان مفيد حل فيه أسئلة اختبارات قديمة وشرح التركات الي غالبا تجي في الاختبارات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527879-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/54", "user": "Ahmad_Albori", "ts": 1610655797000, "tid": 68471, "pn": 54}}]}', 1610655797000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-kirsty13-math201', 'stk-kirsty13', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201 -TERM202 (ONLINE\n\nالتحضير: في نصف الحصة ينزل فورم لمدة دقيقة كحد اقصى ولو فاتك انسى تكلمه بيسفل فيك وبيحرجك ولا بيشيل الغياب\nطريقة الشرح: يشرح الكونسبت بثلاث دقايق ويبتل يحل مسائل لين نهاية الكلاس صوته عالي جدا مزعج يجيب الصداع عن نفسي ما استفدت من شرحه ولا قيد أنملة نهائيا ماناسبني غير أنه طيارة بالشرح\nالكويزات: مستوى الكويزات أشوفه متوسط مثل مستوى الاولد باي سكشن ، عطانا ٦ كويزات لضيق الوقت بعد قرار الملك بتقديم الاختبارات. الكويزات على كل ٣ دروس تقريبا واذا اصريتوا بالتاجيل يوافق .\nالمياجر: كومن\nالفاينلات: كومن\nالقريد النهائي: +B\nالصوت: عالي جدا مزعج مزعج يصارخ واكسنت مضروب ألف .\nإضافات: الشي الوحيد اللي صبرني عليه هو انه الترم عن بعد + كويزاته مستواها جميل ويساعدك انك تعرف وضعك قبل المد .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530372-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/55", "user": "Kirsty13", "ts": 1622911545000, "tid": 68471, "pn": 55}}]}', 1622911545000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-math201', 'stk-saleh_h', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68471", "n": "Dr. Yaqoub Shehadeh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201 - Term211\n\nالتحضير : يحضر نهاية المحاضرة عن طريق الSerial Number وشديد مرة بموضوع التأخير فلو تتأخر بيجيك تهزيء محترم.\nطريقة الشرح : بداية الكورس كان جيد بحكم سهولة المتيريال لكن بعد ميجر 1 صار ياكل الكلام اكل وسريع مرة ما تلحق معه ولا تفهم شيء.\nالكويزات : متوسطة، من الكتاب ويقولك تذاكر ال Suggested Problems بالسيلابس.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C+\nالصوت: مو واضح وتحتاج تجلس قدام عشان تسمع زين.\nإضافات : الدكتور الله يهديه شديد جدا بتعامله وما يتقبل المزح وطول الترم ما شفته يبتسم بالغلط، لكنه متفهم ومرن بالميك اب والكويزات بالاضافة ان عنده نوتة جيدة يشرح فيها أمثلة الكتاب وأمثلة ثانية تغطي تقريبا كل افكار المياجر، عموما الدكتور يعتبر خيار لا بأس به اذا ما لقيت لك دكتور ممتاز فـ تمشي حالك فيه لين الله يفرجها.\n\nوموفقين إن شاء الله…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533460-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yaqoub-shehadeh/68471/56", "user": "Saleh_H", "ts": 1642157834000, "tid": 68471, "pn": 56}}]}', 1642157834000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iahmed015-math201', 'stk-iahmed015', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68472", "n": "Dr. Stephen Binns", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "# term 121 - math 201\n\nالتحضير :\nالوضع فللللللّه ، يحضر نهاية الكلاس واسهل شيء تحضر اللي تبغى ، بس نهاية السمستر فهم عليها وصار يحضر بداية الكلاس واحد زودها دخل قبل الكلاس بخمسة دقايق، وانا كنت اسويها بس يومين حضر بدايته ورجع عادي !\n\nطريقة الشرح :\nالصراحة ماكنت افهم معاه شيء ، يشرح كونسبتس ومايحل مسائل غير ناااادراً .\n# يشوفك تحل الهوموورك بالكلاس ويخليك.\n# يشوفك تمسك الجوال ويخليك.\nيعني عادي تسحب عليه وتسوي اللي تبغى.\n\nالكويزات :\n3 اختبارات، قبل الميجر الاول وقبل الثاني و قبل الفاينل ( الكويز الواحد يشمل الماتيريال حق الاختبار )\n\nالمياجر:\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي:\nB\n\nالصوت:\nواضح والاكسنت حقه بطل .\n\nإضافات :\n- يعطيك حقّك بالتصحيح بدون تعقيد.\n- الدكتور طيب وخلوق بالمكتب جداً وفاهم الكونسبتس جداً بس تحسه مو متعود على ملعنة الجامعة.\n- اذا انت انسان تبغى الحضور فلّه وتذاكر لحالك نزّل عنده ، اذا تبغى شرح دور غيره.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164018-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stephen-binns/68472/40", "user": "iAhmed015", "ts": 1358158656000, "tid": 68472, "pn": 40}}]}', 1358158656000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mjehad-math201', 'stk-mjehad', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68472", "n": "Dr. Stephen Binns", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201- Term 121\n\nالتحضير : يوميا ولكن التحضير سهالات يحضر بالارقام وتقدر تحضر 10 وياك\n\nطريقة الشرح: يكتب نوت علاسبورة ولكنه مخربط ومو مرتب وشرحه سيء يضيع اكثر من نص الحصة وهو يعلمك شلون اشتق القانون وما يحل مسائل كثيير\n\nالكويزات : متوسطة كائلة للسهولة\n\nالمياجر: كومون\n\nالفاينلات: كومون\n\nالقريد النهائي: C+\n\nالصوت : عادي\n\nاضافات: الدكتور طيب واخلاقه حلوة مع الطلاب ولكن شرحه انا بالنسبة لي كان سيء\nأنزل كورس ماث اخذته مان عند هالطيييييييييب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1393570-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stephen-binns/68472/49", "user": "mjehad", "ts": 1409125493000, "tid": 68472, "pn": 49}}]}', 1409125493000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4529-math201', 'stk-user4529', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68565", "n": "Dr. Muhammad Aslam Chaudhry", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "شودري أخذت معاه 201 في 083\n\nالكلاس وورك ماله دخل بالمياجر\nلكن طريقته في الكلاس وورك ما عجبتني\nكان على الحضور 5 % لكن الميزة انك تجي في أي وقت تحضر يعني لو جيت وباقي على الكلاس دقيقة يحضرك و في شباب استغلوا الحركة و كل يوم تأخير\nو على الهوموورك 5 %\nو على الكويزات 10 % طبعا يسوي كوزين في الصيف و في السمستر العادي يسوي خمس كوزات\nو يقسمها على على العشرة\n\nبخصوص شرحه حقيقة هو أفضل دكتور للماث 201 حاليا متمكن من المادة و لديه نوت جيد\n\nو الميزة أنه هو الكردينتر حق الماث 201 فالمراجعة اللي يسويها قبل الميجر مفيدة جدا\n\nلكن حقيقة لم اعتمد على شرحه كثير و خرجت من المادة بقريد زين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p454664-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-aslam-chaudhry/68565/24", "user": "user4529", "ts": 1252105921000, "tid": 68565, "pn": 24}}]}', 1252105921000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-medoalkebsi-math201', 'stk-medoalkebsi', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 132(حاليا) … ماث 201\n\nالتحضير :\nاول اسبوع ماحضر شي , بعدين كان يحضر في اخر 10 دقايق من الكلاس…متساهل جدى في التأخير ولا يتكلم ابدا مع المتأخرين\nطريقة الشرح : طريقه بالشرح نسبيا جيده…يهتم بالكونسبت كثييييييييييييييييييييييييييييييير.\nيعطي امثله من اسئله الكتاب وكلها سهله , اوقات يعطي اسئله من الاولد اقزامز بس قلييييييييييييل …\n\nالكويزات :\nاشوف انها سهله جدآ\n\nالمياجر:\nتصحيحه للرتن بالملي يعطيك حقك , نفس الي في الكي سلوشن تاخذه\n\nالفاينلات :\nباقي ما اختبرنا الفاينل\n\nالقريد النهائي:\nb+ ( هذا تقييمي للدكتور وليس درجتي )\n\nالصوت:\nصوته واطي وهذا اكثر شي يقهرني , احب المدرس الي صوته عالي ووضاح بحيث انه يجذبك للشرح .\n\nإضافات :\nكورس 201 اشوف انه سلف ستدي مايحتاج مدرس يشرح , يحتاج واحد يصحح بسهالات ويعطي درجات.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1350532-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/54", "user": "Medoalkebsi", "ts": 1397119726000, "tid": 68569, "pn": 54}}]}', 1397119726000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-math201', 'stk-user8581', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math201 - term 141\n\nالتحضير :\nنهاية الكلاس بالاسماء … في اول كم اسبوع يمكن يتغاضى عن اللعب بالجوال او النوم في الكلاس لكن بعدها راح يعتبرك ابسنت وهو متعاون يعني لو عندك شيئ تقدر تستأذن وتطلع من الكلاس + يقبل بالميك اب\n\nطريقة الشرح :\nعلى السبورة ومن نوتته وهي مبسطة بشكل كبير ولو تركز معاه في الكلاس راح ترتاح لأن يركز على الكونسبت ويحل اسئلة وامثلة بعدد معقول خصوصا في ماتيريال الميجر الأول والثاني والي يبقى عليك بس هو اسئلة الكتاب الي يحددها في نهاية كل درس\nواذا فيه قوانين يشرح لك من وين جات واذا عندك اي سؤال يتقبله بصدر رحب …\nلكن الي يعيبه صوت شوي منخفض فخلك قدام لأنك لو صرت ورى ماراح تسمعه ويمكن تنام\n\nالكويزات : سهلة او متوسطة المستوى احيانا يجيب نفس الاسئلة الي في النوتة او الي محددها من اسئلة الكتاب اللهم اختلاف بسيط\n\nالمياجر & الفاينلات\n:كومون والصراحة بخصوص التصحيح هو مب مثل بعض الدكاترة الي يدفون ويتغاضون عن بعض الأشياء لكن ماهو بالشديد في التصحيح مثل مايصوره البعض وفيه اكثر من كويز هذا السمستر مشى لنا اشياء كثيرة ( يمكن غير نظامه هذا السمستر ) لكن بشكل عام حقاني ومايزيدك وفي نفس الوقت ما يظلمك …\n\nالقريد النهائي: b+\n\nالصوت: ضعيف وهذا الشي الي مخرب عليه\n\nإضافات :\nاشوفه ممتاز لكن في 201 لو حصلت واحد غيره يدف في التصحيح كثير حتى لو ما كان شريح فسجل معاه لأن هذي الكورس اغلب اختباراته رتين\n\nكويزاته\nhttp://aisys.kfupm.edu.sa/MATH_ONLY/Search_Courses1.aspx\n\nنوتته لـ math201\nhttps://www.mediafire.com/?hxofm5qqju9up9k", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420445-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/55", "user": "user8581", "ts": 1421633345000, "tid": 68569, "pn": 55}}]}', 1421633345000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_91110-math201', 'stk-_91110', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 - 162\n\nالتحضير :\nيوميا , متساهل جدا في التأخير\n\nطريقة الشرح :\nيكتب على السبوره من النوت حقه ( النوت جدا ممتاز ويغني عن الكتااب في الشرح ) ويحل أمثلة متدرجة في الصعوبة\n\nالكويزات :\nمتسوطة مائل إلى السهولة , غطي أفكار الكتاب وأضمن لك فل مارك\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت:\nهذي مشكلت الدكتور 🙂 و صوته ضعيف لكن بعد فترهراح تتعود عليه\n\nإضافات :\nالدتور حبيب وينكت في الكلاس بعض الأحيان\nحبيب ومتعاون جدا\nاشوفه عادل في التصحيح وبعض الأحيان يتساهل\nصراحه شرحه بالنسبة لي جدا رائع وما احتجت ارجع للكتاب عشان أفهم طول الترم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474177-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/60", "user": "_91110", "ts": 1496154611000, "tid": 68569, "pn": 60}}]}', 1496154611000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10879-math201', 'stk-user10879', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "حضرت معاه ليسنير في 162 ماث 201\n\nالشرح لايعلى عليه من النوت مايحتاج تكتب وراه ولاشي بس ركز\n\nالتحضير نهاية كل كلاس ولايهتم للمتاخرين\nبس انتبه تمسك جوالك لانك بتصيرر ابسنت علطول\n\nالكويزات متوسطة\n\nالتصحيح مدري\n\nالصوت ضعيف لدرجة اني اقعد قدام وجهه واحيانا يروح علي كلام\n\nاذا بتنزل معاه يا تكون قبلها فاضي او الحاضرة اللي قبلها في نفس المبنى عشان تجلس قدام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479907-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/62", "user": "user10879", "ts": 1504958602000, "tid": 68569, "pn": 62}}]}', 1504958602000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-monster77-math201', 'stk-monster77', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201\nTERM : 172\nبنود التقييم :\n\nالتحضير : يومي عن طريق الاسماء, ماعنده مشكلة بالتأخير اذا ماكان اكثر من 10 دقايق , يسمح بالميك اب حتى طوال الترم\nطريقة الشرح : ممتازة , يهتم بالكونسبت بشكل كبير اكثر من اهتمامة بالمسائل , احيانا ياخذ نص المحاضرة على الكونسبت , لكن بشكل عام الشرح ممتاز\nالكويزات : 4 كويزات , متوسطة ويجيب مشابهة لكويزاته القديمة\nالمياجر: كومون\nالفاينلات : كومون\nالقريد النهائي: a+\nالصوت: واطي لكن لو تركز يمديك تسمعه\nإضافات :\n\nنظام الكلاس وورك عنده\n8% على الكويزات , كل كويز 2%\n2% على الحضور , كل غياب خصم 0.25%\nنوتة الدكتور ممتازة لفهم المنهج لكن كـ أسئلة لاتعتمد عليها , لان معظمها بسيطة واسئلة المياجر اصعب . ف ذاكر منها واذا جيت تحل شوف لك اولد اكزام او بعض اسئلة الكتاب\n\nبالنسبة للتصحيح , اشوفه عادل , يعني مستحيل يظلمك و قد يمشي لك كم حاجة , والدكتور يهتم بالخطوات, يعني سؤال عليه 10 بوينتس وتختصر الحل بخطوتين , ممكن يعطيك 5 او 6 من 10\n\nاذا مايهمك التصحيح ويهمك الشرح فالدكتور مناسب, اذا يهمك التصحيح شوف غيره", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491982-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/64", "user": "monster77", "ts": 1525812279000, "tid": 68569, "pn": 64}}]}', 1525812279000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_alwaleed1-math201', 'stk-abo_alwaleed1', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201\nTERM : 172\nبنود التقييم :\n\nالتحضير : يوميًا عن طريق الأسماء ، التأخير ما يقول شيء عليه ، يخصم ربع درجة على كل غياب .\nطريقة الشرح : ممتازة جدًا ، وعنده مذكرة NOTE فيها كل الشرح موجود ، يعني ما يحتاج تكتب معه .\nالكويزات : 4 اختبارات ، نفس الأفكار في اختباراته السابقة بالضبط .\nالقريد النهائي: A++\nالصوت: هذه مشكلته الوحيدة ، اقعد قدام وأمورك تمام\nإضافات :\n\nالتصحيح أشوفه عادل ومرات ممتاز ، أنصح فيه وبشدة ، ممكن البعض ما يعجبه تصحيحه .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1497392-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/65", "user": "abo_alwaleed1", "ts": 1533806939000, "tid": 68569, "pn": 65}}]}', 1533806939000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammad2-math201', 'stk-mohammad2', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201\nTERM 173\nبنود التقييم :\n\nالتحضير :\n-يحضر يومياً بعد إنتهاء كل كلاس.\n-يغيب الطالب اللي يشوفه جالس على جواله\n-مايقولك شي اذا دخلت بعد بداية الكلاس بعشر دقائق او حولها\n- يخلي درجة التحضير كدرجه لكويز خامس ( مثلاً : اذا ماغبت ولامره ، يعطيك درجة كويز كامله )\nطريقة الشرح : شريح ماشاء الله عليه ، عنده نوته يجيبها معه ويكتبها ويشرحها على السبوره ويطول على الكونسبت عشان ينفهم صح بعدها يدخل على الامثله ( تكون بالتدريج من السهل الى الصعب ).\nنوتته ينزلها في البلاك بورد بعد إنتهاء كل درس.\nوموجوده بعد كامله في KFUPM RESOURCES .\nالكويزات : اربع كويزات متوسطه ودائماً يجيب نفس طريقة أسئلة كويزاته القديمة\nالمياجر: common\nالفاينلات : common ، هو كان كوردنيتر الكورس ، كانت الاسئله معظمها سهل وغالباً تكون أفكار أساسيه.\nالقريد النهائي: A+\nالصوت: يتكلم غالباً انقليزي ونطقه ممتاز لكن صوته ضعيف جداً جداً، لذلك لازم تحرص دائماً انك تكون قدام عشان ماتتعب مع هذه المشكله.\nإضافات :\nالدكتور إبراهيم حسب ماسمعت وحسب ماشفت من أفضل دكاترة القسم شرحاً ( خصوصاً Math 201 ) واخلاقاً أيضاً ، فالافضل لك تسجل عنده اذا قدرت.\nبالنسبه للتصحيح ، انا سمعت ناس كثير يقولون ان تصحيحه شديد ، لكن انا مالاحظت ذلك لان فيه طلاب يحل سؤال من ٣ خطوات وهو يتطلب اكثر او يجيب طريقه لحل السؤال من رأسه ويطلع الجواب النهائي بالصدفة صح ويزعل اذا نقص عليه الدكتور.\nلذلك افضل طريقه لحل سؤال هي ( مثل ماقال لنا ) :\nwhat comes in your mind, write it !\n( اذا انت متأكد ان طريقتك صحيحه ، اكتب جميع الخطوات حتى لو انها تافهه او طويله )\nوتراه يمشّي (بعض الاحيان يعطيك اكثر من حقك لكن بشي بسيط)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498100-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/66", "user": "Mohammad2", "ts": 1535173770000, "tid": 68569, "pn": 66}}]}', 1535173770000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hassan_al_bin_saad-math201', 'stk-hassan_al_bin_saad', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201\nTerm:182\nالتحضير :يقبل بالميك اب + كان يحضر قبل نهاية الكلاس ب10 دقائق لكن الطلاب صاروا يتأخرون ف صار يحضر في اول 10 دقائق+اذا استخدمت الجوال على طول انت غايب + يخصم من اول غياب 0.25%.\nطريقة الشرح :ما ظن انك راح تلاقي دكتور يشرح 201 افضل من الرصاصي, متمكن من المادة.\nالكويزات :الطلاب يعتبرونها صعبة والافرج نازل نوعا ما, لكن بالنسبة لي اذاكر من النوت اللي يرفعها على البلاك بورد واجيب درجات ممتازة.\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي:A++\nالصوت:ضعيف مائل للمتوسط, هذا عيب الرصاصي الوحيد(بالنسبة لي) ,لذلك حاول تجي مبكر وتجلس قدام.\nاضافات :الدكتور ما يتفوت خصوصا لماث 201,بالنسبة لي راح انزل عنده في اي كورس يتواجد فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508924-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/67", "user": "Hassan_al_bin_saad", "ts": 1556101104000, "tid": 68569, "pn": 67}}]}', 1556101104000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sake-math201', 'stk-sake', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - 192\nالتحضير : اخر المحاضرة عن طريق الاسامي ونفس الشي بفترة الاونلاين ، الكويز الخامس عنده يعتمد على حضورك ، مع كل غياب ينخصم عليك 0.25 درجة ولما يشوفك قاعد على جوالك على طول غايب\n\nطريقة الشرح : اسطورية جدا ، يشرح عن طريق نوتاته الاسطورية اللي يرفعها اول بأول ، مايمشي الى النقطة اللي بعدها الا لما يتأكد انه الكل فاهم ، خطه وحله ورسمه مرتب وجميل وواضح.\n\nالكويزات ، متوسطة مائلة للصعوبة ، تحتاج تحل كويزات كثيرة من كويزاته القديمة عشان تضمن تجيب كامل ، اما بخصوص فترة الاونلاي فكانت سهلة جدا وكلها بيسك ودايركت من النوتات\n\nالصوت : ضعيف ، هذا عيب الدكتور الوحيد ، ولكن مع الوقت اعتدت على صوته وصار واضح\n\nاضافات : الدكتور تقريبا هو الافضل بـ MATH 201 ، ولكن تحصله يدرس كورسات ثانية مثل 101 ، اذا حصلته يدرسها لاتتردد ابدا ، انا تحسفت كثيرا اني ماسجلت عنده لانه حرفيا تطلع من المحاضرة فاااهم!! من افضل واروع دكاترة قسم الرياضيات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521842-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/69", "user": "SAKE", "ts": 1588880205000, "tid": 68569, "pn": 69}}]}', 1588880205000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11861-math201', 'stk-user11861', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 192 IBRAHIM AL-RASASI\nالمادة :math 201\nالتحضير : التحضير ب الاسامي نهاية الكلاس\n\nطريقة الشرح : يجي الكلاس محضر الشرح من النوتات حقينه ويبتدي شرح وشرحه صراحة ممتاز بس احسه زي اللي حافظ اللي بيشرحه م يترجل ف الشرح\nالكويزات : كان بيعطينا ٤ كويزات بس مامدا الا يعطينا كويز واحد وصراحة كان صعب شوي\nالمياجر: كومن\nالفاينلات :كومن\n\nالقريد النهائي: A\n\nالصوت: الرصاصي هذي مشكلته الوحيده انه صوته خفيف ف يعني لو كنت جالس ورا او كان الكلاس ازعاج انسى انك تسمع شي\n\nإضافات : الدكتور حبيب وطيب لو احتجت انك تغيب وكلمته يتفهم الوضع عادي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521944-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/70", "user": "user11861", "ts": 1589149523000, "tid": 68569, "pn": 70}}]}', 1589149523000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-math201', 'stk-user11372', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68569", "n": "Dr. Ibrahim Al-Rasasi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - TERM 201 ترم الكورونا اونلاين\n\nالتحضير :\nيحضر الدكتور عن طريق مايكروسوفت تيمز نهاية الكلاس يحفظ الحاضرين عن طريق تيمز ينزل الملف\nالدكتور يسمح بالتاخير عادي\n\nطريقة الشرح : طريقة ممتازة صحيح احيانا يجيك النوم لكن لو تركز معاه بتاخذ قريدات طيبة وبتفهم\nيبدا بشرح الكونسبت ثم يحل كذا مسألة موجودة بالنوت الخاصة فيه\nطبعا النوتات حقته هي افضل نوتة تقريبا لماث 201 فا حتى لو انت مو طالب معاه انصحك تذاكر منها\n\nالكويزات :\nاختبرنا تقريبا 5 كويزات الافرجات تبع كلاساته كانت دمار مو بسبب صعوبة الاسئلة كانت تجي من النوتة اغلب افكارها\nبس كان الافرج دمار وزاد سكشنا تقريبا حول 10 بوينت لكل طالب نهاية بسبب الافرج كان نازل مره\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: في الاونلاين كان واضح جدا في الحضوري سمعت طلاب انه منخفض ولازم تجلس قدام له\n\nإضافات : الدكتور فيه شي صراحة ما اعتبره ميزة ولا سلبية\nاحيانا مايقدر يخلص الدرس في نفس الوقت المحدد فايضطر ينزل تسجيل ويقول شوفوه لحالكم وهذا شي كان ياخذ وقت صراحة انك تشوف فيديو نص ساعة زيادة عن محاضراته.\nالكويزات بداية الفصل كانت الساعة 10 بالليل بس بعدين كلمناه وصارت الصباح في نفس وقت الكلاس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527889-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-al-rasasi/68569/73", "user": "user11372", "ts": 1610701633000, "tid": 68569, "pn": 73}}]}', 1610701633000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8890-math201', 'stk-user8890', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "نزلت معاه ترم 141 - ماث 201 .\n\nالدكتور ما كان يحضر أبدا لكن يقول اني اعرف من يحضر ومن يغيب.\n\nعطانا 5 كوزات أظن، اثنين منهم كانو بكلاس واحد، واخذ افضل 4 ،، ما زاد الطلاب أي درجة بحكم الأفرج العالي لكن قالنا ببداية الترم أنا أخلي الافرج حقي 30 بالكلاس وورك وهذا شيء كويس… عموما كوزاته كانت سهلة ومن الكتاب.\n\nشرحه أشوفه عادي وسريع جدا وملخبط , اذكر بدينا بماتيريال ميجر تو قبل ميجر ون بأسبوع وشوي وكان يقولنا بخلص بدري من ماتيريال الميجر عشان تذاكرون واعطيكم هيلب سيشن لكن ما عطانا شيء. عموما شرحه عادي وشايف نفسه أنه أعلى من الكورس هذا وذكر لنا ان الطلاب يقولون عنه بالمنتدى ما يعرف يشرح وان الكورس هذا حق High School بـ ألمانيا وانا بروفيسور - وهو مب درجته العلمية أستاذ ، أظنه استاذ مشارك - يعني شرحي له كويس. غاب عنا وألغى تقريبا 6 كلاسات.\n\nبالنسبة للتصحيح، الدكتور يحب يكون أنه أعلى أفرج بين السكاشن وذكر لنا انه الترم الماضي كان أعلى سكشن وكذا فـ بميجر ون دفّنا دف وكان الافرج عالي اما بالنسبة لميجر تو صحح بالملي على المانوال سولوشن لكن بالفاينال عطانا فوق حقنا بكثير برضه. انصحك تراجع وراه اذكر مخطي كان باختباراتي بـ فوق 7 نقاط.\n\nعموما الكورس يحتاج اولد اقزامز واليوتيوب ما يقصر بالشروحات، الدكتور خيار جيّد بالنسبة للتصحيح يعني أفضل من غيره لكن لو حصلتو عادل خلف الله أتوقع أفضل.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451674-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/23", "user": "user8890", "ts": 1465851671000, "tid": 68571, "pn": 23}}]}', 1465851671000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jstnawwaf-math201', 'stk-jstnawwaf', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201 term 153\nالتحضير: نادر يحضر\nطريقة الشرح: سريع وإذا ما حضرت بأول ٥ دقايق راح عليك الكونسيبت، الشرح يعجبني لأنه سريع ودائما ما يذكر أمثلة مثلا قال بأول كلاس أن الحياة ما فيها متغير واحد مثل لمن تتزوج وحدة عندك عامل الجمال والدين والنسب والمال ولذلك 201 كورس واقعي أكثر من 101 و 102 ودائما ما يبدأ الأمثلة بـ: تخيل أنت وزوجتك بهذا الموقف… يخلي الحصة خفيفة بالرغم أنه فيه الصيف الحصة ساعة كاملة\nالكويزات: عطانا ٦ وأخذ أفضل ٥، +ترا كلها من الكتاب يعني تحل أسئلة الكتاب قبل تضمن تأخذ فل، + في النهاية أفرج الكلاس وورك خلاه على الليميت ٣٠ من ٤٠.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+, اللي قلل من القريد أن صعب تكتب معه نوت، كنت الطالب الوحيد اللي يكتب معه وواجهت صعوبة بالكتابة، +شرحه السريع ممكن ما يناسب كل الطلاب.\nالصوت: واضح جدا\nإضافات: Math201 كورس سهل وممتع وقريب من الواقع، أنصح بحل أسئلة الكتاب بفهم +فيه فيديوهات باليوتيوب بقناة patrickJMT وأيضا Krista King و Professor Leonard.\nفي الجامعة عموما إذا تكبرت على كورس بتاكلها على رأسك لذلك عطه حقه واجتهد وربي يوفق الجميع.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457215-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/26", "user": "jstNawwaf", "ts": 1473292837000, "tid": 68571, "pn": 26}}]}', 1473292837000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-krooom-math201', 'stk-krooom', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201 term 161\nالتحضير: نادر يحضرمرتين او 3 طول الفصل لكنه يحطك براسه ويخسف بالكلاس وررك اذا حطك براسه فلا تخليه يحطك براسه\nطريقة الشرح: سريع وإذا ما حضرت بأول ٥ دقايق راح عليك الكونسيبت، الشرح ما يعجبني لأنه سريع ويصارخ وهو يشرح (فعلا يصارخ كنت احيانا اصدع واسحب على الكلاس) ودائما ما يذكر أمثلة مثلا قال بأول كلاس أن الحياة ما فيها متغير واحد مثل لمن تتزوج وحدة عندك عامل الجمال والدين والنسب والمال ولذلك 201 كورس واقعي أكثر من 101 و 102 ودائما ما يبدأ الأمثلة بـ: تخيل أنت وزوجتك بهذا الموقف… يخلي الحصة خفيفة وممتعة وشرحه مب ذاك الزود لكن المادة كانت كريهة شوية(مدري ليه ما حبيتها) ولكن الاستاذ ما يكرف ويعطيك اللي يخليك تعدي والباقي عليك\n\nالكويزات: عطانا ٦ وأخذ أفضل ٥، +ترا كلها من الكتاب يعني تحل أسئلة الكتاب قبل تضمن تأخذ فل، + في النهاية أفرج الكلاس وورك خلاه على الليميت ٣٠ من ٤٠.\nالمياجر: كومن وتصحييحه بطللللللللللل\n\nالفاينلات : كومن (في 161 بما ان المياجر كانت دمار اغلب الاساتذة حاولوا يدفون ويخلون الافرج حول ال95 فكانوا متساهلين من ضمنهم استاذنا شفنا دف مب صاحي )\n\nالقريد النهائي: B+, اللي قلل من القريد أن صعب تكتب معه نوت، كنت الطالب الوحيد اللي يكتب معه وواجهت صعوبة بالكتابة، +شرحه السريع والصوت العالي ممكن ما يناسب كل الطلاب.\nالصوت: واضح جدا\nإضافات: اذا تبي استاذ ما يكرف ويسامح على التاخير واحيانا الغياب ويخلي الحصة جدا خفيفة بخفة دمه وان الدرجة اللي بتاخذها تعتمد على مجهودك فانصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467080-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/27", "user": "Krooom", "ts": 1485514677000, "tid": 68571, "pn": 27}}]}', 1485514677000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mfamss-math201', 'stk-mfamss', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 161- Math 201\n\nالتحضير : مايحضر الا نادراً طول السمستر يمكن مرتين او ثلاث بس … لا تمصخها واجد في الغياب لأنه يحفظ الاشكال واذا جيت في المياجر والكويزات يقولك احذر من الـ DN…نهاية السمستر قال الي ماراح يحضر آخر اسبوع ماراح اساعده في الكلاس وورك وتقريبا آخر حصة حضر فيها والي حضروا زودهم اكثر من غيرهم في الكلاس وورك\n\nطريقة الشرح :\n* يشرح سريع سريع بداية الحصة وبعدين يكتب أمثلة ويحلها\n*ويكتب مثال صعب ويخلينا خمس دقايق نحله في مجموعات طبعا يكون المثال صعب علينا كونه ماشرح عدل وبعدين لما تذاكر وترجع تحل نفس المثال تشوفه اسهل من السهل\n* شرحه سيء كونه غير مرتب ولا عنده شيء يمشي عليه لا نوت ولا كتاب يجي حافظ الكونسبت ويشرحها وعادي عنده انه يشرح درسين ثلاثة في حصة\n* خطه جدا جدا سيء وشرحه على السبورة خرايط يكتب يمين وشوي تشوفه يسار وشوي فوق وشوي تحت\n\nهذا نموذج لخطة http://aisys.kfupm.edu.sa/WBKFUPM/Departments/MATH/153/coursefile_data/MATH201_153_01_E2.PDF\n\nالكويزات :6 كوزات واخذ افضل خمسة… بعضها سهلة نوعا ما وبعضها صعبة ماتقدر تحلها … يجي يقولك طلع ورقة ويكتب سؤال على السبورة وحله … في كويز ماكان واضح على اي درس هو كلموه الطلاب وحدد الدرس واجل الكويز لكن جاب سؤال الكويز عن درس ثاني 🚬\n\nالمياجر: كون … رتن …في 161 الكوردنيتر لعب فينا الميجر الاول كان طويل جدا مايمديك تحله وماكان شامل كل الكونسبت كان مركز على اشيا معينة المدرس كان شاغلنا على الرسم والسمتري وماحا منها شي …والميجر الثاني اقصر لكن نفس الحكاية كان مركز على كم كونسبت وناسي الباقي\n\nالفاينلات :كومن\n* الفاينل من 140\n* سبعة اسئلة رتن على دروس مابعد الميجر الثاني عليها 70\n* 14 سؤال اختيارات اسئلة مخلوطة لكن اكثر شي من الدروس الاولى عليها 70\nالقريد النهائي: C+\nالصوت:واضح بالانجليزي مستحيل يتكلم عربي ولا يسمح للطلاب يتكلموا عربي\nإضافات :\n*المدرس يدف في الدرجات ومتساهل جدا في التصحيح\n*زودنا في الكلاس وورك حول 10 الى 13 بوينت\n*نصيحة لا تترك سؤال فاضي لان يعطي درجة على اي شي\n\nتصحيحه ممتاز\nيزيد في الكلاس وورك\nمايحضر\n\nشرحه سيء\nماتقدر تكتب وراه\n\nاذا كنت تحب السيلف ستدي فهو خيار جيد ذاكر صح وحضر قبل الدرس وراجع بعده وراح تاخذ فوق الـ B بالراحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467120-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/28", "user": "MFAMSS", "ts": 1485550427000, "tid": 68571, "pn": 28}}]}', 1485550427000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10932-math201', 'stk-user10932', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - TERM172\nالتحضير : مايحضر أبد ، لكن ينبه من وقت لآخر على أهمية الحضور والتركيز معاه .\nطريقة الشرح : اول شيء يشرح الدرس نظريا ثم يكمل على السبورة ، عيبه الوحيد هو خطه وعدم ترتيب التمارين على السبورة .\nالكويزات : سهلة ،اغلبها يجيبها من مخه ، وأحيانا يفتح الكتاب ويختار سؤال .\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A\nالصوت: عالي وواضح ماشاء الله .\nإضافات : الدكتور جدا حبيب ومتساهل بالتصحيح ، ركز معاه باللكتشر وفالك A+.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498782-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/29", "user": "user10932", "ts": 1536066698000, "tid": 68571, "pn": 29}}]}', 1536066698000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-math201', 'stk-bader_alqahtani', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201 -182\nالشرح :هو فاهم مرة بس شرحه للاسف ملخبط و سريع م تدري هو في اي درس و يشطح كثير و خطه للاسف سيء مرة اذكر اخلص متيريل الفاينال قبله ب اسبوعين\n\nالتحضير :الدكتور صار يحضر مو زي قبل و زود انه يخصم عالغياب و من ناحية التاخير يمشي الا لو جيت متاخر نص ساعة هنا بيزبد لك لكن بيحضرك اذكر كان يزبد لواحد بالكلاس و قفطه انه كان يتقهوى\n\nالتصحيح :يعطيك فوق حقك و م يخصم لو شافك فاهم يعني غلط بسيط\n\nالكوزات :صراحة سهلة و من الكتاب\n\nالتعامل :طيب بس مشكلته صوته عالي مررررة بيصدع راسك\nالقريد 😃 مرة م انصح فيه و ندمت درست معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513499-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/31", "user": "Bader_Alqahtani", "ts": 1565206331000, "tid": 68571, "pn": 31}}]}', 1565206331000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12081-math201', 'stk-user12081', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "J ABUIHLAIL\nMATH201 - T203\nبنود التقييم :\n\nالتحضير:\nيرسل نهاية كل كلاس فورم. راح يحاول انه يبين لك شدته في التحضير, لكن بالنهاية اعطى كل الطلاب تحضير كامل.\nطريقة الشرح:\nشرحه ممتاز ويعطيك امور اشمل من الاونلاين كورس بحيث انك تكون فاهم الفكرة وتطبقها على كل انواع القرافات.\nالكويزات:\nالدكتور في هالناحية كسول جداً. ياخذ الاسئلة جاهزة. الارقام في الكويزات فلكية, راح تحس انه يختبر مهارتك في ضرب وقسمة الاعداد الكبيرة. مع انه المفروض يركز على الفكرة اكثر لكن الشكوى لله.\nالمياجر:\nكومون\nالفاينلات:\nكومون\nالقريد النهائي:\nA\nاضافات:\nالدكتور غير متعاون وراسه يابس شوي.\nعلى فكرة , الدكتور شاعر ويحب الشعر.\n\nhttps://www.youtube.com/watch?v=ZU8umDSPerY\n\nهذا فيديو له للي يبي يشوف قريحته الشعرية. 🤔", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531459-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/33", "user": "user12081", "ts": 1629891176000, "tid": 68571, "pn": 33}}]}', 1629891176000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-2ams-math201', 'stk-2ams', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201\nTerm 203 (Online)\n\nالشرح وطريقة التدريس:\nالدكتور جواد طريقة في الشرح يشرح الكونسبت في البداية بس شرحه اسرع من السريع فصعب تفهم معه. بعدها يبدأ يحل مسائل بس حله غير مرتب فلو سجيت (فهيت) شوي بتنصدم من الحوسه وما تدري وش صار.\n\nالبونص :\nالدكتور ما عنده اي بونص بس اذا كان الافرج طايح وهذا الي صار معنا يرفع لين يوصل الافرج المطلوب (70-75)%.\n\nالاختبارات القصيرة (الكوزات) :\nكل الكوزات والكلاس تست كانت على ويب اساين، والدكتور ما كان يتعب نفسه شوي ويختار الاسئلة والارقام لا تجيك ارقام فلكيه يضيع وقتك وانت ما عرفت تحسبها واذا واجهتك مشكلة في اختبار او شيء يقول مو مشكلتي مشكلتك ابد ما كان متعاون من هذي الناحية.\n\nالتحضير:\nفي بداية الترم كان يرسل رابط microsoft forms في وقت عشوائي ممكن نص المحاضرة ممكن بدايتها او في نهايتها وكان ينادي الطلاب بشكل عشوائي ويسألهم واذا ما جاوب يغيبه واذا جاوب غلط حط عنده علامة. بعد كم اسبوع صار يرسل الرابط بشكل ثابت بداية المحاضرة وقليل ينادي الطلاب.\n\nإضافات:\nالدكتور بشكل عام غير متعاون ورأسه يابس ونا يقبل النقاش حتى لو عندك عذر", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531715-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/34", "user": "2ams", "ts": 1631007890000, "tid": 68571, "pn": 34}}]}', 1631007890000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fahadmh-math201', 'stk-fahadmh', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68571", "n": "Dr. J Abuihlail", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 231 - Math 201\nالتحضير : كل كلاس يحضر ويختلف وقتها مرات بالبداية ومرات بالنهاية واحيانا بنص الشرح. وطريقة التحضير بالباركود وما يدقق كثير بالتاخير\nطريقة الشرح : من سلايدات الكتاب الجديدة واشوفها مملة جدا. يحل اكزامبل الكتاب واشوف شرحه جيد بس مو اللي تعتمده كمصدر رئيسي للمذاكرة. كنت اشوف ابو زهرة بدال شرحه\nالكويزات : بسيطة جدا. يقولك طلع ورقة ويعطيك سوالين من الكتاب وتصحيحه ممتاز اذا شاف طريقة حلك انك فاهم السوال\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: واضح\nإضافات : اذا حصلت دكتور ثاني روح فيه كثير افضل\nالدكتور يشطح احيانا برا الدرس وتراه شاعر عادي تلاقيه بنص الشرح يقط لك بيتين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1537225-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/j-abuihlail/68571/36", "user": "FahadMH", "ts": 1705429577000, "tid": 68571, "pn": 36}}]}', 1705429577000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5755-math201', 'stk-user5755', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68575", "n": "Dr. Mohamed El-Gebeily", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201\n\nالتحضير يومي ببداية الكلاس … وتاخير اكثر من خمس دقايق مايسمح لك تدخل.\nشرحه كويس يشرح الاكزامبلز وبعض اسئلة الكتاب فقط\nكويزاته متوسطه ولو تراجع الكويزات بصفحته بتجيب درجة حلوة\nتصحيحه منصف لازيادة ولا نقص … \" يتقيد بالبوليسي \"\n\nالقريد النهائي b+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972048-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-el-gebeily/68575/23", "user": "user5755", "ts": 1327236382000, "tid": 68575, "pn": 23}}]}', 1327236382000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ash800-math201', 'stk-ash800', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68579", "n": "Dr. Monther Alfuraidan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "TERM191-Math201\nالتحضير : يحفظ اسامي الطلاب وانتبه تتاخر, لو كلاسك الساعه 9 ودخلت 9:01 راح يطردك\nطريقة الشرح : الشرح مقبول ويستخدم نوتاته ولكن مافيها حلول، يعني لازم تصور بجوالك خصوصا ان الدكتور مايرضى احد يكتب وهو يشرح\nالكويزات : يعطي 2 او 3 كلاس تست صعب جدا\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: C\nالصوت: عالي\nإضافات : الدكتور شرحه معقول لكنه مايحب احد يسأل في الكلاس والدكتور مزاجي يوم يكون عصبي ويوم يطقطق وما انصح به الا للطلاب الي يتقبلون المزح ايضا الدكتور بنهايه الترم يجبر كل الطلاب يروحون للاوفس عشان يعطيهم الكلاس وورك وهنا انت لازم تجي قبل الموعد الي حدده الدكتور بساعه على الاقل لان الطلاب راح يسجلون اساميهم في ورقة والدكتور يجلس مع كل طالب اكثر من 10 دقايق والدكتورغالبا عنده فوق ال 80 طالب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1520551-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/monther-alfuraidan/68579/68", "user": "ash800", "ts": 1583417723000, "tid": 68579, "pn": 68}}]}', 1583417723000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman.h-math201', 'stk-abdulrahman.h', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - term 103\n\nالتحضير : ورقة تمر على الكلاس … ما يدقر على التأخير ،\n\nطريقة الشرح : يشرح الكونسبت على خفيف ويحل مسائل كثير … طريقته ممتازة ويوصل المعلومة ويثبتها …\n\nالكويزات : متوسطة على ما أذكر ،\n\nالقريد النهائي: أعطيه A+\n\nالصوت: ممتاز ، يمكن كلمتين أو ثلاثة تستغرب أول ما تسمعها بس بعدين الوضع تمام ،\n\nإضافات :\nمدرس ممتااااز خلوووق وشرح كويس … يفهمك زين ويتعامل معك بشكل راقي وأخوي ،\nحريص على الطالب وأنه يستفيد ،، الله يوفقه …\n\nأنصح به وبقوة …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p939488-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/29", "user": "Abdulrahman.H", "ts": 1322584022000, "tid": 68581, "pn": 29}}]}', 1322584022000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-magbool-math201', 'stk-magbool', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - term 133\n\nبنود التقييم :\n\nالتحضير : يمرر ورقة ، والتحضير من اول كلاس الى اخر كلاس ما يسيب ولا يوم.\n\nطريقة الشرح : شرحه عموما كويس ، لكن يعيبه انه ما يحضر للدرس ، يجي الكلاس ويفتح الكتاب ع الدرس ويعطينا القاعدة ثم أمثلة كثيييييير ، أحيانا تحسه ضايع ( بسبب عدم التحضير) ، وأحيانا يحل مسائل غلط لكن نادرا .\n\nالكويزات : سهلة، اختبرنا 6 وحذف أسوأ كويز , عشان كذا جاء افرج الكلاس وورك عالي ، واضطر ينقص كل واحد درجتين.\n\nالمياجر: common ، لكن تصحيحه بطل جدا ، ويعطيك اعلى من حقك .\n\nالفاينلات : نفس المياجر.\n\nالقريد النهائي: b+\n\nالصوت: أكسنت باكستاني بس واضح .\n\nإضافات :\nلو يجي محضر الدرس بيصير احسن مدرس ، لكن أحيانا يضيع ويضيعك معاه ، لكن عموما يبقى مدرس ممتاز.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1390474-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/33", "user": "magbool", "ts": 1408293866000, "tid": 68581, "pn": 33}}]}', 1408293866000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-math201', 'stk-abdulla_yahia', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. محمد يوسف ]\n\nMATH 201 - Term 133\n\n- التحضير : يومياً ورقة تمر على الطلاب ,\n\n- طريقة الشرح : يشرح على السبورة - شرحه جيد جداً بسيط و واضح لكنه أحيانا ما يحضر الدرس فيكون مرتبك ,\n\n- الكويزات : أعطانا 6 كويزات سهلة و شبه مباشرة يحذف أسوأ واحد ,\n\n- المياجر : كومن ,\n\n- الفاينلات : كومن ,\n\n- القريد النهائي : B\n\n- الصوت : واضح و لهجته الإنجيلزية متوسطة ,\n\n- إضافات : الدكتور محترم جداً و بشوش + تصحيحه ممتاز + يرحب بالأسئلة و يجاوبب عليها دائماً ,", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1391856-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/34", "user": "Abdulla_Yahia", "ts": 1408648614000, "tid": 68581, "pn": 34}}]}', 1408648614000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-p0wer-math201', 'stk-p0wer', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 151 - ماث 201\n\nهالدكتور لازم تنزل عنده وين ما شفته …\n\nكويزاته سهلة جدا وتصحيحه أكثر من ممتاااااااااااااااااااز دف مو طبيعي ! …\n\nروميتي اخذ عنده بالصيف وقالي لازم تنزل عنده تصحيحه رهيب … ما صدقت حتى شفت بنفسي …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1433636-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/37", "user": "p0wer", "ts": 1447780332000, "tid": 68581, "pn": 37}}]}', 1447780332000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10578-math201', 'stk-user10578', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 - ترم صيف 163\n\nباختصار مثل ما قالوا الشباب الدكتور ممتاز ولا تتردد تسجل عنده\n\n* الشرح ممتاز يعطي فكرة عن الدرس على السريع و يدخل على الطول باسئلة الكتاب\nويحل اكبر عدد ممكن من الاسئلة وهو اهم شيء بالماث انك اكبر عدد من الاسئلة.\n\n* الصوت واضح جداً رغم انه باكستاني لكن واضح انه متمرس بالانجليزية\n\n* التحضير يكون بورقة تمر على الطلاب خلال الدرس\n\n* من الاشياء اللي عجبتني فيه ايضاً انه ما يحاسب على التأخير\nيعني لو تتأخر عشر دقائق او ربع ساعة يسمح لك تدخل و تحضر\nلكن اذا زودتها نص ساعة او كل يوم ممكن يزعل و مع ذلك يسمح لك تدخل وتحضر ،\nفي النهاية الدكتور مقتنع ان اللي يبي مصلحته يحضر من البداية .\n\n* الكويزات كان عددها 6 و اخذا افضل 4 لكن افرج سكشنا كان عالي جداً 35 من 40\nلذلك اضظر يحذف 5 درجات من كل واحد\nكل كويز يكون عبارة عن درسين او ثلاث و يكون الكويز سؤال من كل درس سؤال يعني سؤالين او ثلاثة ،\nكويزاته متوسطة المستوى بتلقى تريك صغير بكل كويز ،\nالكويزات تكون شبيهة باسئلة الكتاب لكن مو نفسها ، حاول تدخل على كويزاته القديمة\nيجيب نفس الطريقة لكن مو نفس الاسئلة .\n\n* تصحيح المياجر احسه لا بأس به يمشي على السلوشن يعني مو ذاك النوع اللي يعطيك درجات مجانية\nلكن ممكن يميشك ببعض الاشياء يعني بدل 2- يخليها 1-\nاذا انت شاك بشيء بالتصحيح روح له المكتب وما راح يقصر معاك ممكن تحصل درجة او درجتين\nبس اذا الغلط واضح ما يقدر يسوي شيء .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479252-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/41", "user": "user10578", "ts": 1503577445000, "tid": 68581, "pn": 41}}]}', 1503577445000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal_2015-math201', 'stk-faisal_2015', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68581", "n": "Dr. M Yousuf", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم 181\nالتحضير ورقة تمر ولو تجي متاخر يحضرك عادي\nالشرح في بداية الكورس ما كنت افهم منه لكن يوم تبدأ تحل تفهم كل شي لانه يركز على المفهوم كثير لكن بعد ميجر 1 صرت افهم بشكل واضح وكان مصدري الرئيسي\nالكويزات بسيطة ومن حظي صراحة افرج السكشن ما كان عالي يعطي 7 وياخذ افضل 5 ويوم شاف الافرج نازل زاد واحد بادرة جميلة منه\nالميجر الاول كان ريتين كومن اما الثاني والفاينل MCQ كومن و تصحيحه جيد لا هو اللي يدف ولا اللي يشد عليك\nالصوت واضح\nالقريد النهائي A جدا ارتحت معه في الكورس وكلاسه خفيف ويهتم للطلاب حتى يوم الميجر قبلها بكم ساعة يجي يشرح لنا اسئلتنا انصح فيه بشدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504327-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-yousuf/68581/42", "user": "Faisal_2015", "ts": 1546297653000, "tid": 68581, "pn": 42}}]}', 1546297653000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12192-math201', 'stk-user12192', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 term211\n\nالتحضير : شدييد، يبدأ يحضر من قبل لا يبدا الكلاس إلى اول دقيقة، لو جيت بعد دقيقتين ولقيته يحضر أنت محظوظ. >>> يحسبه في الكلاس الوورك<<< كان عليه 6 نقاط وكل غياب يخصم نقطة.\n\nطريقة الشرح : الدكتور شرييح ما شاء الله عليه ويبدع في استخدام التاب للشرح والرسم، نادرا ما يقوم ويشرح من السبورة.\n\nالكويزات : متوسطة الصعوبة اخذ افضل 5 من 6\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A\n\nالصوت: كنت في نص القاعة اسمعه واضح، لغته ولهجته ممتازة جدا، ما يتكلم عربي إلا ما ندر.\n\nإضافات : -", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533302-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/81", "user": "user12192", "ts": 1641325352000, "tid": 68582, "pn": 81}}]}', 1641325352000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-q18-math201', 'stk-q18', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68582", "n": "Dr. Rajaie Alassar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH-201\n211\n- التحضير : شديد الصدق وذا الشي فاد اللي ماغابو أنه خصم بنهاية السمستر على كل غياب بوينت.\n\n- طريقة الشرح : الدكتور شريح جدا مع أنه جالس وتسأله أي شي يجاوبك بكل أريحية.\n\n- الكويزات : كويزاته تعتبر وسط لين ماتعرف طريقته وتصير سهله عليك واكتشفنا متأخر مع انه كان يقول تدربو عالكتاب دايم أنه يجيب الأسئلة نسخ لصق غالبا من الكتاب.\n\n- المياجر والفاينلات: كومن.\n\n- القريد النهائي :A+\n\n- الصوت : واضح وينفهم.\n\n- إضافات : الدكتور مع أنه شديد وتحسه بس يبي يشرح ويجاوب الأسئلة المتعلقة بالدرس إلا أنه متعاون جدا لا كلمته بالاوفس أور ويتناقش معاك بكل هدوء ويدور مصلحة الطالب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533391-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rajaie-alassar/68582/82", "user": "Q18", "ts": 1641838087000, "tid": 68582, "pn": 82}}]}', 1641838087000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8551-math201', 'stk-user8551', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - Term 121\n\nبالنسبة للي يقول الدكتور مهوب عادل !!\nالدكتور يوضح كيفية تقسيم من بداية الترم ، و قد قال لنا اللي يغيب عن كويز سواء بعذر أو بغير عذر راح يأخذ صفر ، فما أدري وين المشكلة اللي يشوفها البعض !\n\nبنهاية الترم و قبل الفاينلات بأسبوع “تقريبا” أعطانا مسائل نطبعها و ننسقها على الكمبيوتر و عليها بونص ، ما إشتغل عليها إلا ثلاث طلاب و أعطاهم 10 من 60 بونص.\nأنا ما حليت إلا هومووركين لكني إشتغلت على البونص و أعطاني 58/60 بالكلاس وورك.\nطبعا تقسيم الكلاسوورك عنده : 50 كويزات “أفضل خمس من ست كويزات” + 10 هومووركات \" يطلب عدد محدد من الهومووركات ، أعتقد 12 هوموورك\"\n\nالتصحيح : بصراحة أرى بأنه من أفضل الدكاترة اللي درست عندهم من ناحية تصحيح المياجر ، حل بطريقة مرتبة و وضح له إنك فاهم و راح يعطيك قريد طيب ، أذكر مسألة بميجر 2 ضيعت بمعطيات السؤال لكني حليت بشكل واضح و أعطاني 8/10 فيها.\n\nالشرح : ما أقدر أتكلم عنه لأني ما كنت أنتبه معه.\n\nالأخلاق : الدكتور يتعامل بـ “قسوة” -إن صح التعبير- ، فإن كنت من النوع اللي يزعل من كل كلمة ما أنصحك تنزل معه.\nموقف صار لي معه ما أنساه له : بالميجر الثاني جبت درجة طيبة فناداني مكتبه و شكرني و عرض علي إني آخذ ماينور بالماث.\n\n* لو لقيت إسمه منزل أي كورس ما راح أتررد إني أنزل معه مرة ثانية.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1218361-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/41", "user": "user8551", "ts": 1367529036000, "tid": 68677, "pn": 41}}]}', 1367529036000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-math201', 'stk-mr.a1', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68677", "n": "Dr. M Al-Shahrani", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 161 MATH 201\n\nالتحضير :\nعلى الجوال ، ينادي بالأسماء. حسب ما لاحظت ما يدقق على التأخير.\n\nطريقة الشرح :\nشرح على السبورة + سلايدات يكون هو رافعها على البلاك بورد. يستخدم موقع GeoGebra للرسم -في بعض الأحيان. يحل أمثلة كافية.\n\nالكويزات :\nوسط إلى صعبة. يجيبها من الأولد اقزام.\n\nالمياجر:\nكومون. تصحيحه ممتاز ، أهم شيء لا تترك السؤال فاضي وحاول تحل ، وبتاخذ بارشال قريد.\n\nالفاينلات :\nكومون ، باقي عليها.\n\nالقريد النهائي:\nمن A إلى +A.\n\nالصوت:\nواضح جدا ، يتكلم دايما بالانجليزي والاكسنت ممتاز.\n\nإضافات :\nتعامله رسمي مع الطلاب ، لكنه ما يخلو من بعض المداعبات والمزاح -على خفيف-.\nما يحب يشوف الطالب منشغل بالجوال أو أي شيء عن الشرح ، وإذا شافك منشغل راح يحرجك 😆.\nالتصحيح جيد ، ياخذ وقت لكن ما يطول كثير ، والدرجة مرضية.\n\n*", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1462654-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-al-shahrani/68677/54", "user": "Mr.A1", "ts": 1479647826000, "tid": 68677, "pn": 54}}]}', 1479647826000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dr_k_a_z-math201', 'stk-dr_k_a_z', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خذ العلم مني يالحبيب\n\nاول شي ماث 201 تكملة وكتابها هو الكالكولس الشهير والواضح واكيد الكل يتفق معي في هذا الشي انو الكتاب مره اوك\n\nثاني شي كل دكاترة ال 201 سيئين في الشرح وهذا الشي معروف\n\nفبالتالي لازم تدور على الدكتور اللي عنده ترتاح من ناحية الدوام والكلاس وورك\n\nوالدكتور هذا هو الضالة المنشودة وعن تجربة وربي غايب يمكن نص الترم وواحد دايم يحضرني والوضع عال العال\n\nومافيه ولا كويز الا وماخذه في الاوفيس الاور عنده وهو مررررررررررررررررررررررره طيب وحبووووووووووووووووب\n\nنصيحه لاتنزل الا عنده", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p581338-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/16", "user": "Dr_k_a_z", "ts": 1270300714000, "tid": 68928, "pn": 16}}]}', 1270300714000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alb7ar1-math201', 'stk-alb7ar1', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معاه Math 201 في 092\n\nالتحضير :ورقة للسكشنين تمر، يعني ممكن تحضر خويك حتى اللي في السكشن الثاني\nطريقة الشرح :جيدة الى ممتازة، وتحس باخلاص ويحاول يوصل المعلومة باي طريقة\nالكويزات :متوسطة الى صعبة، لكن في تصحيحها يمشي واجد\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: B+\nالصوت:مسموع لكن لهجته اﻵسيوية في البداية بتكون نوعا ما صعب فهما\nإضافات : المدرس ماقصرنا معنا في تصحيح الاختبارات الريتن(من حيث اعادة تصحيحها وزيادة معظم الطلاب من 7-10 درجات)\nوبالنسبة للكلاس وورك يعطيك شي ما تتوقعه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p641358-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/27", "user": "alb7ar1", "ts": 1277153328000, "tid": 68928, "pn": 27}}]}', 1277153328000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-montadhar-math201', 'stk-montadhar', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درسني math201 سمستر 111\n\nالتحضير : ورقة تمر و متساهل جددددداً حتى لو تجي آخر خمس دقايق ما يقول شي و الميك أب عنده زي الحلاوة\nطريقة الشرح : متوسطة و بدأت تصبح سيئة قليلا بعد ميجر ون و بالذات لأن كان في قبلنا سكشن و ما نجي إلا السبورة مكتوبة و يالله عاد يا تفهم يا تكتب\nالكويزات : سهلة من النوت و الهوموورك\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: B\nالصوت: زوين و الأكسنت تتعود عليها و تصير عندك زي النكته ههه\nإضافات : أخلاق عالية جدا و مزح لكن اخترب شوي على النهاية، التصحيح يمشي على السلوشن و لو تتأطع شئف على قولة السوريين ما زادك شي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972123-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/46", "user": "montadhar", "ts": 1327252593000, "tid": 68928, "pn": 46}}]}', 1327252593000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_fras-math201', 'stk-abu_fras', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "خلاص انا نزلت معاه الكروس math201 term 121\nالتحضير : يمرر ورقة توقع عليها .\nالشرح : ينقل من نوت (الافضل لك تنتبه معااااااه والله شرحه مرررة بطل بس بعض الدوافير اصلحهم الله مايحبونه لانه يشرح حبة حبة ويشرح مثال سهللللل ثم وسط ثم سلخخخخ من الاولد اقزام\nالكويزات :صراحة جنني ماعرفت طريقتة مرة وسط مرة من اسئلة الكتاب مرة مش صعب بس يميل الى الصعوبة لاني صراحة ماذكرت زين واخذت 5 من 10\nالمياجر والفانيل …تصحيحه حلو يعني مع الطالب مهو ضدة بس عبي الورقة قوانين\nالصوت :اكسنت انجليزي مدبلج هندي (ههههههه عساكم تفهمون اش اقصد )\nالقريد النهائي :b+\nاضافات :\nترى ما تستفيد منه في الساعة المكتبية لانه لازم يطالع في السليوشن (هههههه هو يشوفها عيب يقوم يصرفك\nويقول راح اشرحها لك في الكلاس ) بس والله العظيم اخلاق والدكتور الوحيد اللي يسلم على الطلاب واما بالنسبة للتدخين ياخي محد له سلطة عليه (تعليقا على الاخ اللي فوق يقول يدخن يعني ايش يعني يدخل الكلاس وهو سكران الله يهيدنا ويهديك تذم مدرس عشان دخان !!!!)\nايضيا زودنا اخر الترم في الكلاس ورك 3 درجات شيء حلو مقارنة بكوزاته المتوسطة بشكل عام", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1163381-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/53", "user": "ABU_FRAS", "ts": 1358074263000, "tid": 68928, "pn": 53}}]}', 1358074263000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-amrfa-math201', 'stk-amrfa', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 121 ماث 201\n\nالتحضير : ورقة تمر على الطلاب مداك تخلي احد يحضرك بس لمن يلاحظ انه العدد اقل بيعد وراكم و يشك بالكلاس كله باقي الترم خخخ\n\nطريقة الشرح : مرتبة و حلوة و يشرح امثلة كويسة و النوت حقه منتآآز\n\nالكويزات : متوسطة بس اول وآآحد مرة سهل ؛)\n\nالمياجر: كومون\n\nالفاينلات : كومون\n\nالقريد النهائي: بي\n\nالصوت: اللهجة شوي غريبة\n\nإضافات : مدرس حبيب <3 و الكلاس وورك يزبطك اذا غياباتك قليلة و حال الهوموورك و بالاضافة الكلاس وورك حقه يعتمد على الكوزات و الغيابات", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1169990-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/54", "user": "amrfa", "ts": 1359214421000, "tid": 68928, "pn": 54}}]}', 1359214421000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-almaiman-math201', 'stk-almaiman', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "درست عنده ماث 201 و 202 واحتمال كبير أنزل عنده 301\n\nالدكتور بطل في الشرح بكل ما للكلمة من معنى … كويزاته متوسطة … التحضير ورقة تمر ع الشباب أحيانا يدقق فيها … ما يغيب أبدا ما شاء الله عليه … الهومووركات أول بأول وأحيانا يعطي الطلاب مهلة زيادة إذا كان في مياجر وكذا … شرحه طبعا على السبورة … مرتب جدددددددا في الشرح … يعطيك يمشي على نظام الأفرج …\n\nبشكل عام … بطل بطل بطل …\n\n*بالتوفيق *", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1284746-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/61", "user": "almaiman", "ts": 1384009112000, "tid": 68928, "pn": 61}}]}', 1384009112000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_169-math201', 'stk-_169', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "143 math 201\nالتحضير : ينادي بالارقام\n\nطريقة الشرح : يشرح من اوراق امثلة حلوة وبعضها من الكتاب\n\nالكويزات : متوسطة بس واحد صعب عشان يضبط الافرج\n\nالمياجر: كومون , تصحيحه عادي مايزيد ولا ينقص (اذا عندك مشكلة او غلط كلمه ويزيدك مو زي بعضهم )\n\nالفاينلات : كومون\n\nالقريد النهائي: بي\n\nالصوت: صوته مسموع بس اللهجة شوي لك عليها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1423736-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/65", "user": "_169", "ts": 1439302609000, "tid": 68928, "pn": 65}}]}', 1439302609000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-al-houri-math201', 'stk-al-houri', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201\nTerm 161\n\nالتحضير : عنده مرونة في التحضير - يحضر في نص المحاضرة بمناداة serial number ( تقريباً بعد 20 إلى 25 دقيقة من بداية المحاضرة ) - ما عنده تأخير - لو تحضر قبل خمس دقائق من انتهاء المحاضرة يسجلك حضور\n\nطريقة الشرح : يشرح باستخدام السبورة حيث يكتب أسياسيات الدرس ( concept ) ثم يقوم بحل المسائل على كل نقطة - يحل مسائل كثيرة\n\nالكويزات : عطانا 6 كويزات حذف منها أسوء واحد - الكويز عبارة عن سؤالين تقريباً - يعطيك 30 دقيقة تقريباً عليها - سهلة إلى متوسطة الصعوبة\n\nالمياجر: تصحيحه عادي وقد يزيدك قليل - كومن\n\nالفاينلات : كومن\n\nالصوت :\n\n**[quote=\"abu FRAS, post: 1136282, member: 46202\"]\n\n[/quote]\n\nيعني بتتعلم لغة جديدة - ستعتاد عليها مع الوقت\n\nإضافات :\n١) - الدكتور يكتب كل شيء بشكل مرتب ومنظم على السبورة\n٢) - الدكتور طيب ومتساهل ومهتم بالطالب\n٣) - الدكتور يرسل أسئلة على BlackBoard قبل المياجر والفاينل ويرسل حلولهم بعد فترة لمساعدة الطلاب\n٤) - الأفضل تروح وتناقشه على الإختبارات وتتأكد مثل ما قال الأخ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467336-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/74", "user": "Al-Houri", "ts": 1485809123000, "tid": 68928, "pn": 74}}]}', 1485809123000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-jolenve-math201', 'stk-jolenve', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m68928", "n": "Dr. Izhar Ahmad", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201 - TERM211\n\nالتحضير : ما يدقق بالتحضير و يمشي\nطريقة الشرح : يكتب بالسبورة و ما عنده سلايدات\nالكويزات : متوسطط الى صعبة و بالاخير رفعنا النورملايزيشن\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: صراحة على خلاقه يستاهل B+ ولا شرحة متوسط\nالصوت: لهجة هندية مضروبة\nإضافات : تعامله جيد و يسولف كثير بالكلاس و بعدين يقول تشغلوني عن الكلاس هههههههه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533273-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/izhar-ahmad/68928/78", "user": "Jolenve", "ts": 1641228511000, "tid": 68928, "pn": 78}}]}', 1641228511000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8975-math201', 'stk-user8975', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m69347", "n": "Dr. I Louhichi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 سمستر 123\n\nاسمه بالبورتال : I louhichi\n\nشهادة حق سأحاسب عليها :\n\nالشرح : بطل\n\nالتصحيح : سيء\n\nنصيحة أخ : لو كان مستواك بالماث مو مرة ممتاز (يعني عادي أو فوق العادي بشويتين) وطموحك بقريد طيب ، خليه آخر خيار لك ، لأن تصحيحه بيأثر على الفاينل ليتير قريد حقك (الي صار معي) 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1250651-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/i-louhichi/69347/47", "user": "user8975", "ts": 1375275773000, "tid": 69347, "pn": 47}}]}', 1375275773000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2728-math201', 'stk-user2728', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m70511", "n": "Dr. Ahmad Bonfoh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201\n\nالتحضير :\nورقة تمشي على الطلاب\n\nطريقة الشرح :\nصراحة ما أقدر أقيمه لأني مو متابع معه\nلأنه جاء متأخر آخر السمستر والحالة ربك أدرى فيها\nالكلاس ما ينتبه معه إلا إللي قدام\nكتابته ملخبطة على السبورة ولغته مب واضحة\n\nالكويزات :\nسهلة بس ما ادري من وين يجيبها\nهي أسئلة أو أمثلة الكتاب أو نوتته\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nd\n\nالصوت:\nغير واضح وغير مسموع ولغته عاملة عائق لوصول المعلومة لنا بسبب جنسيته\n\nإضافات :\nما تبي شرح وتبي غيابات وتاخير وتبي تمشي حالك نزلها معه\nتبي شرح وفهم وترتيب بالمادة غيره أفضل بواجد !\nتصحيحه ما لحقت عليه لأنه جاء متأخر بعد ميجر 2 والفاينل كان ملتبل تشويسز فعشان كذا ما حصلت لي الفرصة غني أعرف تصحيحة\nللمعلومية هالكلام كان لأول سمستر جاء فيه الجامعة والكلام مضى عليه 3 سنين فما أدري تغير ولا لا ألحين\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972155-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmad-bonfoh/70511/19", "user": "user2728", "ts": 1327258516000, "tid": 70511, "pn": 19}}]}', 1327258516000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-del_piero_7-math201', 'stk-del_piero_7', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m70785", "n": "Dr. S Boubaker", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "شديد جداً في التصحيح لدرجة انه في ميجر 2 ماث 201 عطاني 61 ووالله لو اني مع مدرس ثاني ما نزلت عن 75 تخيلو في مسألة حليت نصها كامل كامل وبقى النصف الثاني خربطت اي كلام يعني قلت يمكن آخذ منها كم بوينت\nعطاني صفررررررررررررررررررررررررررررر قد راسي والسؤال عليه 12 درجة\n\nيعني لازم تحل كامل صح\n\nواخلاقه بصراحة زفت اروح عنده الاوفس كأني ذابح امه وابوه وجاي اتأسف له\n\nمعاملته سيئة جداً\n\nوعلشان اكون منصف شرحة ممتاز جداً وحلوة طريقتة ولكن ايش الفايدة انك تطلع من الكورس فاهم وتطلع ب سي ولا سي بلس!!\n\nتقييم المدرس من ناحية الشرح a\nومن ناحية الأخلاق d\nومن ناحية التصحيح d", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p543981-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/s-boubaker/70785/14", "user": "del_piero_7", "ts": 1266244469000, "tid": 70785, "pn": 14}}]}', 1266244469000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-loop24-math201', 'stk-loop24', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m81621", "n": "Dr. Slim Belhaiza", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - 212\n\nالتحضير :\nيحضر اخر الكلاس … بس أحيانا كان يطرد المتأخرين اذا تكرر تأخريهم\nالشرح :\nيستخدم السبورة و الصدق من افضل المدرسين الي درسوني\nالكويزات :\n٣ او ٤ كويزات على ما اذكر … متوسطة وسهلة للي يركز معه\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A\nالصوت: واضح\nإضافات :\nالدكتور حبيب ومتفاهم مرة وشرحه ممتاز،، احيان كان يشطح ويمزح بس اشوفها ميزة لان الكلاس طويل mw بس اذا شافها طولت يرجع للدرس وولا قد تأخرنا في المنهج", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535874-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/slim-belhaiza/81621/52", "user": "loop24", "ts": 1668071684000, "tid": 81621, "pn": 52}}]}', 1668071684000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-feras-mtn-math201', 'stk-feras-mtn', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 -181\nالتحضير :\nكل يوم ويحاسب عالتاخير\nطريقة الشرح :\nليست سيئة لكن فيه افضل\nالكويزات :\nمتوسطة وكان كل اسبوع كويز\nالمياجر:\nكومن لكن على ترم ١٨١ الميجر الاول كان تصحيحه سيء جدا\nالفاينلات :\nكومن\nالقريد النهائي: F\nالصوت:\nواضح\nإضافات :\nالتعامل جدا سيء ويحكم عليك من الشكل رغم انه زبدلنا بداية الترم بالشي ذا وقال انا عندي بعد نظر واعرف الطالب الشاطر والسيء من اول نظرة\nكريف عنده واجبات لازم تسلمها قبل الميجر غير واجبات الموقع وكويز كل اسبوع تقريبا الدكتور صح حريص لكن ماهضمته وواحد من الاسباب اللي خلاني اعمل دروب سمستر فلا تخليه خيارك الاول", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1512187-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/13", "user": "Feras-MTN", "ts": 1562633241000, "tid": 176969, "pn": 13}}, {"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201-183\n\nمثل ماقالو الشباب مايحاسب عالتاخير بس لو اتاخرت راح يستقعدلك الكلاس كامل ومايربط الغيابات بالخصم يعني غيب مثل ماتبي بس لا توصل للDN … الدكتور شرحه جدا جدا كويس بس مزحه ماهضمته وكلاسه تحس كانك فمسلسل باب الحارة…\n\nانا اشوف سلبيته في كويزاته يعطيك سؤال واحد واذا ماعرفته او حليته خطأ بتاخذ صفر فالكويز كامل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1515204-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/25", "user": "Feras-MTN", "ts": 1568690861000, "tid": 92906, "pn": 25}}]}', 1562633241000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-math201', 'stk-moh_ammed', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m92906", "n": "Dr. Mohammad Kafini", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - Term 211\nالتحضير: رسل لنا رابط فورم في بداية الترم وصار التحضير عليه…يفتحه دايم في آخر الدقايق من المحاضرة…مايحاسب على التأخير بس في مرات قليلة في نهاية الترم صار يتحلطم علينا بسبب إن بعض الطلاب زودوها في التأخير.\n\nالتعامل: أخلاقه كويسة.\n\nالشرح: لا بأس فيه…يعرض سلايدات الدرس (أتوقع السلايدات مأخوذة من الكتاب) ويشرح بالقلم على السبورة.\n\nالصوت: كلامه خليط مابين الانجليزي والعربي، لكن بشكل عام فهو واضح.\n\nالكويزات: متوسطة بس تحس بعض الأحيان بصعوبة في بعض الأسئلة، والله إني نسيت إذا عطانا 3 ولا 4 كويزات. الأسئلة أظن يجيبها من الكتاب.\n\nقبل المياجر والفاينل يسوي اوفس اورز إضافية على التيمز.\n\nعموما إذا مالقيت إلا هالدكتور فهو خيار جيد.\nالقريد النهائي: B+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533321-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-kafini/92906/29", "user": "Moh_ammed", "ts": 1641390383000, "tid": 92906, "pn": 29}}]}', 1641390383000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-eng.3booodii-math201', 'stk-eng.3booodii', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201\n\nبنود التقييم :\n\nالتحضير : مافي تحضير\nطريقة الشرح : يكتب القانون ويحط رسمه ويقعد يشرح … الشرح مش ولا بد\nالكويزات : تقريباً سهلة أو متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: ماهو عالي لكن نوعاً ما واضح\nإضافات : آخر كورس إن شالله أنزله مع مدرس ما يحضر … المشكلة إنه ما يقلك متى الكويزات عشان تحضر … فـ البداية الطلاب قالو له لازم تقلنا متى الكويزات … صار كل ما قرب كويز قال الكلاسين الجاية واحد منهم فيه كويز على كذا وكذا …\nبالنسبة للهومورك يختار لك 4 أسئلة وتحلها بس وتسحب ع الباقي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p852232-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/20", "user": "eng.3boOodii", "ts": 1307962846000, "tid": 94260, "pn": 20}}]}', 1307962846000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-h_tl-math201', 'stk-h_tl', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم 103\n\nالتحضير : اخر الكلاس يعني تعال قبل نهاية الكلاس بعشر دقايق يحضرك <<< صارت قدامي\n\nطريقة الشرح : عادي بس يوصل المعلومة\n\nالكويزات : سهلة تكون تشبه اسئلة الواجب كل اربعاء كان فيه كويز سؤال او سؤالين ماتزيد\n\nالمياجر:كومن\n\nالفاينلات :كومن\n\nالقريد النهائي: +a\n\nالصوت: واضح\n\nإضافات : لا تغيب وابشر بالبونص مدرس حبوب و ما يمديك تقول لاحد يحضرك يحفظ ام السكشن باسبوع .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p888615-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/22", "user": "H_TL", "ts": 1313787323000, "tid": 94260, "pn": 22}}]}', 1313787323000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.all-math201', 'stk-mr.all', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "زي ماقالوا الشباب …ماث 201. المدرس أخلاق لأعلى مستوى ويعجبني تعامله مع الطالب في الاوفيس أور\nلو تبي يراجع لك المنهج كامل ما عنده مشكلة… أعطانا 6 كويزات وأخذ احسن 4\n… نزل عنده وان شاء الله موفق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p898146-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/23", "user": "Mr.All", "ts": 1315667950000, "tid": 94260, "pn": 23}}]}', 1315667950000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-7hesham-math201', 'stk-7hesham', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 سمستر 131\nالتحضير :\nيحضر اخر الكلاس واللي يتاخر من 15-20 دقيقة يحطه ليت (متساهل بالتاخر)\nالشرح:\nيشرح من نوته على الايباد ويرسل النوت للطلاب بعد نهاية كل سكشن (نوتته ممتازة جدا )\nالكلاس وورك:\nاعطانا 3 كويزات وكوز ميك اب للي يبغى يعدل اي درجة من الثلاث كوزات, الكوزات من متوسطة لصعبة\nلكن انتبه تفرط فيها مرررررة مهمة لانها قليلة والكلاس وورك ال10 درجات كله عليها وتقدر تضمن درجة شبه كاملة فيه اذا كانت كوزاتك حلوه انا اخذت بالاول10من10 وبالثاني 13 من15 والثالث 12.5من 15 والميك اب كوز اخذت 13.5 من 15 طلعت ب37 من 40 بالكلاس وورك\nالتصحيح :\nيعطيك حقك وزيادة تصحيحه مرة كويس\nالقريد النهائي: a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316803-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/35", "user": "7Hesham", "ts": 1389110838000, "tid": 94260, "pn": 35}}]}', 1389110838000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-cpc_2015-math201', 'stk-cpc_2015', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94260", "n": "Dr. Ahmet Tatar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 -161\n\nالتحضير : يحضر بعد 25 دقيقة و ما عنده مشكلة لو تتأخر\nطريقة الشرح : شرحه جباار بمعنى الكلمة يفتح سلايداته و يشرح عليها يحل أسئلتها و بعدين ينزل نفس السلايدات بالبلاك بورد\n\nالكويزات : نفس صعوبة الأسئلة اللي يحطها بالسلايدات ، من سهله إلى متوسطة ، و تصحيحه في الكوزات “الكوزات فقط” خرافي\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: A+\n\nالصوت: واضح جدا\n\nإضافات :\n\nالدكتور حبيب جدا و متعاون جدا و خلوق ، أفضل دكتور نزلت عنده ماث إلى الآن ، ما يمانع الدكتور أنك تدخل الكلاس و تقعد على جوالك أو حتى تنام ، سلايداته جدا واضحة و تغنيك عن أي مرجع ثاني ، يعني تذاكر سلايداته حتى لو منت فاهم شي و أولد إقزام تجيب قريد بالراحة ، تصحيحه بالمياجر جيد يعطيك حقك و فوقه كم درجة.\n\nباختصار الدكتور بطل جدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466811-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ahmet-tatar/94260/43", "user": "CPC_2015", "ts": 1485119847000, "tid": 94260, "pn": 43}}]}', 1485119847000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6130-math201', 'stk-user6130', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 سمستر 101\n\nالشرح : من نوت له على شكل PDF مع أمثلة و الأمثلة يحلها على السبورة بشكل واضح جداً .\nالتحضير : كل كلاس في الغالب في نهايته .\nالكوزات : سهلة جداً و في متناول الجميع .\nإضافات : تصحيحه للمياجر عسل .\nالقريد النهائي : a .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p741943-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/18", "user": "user6130", "ts": 1291907691000, "tid": 94261, "pn": 18}}]}', 1291907691000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6991-math201', 'stk-user6991', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94261", "n": "Dr. Muhammad Islam Mustafa", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه Math 201 ترم 101\n\nالشرح : يفهمك الكونسبت من دون استرسال ويحل اسئله كافيه بعد كذا من السبوره\nكتابته في السبوره منظمه جدا. ماشى في الكورس على الوقت\n\nالنووت : سلايدات Pdf تحتوي على الكونسيبت واسئله من دون اجابات فلازم تكتب مع الدكتور والا حتنسى\n\nالتحضير : في وسط المحاضره او في الاخير\n\nالكويزاات : سهله وممكن متوسطه\n\nالقريد النهاائي : A+ زي ما اعطاني\n\nالله يشرح لك صدرك ويسر عليك يا د محمد اسلام مصطفى", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p891021-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-islam-mustafa/94261/32", "user": "user6991", "ts": 1314135117000, "tid": 94261, "pn": 32}}]}', 1314135117000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3767-math201', 'stk-user3767', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94263", "n": "Dr. Muhammad Riaz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الحين وانا على نهاية السمستر تقريباً. طبعاً انا اخذت معاه Math201\nأبتكلم عنه بتفصيل:\n\nالتحضير: بالأسامي وبشكل دائم تقريباً. اعتقد انه ما ينقص درجات على التحضير. أو انه معطيها درجات قليلة. بشكل عام ما يهمه التحضير مرة في الكلاس وورك.\nطريقة الشرح: ممتاز جداً. الاكسنت قلق شوي لكن بشكل عام شرحة حلو ويستخدم الامثلة كثير. ويتجاوب مع اسئلة الطلاب دائماً.\nالكويزات: يجيب لك اسئلة قريبة من اسئلة المياجر. يعني صعوبتها نفس صعوبة الميجر.\nالمياجر: كومن. تصحيحه ممتاز جداً، يعني كريم نوعاً ما، واذا شافك حليت يعطيك درجة.\nالفاينلات: كومن.\nالقريد النهائي: A\nالصوت: مثل ما قلت واضح لكن عنده مشكلة بالاكسنت.\nإضافات:\nهذا المدرس على ما اعتقد انه باكستاني الجنسية. بشكل عام انا اعجبني ولو لقيته منزل 202 أبنزل عنده. معاملته راقية جداً يحسسك انك رجال < عكس بعض الدكاترة. دايم موجود بالاوفس حقه ويتفهم للطالب. يعني ما عنده مشكلة تتأخر عن الواجبات وما عنده مشكلة تختبر كويز فاتك. يهتم لنشاطك بالكلاس، يعني حظورك وتجاوبك. لأنه حاط عليها نسبة من الكلاس وورك. تصحيحه للمياجر ممتاز ومتساعد كثير.\nبشكل عام هالمدرس ارتحت له وانصح فيه وبقوة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p760125-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-riaz/94263/10", "user": "user3767", "ts": 1294532828000, "tid": 94263, "pn": 10}}]}', 1294532828000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-math201', 'stk-user6661', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94263", "n": "Dr. Muhammad Riaz", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 بسمستر 101…\n\nالإيجابيات:\n\nالله يرضـى عليك يا دكتور محمد رياض…والله احلى مافيه انه يعاملك على انك رجل…فعلا هالشي ينقص كثير من الدكاترة!\n\nيحضر آخر الكلااس وما عنده مشكله لو تجي آخر 5 دقايق!…الهومووركات تسلمها متى ما تبي!…ايه نعم ايه نعم متى ما تبي تسلمها تسلمهـا…مرة سلمت 7 هومووركات دفعـة وحدة وبعضها متأخر من اسبوعين واكثر وبالنهاية اخذت درجة الواجب الكاملة (16 من 16)…!\n\nوبالتصحيح عسسسسسسسسسل بشكل غير طبيعي سواء بالكويزات او المياجر…يعطيك اكثر من حقك…ومع ذلك لو تراجعـه بعدها وتطلب منه يزيدلك هنـا او هنـا ما بيقصر معك وبيعطيك درجتين او 3 يطيب فيها خاطرك!\n\nتصوروا مرة راجعت معه تصحيح كويز وكنت محتج على تصحيح سؤال معين…وبعد نقاش مدته دقيقة ونص…قالي (معك حق معك حق)…كم تشوف نفسك تستحق من هالسؤال؟!\n\nوالدرجة اللي قلتله ابيها اعتمدها لي خخخخخخخخ…متعاون معك لأقصى درجة بالتصحيح ومستحيل يطلعك وانت زعلان!\n\nوبالكلاس وررك ايضا ما قصر واعطاني درجـه حلووة…وبالنهاية خصم منهـا ومن اللي كلاسووركهم عالي درجـة وحدة عشان يرفع الناس اللي تحت!\n\nيمووون ابو رياض يموووووووووون!\n\nنجي للسلبيات:\n\nاذا انت من النوع اللي تعتمد على الدكتور ونوته بالمذاكره فأنححححححححححححححححححححححححححش!!!!!\nالدكتور للأمانة شرحه كويس بس نوته ملخبط ولا تقدر تعتمد عليه…ومستحيل يقعد بسكشن اكثر من محاضرة وحدة…واحيانا ينهي سكشن بنص محاضرة ويبدا بالسكشن اللي بعده!!…لدرجـة اننا خلصنا المنهج قبل لا تنتهي الدراسة بأسبوعين!!!\nيعني نظامه يعرضلك النقـاط الأساسية من السكشن كامل ويحل سؤال ولا سؤالين ويقوم يطمر للسكشن اللي بعده!\nكويزاته للأمانة مو سهلة!…لازم تكون مذاكر صح!\n\nواسئلة الأولد اكزام ما يعرف يحل اغلبها!!!…وقالي واحد من الشباب انه دكتور (احصاء) مو ماث وانهم اضطروا انهم يحطونه يدرس ماث لكثرة السكاشن وهالشي قاله محمد رياض نفسه لخويي…!\n\nفي النهاية اقول اذا انت من النوع اللي تعتمد على نفسك بالمذاكرة فلااااااااا تفووووته ابدا…واذا انت من النوع اللي يعتمد عالدكتور ونوته بدورلك اي دكتور ثاني لأن اللي تبيه ما بتحصله مع الدكتور محمد رياض…!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p772645-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/muhammad-riaz/94263/11", "user": "user6661", "ts": 1295916999000, "tid": 94263, "pn": 11}}]}', 1295916999000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_gentleman-math201', 'stk-_gentleman', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94443", "n": "Dr. Nadeem Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم 101\n\n* التحضير :\nورقة تمر ع الطلاب وحضر اللي تبي\n\n* طريقة الشرح :\nمسوي سلايدات بنفسه ( أنا مانفعتني ,الكتاب أصرررف ) ويستخدم السبورة لحل إكزامبلز الكتاب\n\n* الكويزات :\nطبعا الكوز ياخذ وقت الكلاس كله , و أول كوز جابه كان حريقة وبعد ماشاف درجات الطلاب بدأ يخفف\n\n* المياجر والفاينلات :\nكومون\n\n* الصوت:\nواضح والظاهر انه قال لنا إنه بريطاني من أصل هندي بس اللهجة بريطانية\n\n* إضافات :\n1) لو عاد بي الزمن لما نزلت عنده …\n2) الحسنة الوحيدة اللي شفتها فيه هي تصحيحه لميجر 1 كان طيب وزود الطلاب شوي …\n3) شف غيره أحسن لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p749081-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadeem-malik/94443/6", "user": "_Gentleman", "ts": 1292954471000, "tid": 94443, "pn": 6}}]}', 1292954471000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-math201', 'stk-user4988', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m94443", "n": "Dr. Nadeem Malik", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201\n101\n\nالتحضير : بالله لا تسأل عن التحضير …\nعدد اللي يحضروا الكلاس يكونوا بين الـ 5 إلى 10 طلاب من أصل 24 طالب … و تلقى في الورقة الكل محضر … و بعض الطلاب المحترمين يحضروا الكلاس لخمس دقائق فقط … يوقعوا على الورقة و يمشوا على طول بكل وقاحة … حنا عارفين إن شرح الدكتور لك عليه بس على الأقل احترم المدرس … مو ترميها في وجهه !!\nالزبدة / يمرر ورقة … ووقع عن اللي تبغى …\n\nطريقة الشرح : تبون الصراحة … أقرأ من الكتاب أصرف بكثييييير … يكتب في السبورة و يرسم إكسات و وايات … يحاول يوصل المعلومة و يوضح الدرس بس بدون فائدة … انا كتبت معاه في أول السمستر … بس عجزت أخرج من نوته بفائدة … أنا استغرب من بعض الأخوان اللي يكتبون وراه … إنتم من جدكم تفهمون شيء من شرحه ؟؟؟\n\nالكويزات : أول 3 كويزات كانت نااار … واحدة منها كانت 7 أسئلة طويلة … صارت ميجر … بعد كذا خفف علينا شوي\n\nالمياجر:كومن\nالفاينلات :كومن\n\nالقريد النهائي: أنا أعطيه C\n\nالصوت: واضح بشكل عام …\n\nإضافات : الرجال مناسب جداً للي يعتمدوا على نفسهم في المذاكرة … لأنه ما يشرح شيء واضح أصلاً ، غير كذا شف لك واحد ثاني …\n\nالحسنات اللي فيه :\n* متساهل في تصحيح المياجر ، و تقدر تكلمه عشان يزود لك كم نقطة …\n* متساهل في أوقات تسليم الهوم وركات و مواعيد الكويزات\n* الرجال تساهل معنا جداً في درجات الكلاس وورك … وزع الدرجات إلى 48 للكويزات + 6 حضور + 6 هوم وركات …\n\nالعجيب في الأمر … إنه بالرغم من الغيبات الشنيعة في كلاسه … إلا إنه أعطى للجميع الدرجة الكاملة حق الحضور … لا تعليق صراحة …\n\nطبعاً آخر أناوسيمينت أرسلها لنا كانت عن الكلاس وورك … و كتب في الأخير /\n\nThank you for your time, it has been very enjoyable teaching you all.\n\nالله أعلم هو كتبها من القلب ؟؟؟؟\n\nختاماً … أنا ما أعتقد إنه راح يستمر في طيبته السمسترات الجاية … خاصةً بعد حالات التطنيش اللي أكلها من طلاب سكشنه …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p766963-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nadeem-malik/94443/7", "user": "user4988", "ts": 1295466289000, "tid": 94443, "pn": 7}}]}', 1295466289000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-osaid-math201', 'stk-osaid', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - T132\n\nالتحضير :\nمرة كل أسبوع أو أسبوعين لكنه ما يهتم بالتحضير أبداً\n\nطريقة الشرح :\nكان يشغل من السلايدات لكنها تغطي على السبورة\nوصار يجي بورقة يكتب منه الأسئلة و يشرح منها\nالدكتور شرحه كويس لو ركزت معاه وسألته تقدر تفهم\nماهو الشرح الخرافي جدا لكن شغلات كثيرة راح تفهمها\n\nالكويزات :\nسهلة من الأسئلة اللي بالكلاس\n\nالمياجر :\nكومون\n\nالفاينلات :\nكومون\n\nالقريد النهائي :\nA\n\nالصوت :\nواطي و هادي و لازم تقعد قدام عشان تسمعه\n\nإضافات :\n- الدكتور حبيب جداً و أخلاقه راقية جدا , يحاول يكون في صف الطالب في كل شيء\n- متواجد بالأوفيس أور في وقته دايما ويستقبل و يجاوب على أي سؤال يقدر عليه\n- ما يهتم بالغيابات أبدا , سألته عن الكلاس وورك بالأوفيس أور , يأخذ أفرج الكويزات ويضربها في أربعه\n- الكورس غثيث جداً و من الممكن يظلم أي دكتور معاه , حاول تذاكر و تركز مع الدكتور وتطلع بقريد إن شاء الله\n- تصحيحه في كويزاته و المياجر بطل يحاول يعطيك على أي شيء كتبته أي حاجة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1374807-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/19", "user": "Osaid", "ts": 1401495945000, "tid": 118563, "pn": 19}}]}', 1401495945000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ak-95-math201', 'stk-ak-95', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 سمستر 151\n\nالتحضير : ما حضر ولا مرة طول السمستر 😆 ، بس آخر كلاس قال للموجودين كل واحد يكتب اسمه ، أظن زود بونص بعدها 😉\n\nطريقة الشرح : غالبا ينقل القوانين من نوتة عنده ، أو يعرضها بوربوينت، ثم يشرحها على السبورة شرح مبسط وسهل مع أمثلة ، ثم يحل عليها أسئلة ، وأحيانا من الأولد اجزام\n\nالكويزات: تميل للصعوبة شوي ، غالبا من أسئلة الكتاب ، لكن تساعدك كثير في معرفة أخطاءك ونقاط ضعفك لتصححها في المياجر 😏\n\nالمياجر ، الفاينلات: كومون\n\nالصوت: يمكن منخفض شوي ، بس الكلاس صغير فغالبا الكل يسمع بوضوح، لو قعدت في الصفوف الأمامية ما عندك أي مشكلة 👍\n\nإضافات :\n- حبيب جدا ومحترم وأخلاق ، ما أذكر إنه عصب على أي واحد طول السمستر 😄\n- مثل ما ذكرت شرحه مبسط جدا، ومدعم بالأمثلة ، بس ركز معاه وأمورك في السليم\n- مثل ما ذكرت إنه ما يحضر ( من التحضير ) ، فما في مشكلة لو تأخرت أبدا\n- تصحيحه للمياجر تستحي تراجعه بعدها 😳 ، يعطيك أكثر مما تستحق بكثييير 👍\n- متجاوب جدا مع الأسئلة ، ما عنده مشكلة يعيد شرح السؤال أكثر من مرة وبأكثر من طريقة\n\nالقريد النهائي:\nِِA\n\nخليه ضمن خياراتك الأولى\nالله يوفقه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1439616-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/24", "user": "AK-95", "ts": 1453146959000, "tid": 118563, "pn": 24}}]}', 1453146959000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a.ee-math201', 'stk-a.ee', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 - T153\n\nالتحضير : ثلاث مرات في السمستر\nطريقة الشرح : عنده نوت يرفعها على البلاك بورد ويشرح منها ، مرتبة بالكونسبت بعدين الأمثلة وأظنها أمثلة الكتاب\nالكويزات : سهلة وأفكارها متكررة من الأولد كويزز\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: A\nالصوت: واضح\nإضافات : -الدكتور محترم جداً وأخلاق لدرجة تنحرج وانت تكلمه\n-تصحيح الدكتور في المياجر جداً مرضي ولو عندك أغلاص بسيطة وخطواتك صح يعطيك زيادة على اللي تستاهله من الدرجة\n-الدكتور عادة ما يشرح بطريقة واحدة فإذا ما فهمت منه ، فراح يعيد كلامه ونادراً ما يفهمك الجزئية بطريقة ثانية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1457221-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/25", "user": "A.EE", "ts": 1473295164000, "tid": 118563, "pn": 25}}]}', 1473295164000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alialdraimli-math201', 'stk-alialdraimli', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 Term 151\nالتحضير :\nما يحضر\nطريقة الشرح :\nالمدرس شرحه ممتاز لأبعد حد لكن ما يجبذك، يعني اذا ما كان الاهتمام منك ما بتستفسد شي\nكان يشرح من سلايدس جيدة ويجل امثلة منها\nالكويزات :\nتميل للصعوبة\nالصوت:\nتحتاج تقعد قدام\nإضافات :\nالدكنور راع في الشرح خلوق جدا جدا في الكلاس وفي المكتب، يحرجك باحترامه … تصحيحه قمة في التسليك والتعاون، يرمي درجات من جيبه (أحسن دكتور اشوفه في التصحيح)\nما كان يحضر طول السمستر باستثناء اخر يوم (كان حاضر سبع طلاب فقط) وقال بزيدكم في الكلاس وورك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466218-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/29", "user": "AliAlDraimli", "ts": 1484332566000, "tid": 118563, "pn": 29}}]}', 1484332566000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m7med_21-math201', 'stk-m7med_21', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 172\nماث 201\nالتحضير : ما يحضر إلا نادرا نادرا يصلح للطلاب اللي ما يحب يحضر ويعتمد على نفسه\nالشرح : ممتاز من النوتات حقته جيدة صراحة .\nالكويزات : نوعا ما صعبة اولد اكزام\nالصوت : ضعيف محتاج تقعد قدام\nاضافات : الكورس غثيث صراحة ويظلم اي دكتور معاه !\nادكتور باي مادة تصحيح خذ معاه بطل بطل بطل يعطيك فوق حقك وزيادة واذا راجعت معه المكتب ما يقصر معك !", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1492427-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/30", "user": "M7med_21", "ts": 1526397913000, "tid": 118563, "pn": 30}}]}', 1526397913000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abbas_tesla-math201', 'stk-abbas_tesla', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118563", "n": "Dr. Adel Khalfallah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "192 - MATH 201\nالتحضير : حضر مرة وحدة قبل الكورونا والاون لاين ما اذكر ان حضر\nطريقة الشرح : يشرح على السبورة مع عرض بوربوينت وبعد مايخلص السكشن يحل اولد اقزام عليه\nالكويزات :متوسطة الى سهله ويعطي وقت كافي جداً ، الاون لاين 3 اسئلة في ربع ساعة\nالمياجر:كومن\nالفاينلات :كومن\nالقريد النهائي: A+\nالصوت: واضح\nإضافات :الدكتور محترم جداً وبشوش ويفتح النفس\nويتقبل اي سؤال مهما كان غبي ويجاوب عليه وقبل بداية اي كلاس يسأل اذا عندكم اسألة ويحلها\nمثل ماقلنا ما كان يحضر فالحضور كان قليل جداً ووقت الكويز الكلاس يمتلي\nالواحد صراحة يستحي في الايام العادية الحضور قليل واللي يتفاعل اثنين ثلاثه بس والدكتور يحب احد يتفاعل معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525203-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adel-khalfallah/118563/33", "user": "Abbas_Tesla", "ts": 1598699722000, "tid": 118563, "pn": 33}}]}', 1598699722000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8708-math201', 'stk-user8708', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118578", "n": "Dr. Hafiz Fakharuddin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم 131\n\nالتحضير :\n\nكان اول السمستر يمررر ورقة\n\nوطبعا الورقة كاملة\n\nوفي الحقيقة الكلاس مايتعدى 10 طلاب\nبعدها صار هو يحضر بالارقام\nطبعاً مافيه ليت بس بعض الاحبان يدقر إذا تأخرت فوق الربع ساعة\nيعطيك النظرة\n\nطريقة الشرح :\n\nمعه اوراق يكون منزلها في البلاك بورد طبعا بخط اليد ما راح تستفيد منها الا في مذاكرة الكويزات لانها فاشلة بكل ماتعنيه الكلمة\nالنوت عبارة تعاريف و بعض اسئلة الكتاب هو بنفسه حالها\n\nممكن تلاقي ما ينتبه معه الا اثنين من الطلاب والباقين على جولاتهم\nمنظر ولا عمري شفته و لااظن بشوفه في المستقبل\n\nالكويزات :\n\nمن النوت وبعض الاحيان يشطح بأسئله من راسه\nالمياجر:\n\nتصحيح المياجر كان تعبان جداااااااااااااا لدرجة انه يدقق على اتفه الاشياء\nالقريد النهائي:\nd\nكنت بعطيه اف بس تذكرت اني ختمت تويتر في كلاسه\nالصوت:\nاكسنت هندي رايح فيها\nإضافات :\n\nالمدرس كنت منزل معه على اساس انه يدف بالتصحيح ولكن للاسف انصدمت مع زملائي بأن سكشنا في كل الميجرين اقل من الكورس العام\nمدرس ما يشرح ويدف تبلعها\nاما مدرس لا شرح ولا تصحيح معناها اهرررررررررررررررررررررررررررررب", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1321714-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hafiz-fakharuddin/118578/27", "user": "user8708", "ts": 1390516701000, "tid": 118578, "pn": 27}}]}', 1390516701000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-soomy11-math201', 'stk-soomy11', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118578", "n": "Dr. Hafiz Fakharuddin", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ماث 201 ترم132\n\nالتحضير :\n\nبالارقام اخر الكلاس\n\nطريقة الشرح :\n\nمش ولابد ( توصيله للمعلومة في بعض الأحيان يكون سيء ) بس اللي يميزه أنه\nعنده أوراقه كاتبها بخط يده يجي و يشرح منها … أنا كنت حاطها عندي في جهازي النوت و اسجل ملاحظات وراه و بعض الطلاب كانو يطبعونها و يسجلو الملاحظات\nالنوت حقه اذا سجلت وراه ملاحظاتك ( راح تكون النوت جيدة نوعا ما ) أما هي لحالها سيئة\nالكويزات :\n\nسهله للي ذاكر\n\nالمياجر:\n\nتصحيحه هي اكثر ما يميزه ( يعطيك حقك و فوقه شوية وصايا )\nالقريد النهائي:\nc+\n\nاضافات :\n\nلو يتناسب مع وقتك خذ عنده … غير كذا لا … لأن حرااام تخبص جدولك و تحوسه عشانه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1414496-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hafiz-fakharuddin/118578/29", "user": "soomy11", "ts": 1416626720000, "tid": 118578, "pn": 29}}]}', 1416626720000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-21m-math201', 'stk-21m', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118579", "n": "Dr. W Al-Khulaifi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201 - T211\n\nدكتور وليد الخليفي\nالتحضير: يحضر نهاية كل كلاس وما يركز كثير على المتأخرين يحط الكل حاضر\nطريقة الشرح : في بداية كل درس يعطيك مقدمة بسيطة عنه واستذكار للي اخذته من قبل عشان يساعدك تربط بين الي اخذته قبل والحين وبعدها يبدأ يحل مسائل على الكونسبت ويتأكد انك فاهم ويتقبل اي سؤال تسأله\nالكويزات :متوسطة اغلبها من سلايداته والكتاب والي يحلها بالكلاس اذا كنت مركز معاه وفاهم بتعرف تحلها ببساطة وماراح تاخذ منك وقت\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: ِA+++++++++++++++\nالصوت: واضح جدا\nإضافات : دكتور وليد من افضل الدكاترة الي درسوني بالجامعة اخلاق وشرح والابتسامة دايم على وجهه ويساعد الطلاب باللي يقدر عليه ولو تروح له اوفيس اور مستعد يشرح لك كل الافكار من جد وجديد وبنفس حلوة ويعطيك افكار تساعدك وتبسط لك فهم المعلومة والله دكتور رهيب بشكل مو طبيعي الله يسعده بس\n\nحاول تنزل عنده بدون ماتفكر او تقارنه بغيره ابد والله عسل عسل عسل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1532716-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-al-khulaifi/118579/25", "user": "21M", "ts": 1636630860000, "tid": 118579, "pn": 25}}]}', 1636630860000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6095-math201', 'stk-user6095', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118582", "n": "Dr. Stefanos Orfanos", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 - Term 111\n\nالتحضير : ورقة و تمر على الطلاآب\n\nطريقة الشرح : يشرح الكونسبت … و يحل اسئلة …\n\nالكويزات : متوسّطة و مآئلة لـ السهولة\n\nالقريد النهائي: A+\n\nالصوت: وآضح … و اللكنة حلوة\n\nإضافات : متســآهل في التصحيح …\n\nيُـنصح به …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p974849-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stefanos-orfanos/118582/3", "user": "user6095", "ts": 1327711017000, "tid": 118582, "pn": 3}}]}', 1327711017000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeezoo_227-math201', 'stk-zeezoo_227', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m118582", "n": "Dr. Stefanos Orfanos", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nسمستر 111 - ماث 201\nالتحضير :\nورقة يمررها عالطلاب\nطريقة الشرح :\nممتازة جدا , وخاصة في ذا الكورس لانه يتمد عالرسم وهو فنان فيه\nالكويزات :\nسهلة , وبعض الاحيان متوسطة\nالمياجر:\nكومن , بس تصحيحه احسن واحد في الحياة , لا تسب ولا فراغ فاضي في الاختبار اقل شي اشتق كل شي هههههه وهو بيعطيك درجة ,اشوفه احسن دكتور في التصحيح ودف الدرجات\nالفاينلات :\nكومن , صحيحه ممتاز\nالقريد النهائي:\nA+++++++\nالصوت:\nواضح , مدرس فلللللللللللللللة لابعد حد لدرجة ان ما ودك تغيب عن الكلاسات , عليه اسلوب وحركات في الفصل مو صاحية هههه , شبابي جدن\nإضافات :\nانصح به وبقوة , ياريت اشوفه في اي مادة , على طوووول بنزل عندو\n\nاحسن مدرررررررررررررررررس على الاطلاق ^^", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p987170-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/stefanos-orfanos/118582/4", "user": "zeezoo_227", "ts": 1329320681000, "tid": 118582, "pn": 4}}]}', 1329320681000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10282-math201', 'stk-user10282', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m172442", "n": "Dr. Nicolas Hadjisavvas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بسم الله الرحمن الرحيم\n\nأخذت معه MATH201 - Term 161\n\nهذا الدكتور أنا أعتبره باختصار وبكلمة واحدة آفرج دكاترة الماث 😆\nيشرح أمثلة شبيهة جداً بأمثلة الكتاب (إن لم تكن نفسها) ، شرحه عادة متوسط ، مرات يبدع ، لكن بعدد المرات الي يبدع فيها هناك مرات يخبص فيها ، فمرده للآفرج 😆\nيحضر بورقة يمررها على الطلاب\nلغته واضحة، أخلاقه جيدة\nتصحيحه حليو ، ما يلتزم حرفياً بالسلوشن، وأنا كنت مبدع فما أدري يدف أو لا 😏\nكويزاته كذلك متوسطة\n\nعنده حركة لطيفة … وهي أنه يرسل ملف فيه remarks على شكل نقاط بالتزامن مع رفعه لدرجات المياجر على البلاك بورد، تحتوي على تنبيهات على أخطاء وقعوا فيها الطلاب في الاختبار.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466677-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicolas-hadjisavvas/172442/5", "user": "user10282", "ts": 1484965724000, "tid": 172442, "pn": 5}}]}', 1484965724000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_nd_m-math201', 'stk-m_nd_m', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m172442", "n": "Dr. Nicolas Hadjisavvas", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "T161 - MATH 201\n\nالتحضير : ورقة تمر على الطلاب… بعض مرات ينسى و في كم مرة ينعدون على الاصابع على طول حضر باول ٣ دقايق و الباقي حطهم غياب… ماعندهم مشكلة تحضر و تختبر مع سكشن ثاني و مادري اذا يخصم على الغياب وكم غياب يحذف (ماذكرلنا اي شي من هذه الناحية)\n\nطريقة الشرح : على السبورة… شرحه عادي… منظم من ناحية تسلسل لكن بالسبورة تحسه All over the place… يشرح كل شي بخصوص الدرس و يشدد على القوانين المهمة\n\nالكويزات : متوسطة الصعوبة\n\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: أتركه لكم\n\nالصوت: اكسنت يونانية واضح النبرة\n\nإضافات :\n\nمادري ليه في ذم كثير للدكتور… لما تقول لواحد ادرس عند نيكولاس يعطيك الوجه اللي اعوذ بالله 🤠\n\nالدكتور فاهم زين و مصنف بمرتبة بروفيسور و حبيب بالأوفس أورز\n\nشخصيًا سجلت عنده متعمد ماث 202… عجبني\n\nالتصحيح كويس… لا تَظلمون ولا تُظلمون و فوقها بوسة بعد و مو معقد… و متوسط السرعة بالتصحيح\n\nدائمًا يعطي فرصة تراجع اوراق المياجر قبل ما يسلمها للديبارتمنت… و أنصح الجميع يروح يراجعها\n\nيسوي كلاسات خارج اوقات الدوام يحل فيها مسائل برضو أنصح الجميع يحضرها\n\nبالنسبة للكلاسورك مايختلف كثير عن اللي حطه الأخ Mr.A فوق\n\nأخيرًا الدكتور عنده مرض (على كلامه) يخليه يتلخبط شوي بالحل لكن غالبًا ما يتدارك الموضوع… الله يشفيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466794-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nicolas-hadjisavvas/172442/6", "user": "M_nd_m", "ts": 1485107850000, "tid": 172442, "pn": 6}}]}', 1485107850000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_1022-math201', 'stk-_1022', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m172449", "n": "Dr. Yassir Khalid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math-201---Term-171\n\nالتحضير : يوميا ً ، ورقة تمر ع الطلاب ويوقعون\nما يحاسب على التأخير\n\nطريقة الشرح : يشرح أقزامبل الكتاب يكتبها ع السبورة ويحلها\n\nالكويزات : يكون محددها من بداية الترم\n6 كويزات في السمستر ، وترتيبها كان مرتب شامله لكل الدروس\nأشوفها صعبة لأنها من الأولد اكزام\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: --\nالصوت: واضح ، بالانجليزي ولو تسأله بالعربي يجاوب ماعنده مشكلة\nإضافات : الدكتور طيب وخلوق ومتجاوب مع أسئلة الطلاب ، طبعاً هو سوداني وماصار له فترة من تخرجه على مايبدو\nشرحه كويس ويوصل المعلومة ،، وتصحيحه ممتاز جداً يحاول يعطيك بوينت ع أي شي يشوف طريقته صح\nالعيب الوحيد أنه يشرح اقزامبل الكتاب وكوزاته من الأولد ، يعني لو بتذاكر النوت الا يشرحه\nغير كافية للكويز … كوزاته صعبة تحتاج تمر ع الأولد اقزام\nالدكتور بشكل عام كويس وإذا بتركز معاه ف اللكشر وبتذاكر أولد للكويز ( أمورك ف السليم )", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486097-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/yassir-khalid/172449/9", "user": "_1022", "ts": 1515974294000, "tid": 172449, "pn": 9}}]}', 1515974294000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-melhim-math201', 'stk-melhim', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور أردني جديد فالجامعة\nماث 201 ترم 162\nالتحضير : آخر الكلاس وما يعطي ليت بس اللي يتاخر يخليه واقف برة شوي … مرات كان ياخرنا دقيقتين زيادة عن وقت الكلاس\nطريقة الشرح : الدكتور شريح ولكن شرحه سريع شوي بالنسبة لي ما كنت افهم كل شي احب اللي يشرح بروقان … يسأل الطلبة عن طريقة حل المسائل ويطلعهم عالسبورة\nالكويزات : متوسطة , اخذنا 5 وحذف أسوأ كويز وفي كويز صحح ثلاثة اسألة من اصل خمسة واللي حل ثلاثة صح اعطاه فل\nالمياجر:كومن\nالفاينلات :كومن\nتقييمي للدكتور :B\nالصوت:واظح والانجليزية ممتازة\nإضافات :ممكن ما يتعمق بصعوبة الاسئلة واجد و مرات يشرح من السلايدات وهذا اشوفة غير صائب لمادة مثل الماث\nفتصحيح المياجر في حلول ما اعطى عليها بوينتس مادري بسبب السرعه او شي ثاني بس راجعة بيعطيك حقك وزيادة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1476268-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/2", "user": "Melhim", "ts": 1499792951000, "tid": 175799, "pn": 2}}]}', 1499792951000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10843-math201', 'stk-user10843', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201, Term: 181\n\nالتحضير: يحضر بالبلاكبورد بنهاية المحاضرة، ومايدخل المتأخرين اكثر من ١٠ دقايق.\nيسمح بالحضور في اي شعبة من شعبه، يعني يمديك تحضر يوم الاحد في شعبة والثلاثاء في شعبة والخميس في شعبة ولا بيقول شي 🙂\n\nالشرح: عنده نوتة يفتحها ويحل الاسئلة اللي فيها، يشرح فكرة الدرس بشكل سريع و يركز على حل الامثلة أكثر. سريع جدا بالشرح، يعني مايمديك تفهم المثال الاول الا وهو طاب في الثاني ومخلصه 🙂 لكن مع ذلك شرحه جيد ومتجاوب مع الاسئلة.\nالنوتة اللي يشرح منها جدا ممتازة، احسن من الكتاب حتى وفيها اختصارات كثيرة، لكن مشكلتها مافيها حلول، لذلك يبغالك تكتب وراه بالمحاضرة. ماتحس بثقل المحاضرة معاه، ويحب ينكت كثير، والصراحة ذباته حلوة 🙂\n\nالكويزات: للحين وصلنا نص الترم عطانا كويزين فقط، وكلها سهلة. بأخر كويز سألوه الشباب عن سؤال وشرحه لهم ومابقى الا يحله عنهم.\nالتصحيح: متساهل شوي، يحاول يعطيك الدرجة بكل الطرق 🤪\n\nمشكلة الدكتور فقط انه يعطينا هومووركات طويييييييلة جدا وتهد الحيل، فوق ٥٠ سؤال تقريبا. لكن يوم كلمناه نقصه لنا شوي و الصراحة انه متفهم جدا للطلاب، اخر هوموورك اجله اسبوع واللي قبله اجله ايضا. محترم لابعد درجة ويحب ياخذ ويعطي مع الطلاب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501775-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/8", "user": "user10843", "ts": 1541159014000, "tid": 175799, "pn": 8}}]}', 1541159014000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammad-72-math201', 'stk-mohammad-72', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 term192\nلتحضير :اخر الكلاس ويقبل ميكب\nطريقة الشرح : بالايباد شرح من نوته موب شامله صراحة وسيىة\nالكويزات :على حسب الافرج حق اللي قبله لكن غالبا وسط الى صعب\nالمياجر:x\nالفاينلات :x\nالقريد النهائي: c او c+\nالصوت: واضح ويوصل للكل\nإضافات :\nالدكتور يخصم عالغيابه\nفلكسبل مره في المواعيد\nيركز على حل الاولد اكثر من الكونسبت\nسريع جدا في السكاشن مايعطيها حقها اهم شي يلحق عالسيلبس\nيعطي واجبات طويلة(حول40 سوال)بس ياجل لاطلبنا التاجيل\nيطلب برزنتيشن!!!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521325-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/18", "user": "mohammad-72", "ts": 1586382741000, "tid": 175799, "pn": 18}}]}', 1586382741000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-wolf_99-math201', 'stk-wolf_99', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201\n192\n\nالتحضير : نهاية كل كلاس يحضر وعادي تسوي ميكب اب طول الترم وعادي تتأخر كم دقيقة بس لاحظت فيه انه ياخذ فكرة سيئة عنك اذا صرت تتأخر بشكل متكرر\n\nطريقة الشرح : يشبك البروجكتر بالايباد حقه ويشرح ، اشوف ان طريقته مملة شوي بالشرح بسبب انه مايتفاعل مع الطلاب بالشرح اغلب وقته منزل راسه عالايباد وتسمع صوته فقط ، بس هذي السلبيه في شرحه ولا الباقي تمام\n\nالكويزات : اختبرنا كويزين وبعدين جت نكبة كورونا (: واختبرنا كويز واحد اونلاين وكل كوزاته مستواها من متوسط الى عالي شوي\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي : B+\n\nالصوت: واضح و ينسمع من نهاية الكلاس\n\nإضافات :\n١-الدكتور طيب ومتعاون جدا ومتفهم ويعتبر من اكثر الدكاترة اللي مروا علي بالجامعة من ناحية التسهيل على الطلاب\n٢- الدكتور طريقة تتوزيعه للكلاس وورك غريبه شوي ويعطي الطلاب واجبات غير الاونلاين واشوفها سلبيه لأنها تشغلك وهو يجيب اسئلة الواجب من الاولد اكزامز وانت بالنهاية راح تمر عليها قبل الميجر وطلب مننا زيادة برزنتيشن نهاية الترم ووقدمناه اونلاين (:\n٣- واهممم نقطة اذا تفكر تنزل عنده :\nاذا انت منت راعي غياب وتحب تأخذ المعلومة من مدرسك وتحب ماتطلع من الكلاس الا فاهم ومستعد تترك جوالك طول وقت الكلاس انصحك بالدكتور وبقووة\nاذا انت زي ووضعي الدكتور والكلاس اخر اهتماماتك وقالبها سلف ستدي اقولك لاتسجل عنده لأنه مايصلح لك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1521672-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/19", "user": "wolf_99", "ts": 1588235901000, "tid": 175799, "pn": 19}}]}', 1588235901000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rm121-math201', 'stk-rm121', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201\nTerm 201 - online\n\nالتحضير :\nيرفع التحضير من MS TEAMS بدون ما ينادي اسماء ويحطيك ليت اذا كنت متاخر ٥ دقايق ويغيبك اذا ١٠ دقايق\n\nطريقة الشرح :\nيفتح نوته ويبدا يتكلم ويكتب فيها وصراحه مب مرتب الوضع حوسه بس اذا خلص الكلاس يرتب النوتات وينزلها بلاك بورد\n\nالكويزات :\nدمار الوضع صراحه ، اختبرنا كويز واحد تشابتر ١٠ وبعدين سحب الييين جاء اخر ربع من السمستر ضغطنا باربع كوزات ضغط مو طبيعي وصراحه صعبه واختياره للاسئله عشوائي من بنك الاسئله يعني انت وحظك …\n\nالمياجر :\nكومن\n\nالفاينل :\nكومن\n\nالقريد النهائي :\nB او C+\n\nاضافات :\nالدكتور بكل امانه متساهل جدا من ناحية التاجيل واخلاقه عاليه واسلوبه ممتاز ولكن عتبي عليه هو موضوع الكوزات لاني اشوفه ظلمنا بالاسئله الصعبه وطريقتها ، ٣ تسئله ملتبل تشويس وحلها طوييل يعني ممكن تغلط باشاره تروح عليك!\nاخذت فالكلاس وورك درجه سيئه جدا مع اني مبدع مره فالمياجر والفاينل", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527551-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/23", "user": "RM121", "ts": 1609773772000, "tid": 175799, "pn": 23}}]}', 1609773772000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abubakermt-math201', 'stk-abubakermt', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m175799", "n": "Dr. Taleb Alkurdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH201 Term222\n\nالتحضير: عن طريق النظام الجديد اللي هو بالـ QR Code يعرضه اول دقيقتين ممكن و الباقين يسجلهم متأخر، حسب كلامه ان المتأخرين ما عليهم شيء و زيهم زي اللي حضروا بالبداية. طبعًا الدكتور نوعًا ما مشدد عالتحضير و اذا تأخرت 10 دقايق غالبا ما بتدخل. الغيابات يعاملها كأنها كويز بمعنى اذا غبت 10 مرات كأنك اخذت كويز و جبت فيه 0 و راح ينضاف للكلاس وورك.\n\nطريقة الشرح: يشرح من سلايداته و شرحه جيد للأمانة.\n\nالكويزات: كلها كانت اختيار من متعدد و الاسئلة كانت جدااا مباشرة و نفس اسئلة الامثلة اللي بالكتاب لكن الارقام فيها كبيرة لذلك بتضيع وقت و انت تحسب، الدكتور كان جدا مرن من ناحية التأجيلات. اخذنا 6 كويزات و حذف منها اسوأ واحد.\n\nالصوت: واضح و مسموع للكل.\n\nالقريد النهائي: B+\n\nإضافات: الدكتور مرح جدا و يحب يمزح و ينكت كثير. الدكتور يستقبل اي سؤال و ما عنده مشكلة يعيد لك اي جزئية ما فهمتها. الدكتور يتنرفز من موضوع الجوال و من موضوع الطلعات الكثيرة خارج الفصل سواء لدورة المياه او اي سبب اخر.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536693-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/taleb-alkurdi/175799/24", "user": "AbubakerMT", "ts": 1684169601000, "tid": 175799, "pn": 24}}]}', 1684169601000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abaadi-math201', 'stk-abaadi', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m176965", "n": "Dr. Jae-Chean Joo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math201-T(192 half online)\nMath202-T(202 online)\n\nتحضير: ما يحضر الدكتور باختصار.\nطريقة الشرح: يتكلم ويكتب على نوتات ويحملها بعدين ع البلاكبورد ويسجل المقاطع كمان وصراحة شرحه لا بأس به(خاصة حضوري) ونوتاته كمان(للعلم في ماث 201 الجزء الحضوري ما كان عنده لمن بالاونلاين بدا يسوي).\n\nكوزات: من 5 لين 6 وصراحة مستواها اكثر حرااااااق جدا. مقارنة مع الحضوري كانت جيدة لكن مع نهاية الترم 202 بدا يسهل كم كويز عشان الافرج المخسوف بالارض.\n\nميجر وفاينل كومون.\nقريد نهائي: حضوري B+، اونلاين صراحة c+\nصوت: هو كوري الدكتور وكلامه بالانجلش شويتين يبيله وقت عبال ما تستوعب وش يقول.\nاضافات: الدكتور ينفس سريع بشكل غريب والحصة مملة بصراحة . خله من اخر خياراتك (انا اخذت عنده مرتين عشان الجدول لاغير)", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530337-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/jae-chean-joo/176965/6", "user": "Abaadi", "ts": 1622756165000, "tid": 176965, "pn": 6}}]}', 1622756165000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-man.moh-math201', 'stk-man.moh', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "MATH 201 -181\nالتحضير :\nعلى المزاج , سكشن وسكشن .\nطريقة الشرح :\nكانت جدا سيئة , يفتح النوتة على البروجكتر ويقرا منها السؤال والسولشن فقط.\nالكويزات :\nمتوسطة ومائلة للسهولة.\nالمياجر:\nكومن\nالفاينلات :\nكومن\nالقريد النهائي: F\nالصوت:\nواضح\nإضافات :\nللاسف كان الدكتور جدا سيئ في ذاك الترم . يسمح بالميكب طول السنة , يعطي هوموركات مفيده واسئلة محلولة من الاولد اكزام.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504850-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/11", "user": "Man.Moh", "ts": 1547366837000, "tid": 176969, "pn": 11}}]}', 1547366837000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-omar.ab-math201', 'stk-omar.ab', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Math 201 --183\nالتحضير : اول اسبوع كان يحضر بعدين خلاااااااااااااااااص ما صار يحضر ابدا لدرجة اغلب الكلااس يغيبون\nطريقة الشرح : ما عجبني شرحه ابدا ويغلط كثيييير خصوصا في الرسمات حضورك لكلاسه زي عدمه\nالكويزات : اولد اقزام نسخ لصق غالبا\nالمياجر:\nالفاينلات :\nالقريد النهائي: D واحس كثيرة عليه\nالصوت:\nإضافات :\nاحسه ينتقم لشي صار له بدراسته , اسلوبه غريب مستحييييل تطلع من الكلاس ابدا + فيه هوم ورك له غير الاون لاين هوم ورك غثيييييييييييث ويجط الديدلاين في اوقات المياجر والفاينلات , تصحيحه ينرفففففففز ما يحاسب الى على الاجابة النهائية لو الاجابة النهائية صح يحاسبك على الخطوات لو المياجر خيارات وتبي المادة سلف ستدي وما تحضر سجل عنده لكن لو رتن نصيحة انححححححححححححش", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513248-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/14", "user": "omar.ab", "ts": 1564770120000, "tid": 176969, "pn": 14}}]}', 1564770120000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-math201', 'stk-rapls', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m176969", "n": "Dr. Abed-Alhay Elmughrabi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math201 - 183\n\nالتحضير : حضر أول اسبوع بعدها الى نهاية الترم ما حضر\nطريقة الشرح : كاتب نوتة بخط اليد , يعرضها ع البروجكتر ويشرح منها , شرحه كويس لكن احيانًا تسأله عن شيء يضيع\nالكويزات : في العادة اقرب أولد اقزام , تصحيحه على الحل النهائي , يا تاخذ ع السوال خمسة او صفر , ونادرًا ما يعطي بينهم\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B+\nالصوت: واضح\nإضافات : الدكتور حبيب وأخلاقه حلوة , يعطي هومووركات للكلاس وورك , وزودنا كلنا بالكلاس وورك , كان في مشكلة بسيطة هو انه لما يكتب بالسبورة الخط صغير والطبشورة مو واضحة يعني لازم تركز مع كلامه اكثر من السبورة .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1513383-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abed-alhay-elmughrabi/176969/15", "user": "Rapls", "ts": 1565022663000, "tid": 176969, "pn": 15}}]}', 1565022663000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m.9-math201', 'stk-m.9', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m181955", "n": "Dr. Brahim Mezerdi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "براهيم مزيد\nTerm :201\nMath 201\nطريقة الشرح:\nالكلاس كان من البلاكبورد يعرض سلايدات الكتاب ويقراها ويحط خطوط ويكتب بالماوس(لو رجال افهم كلمه من الي يكتبه)\nاذا تبغا دكتور يشرح لك لا تفكر تنزل من الآخر شرحة متواضع جداًًً\nالتحضير:\nالدكتور اسطوووووررة في التحضير ماحضر الا مره وحده طول الترم وما اتوقع انه خصم في الغياب على احد وما كان مركز اهم شي تحطون واحد يقوله (تمام، فاهمين ، الي بعده)\nالكوزات:\nاختبرنا ٦ كوزات وحذف اسوء واحد\nكل كوز عليه ٩ بوينت ثلاث اسئلة يعني\n٩*٥ = ٤٥ وهي الكلاس ورك\nالكوزات مستواها متوسط لصعب ويجيب نسخ لصق من الاولد اقزام بس لو تذاكر بتشوفها سهله وكلها خيارات من البلاكبورد\nاضافات:\nلو بتاخذ الماده سلف ستدي نزل عنده اما لو تبغا دكتور يشرح لك لا تنزل عنده ترا شرحه مو ذاك الزود (يادوب يوصل الفكره) تابع اونلاين كورس اصرف لك.\nالدكتور يعجب الي ماخذ الماده سلف ستدي او حذف الماده وفاهمها ويبغا دكتور يمشي الحال وانا اشوف الدكتور صراحه طيب وفاهم بس مايعرف يوصل معلومه.\nونصيحتي لماث ٢٠١ نوتات الرصاصي واونلاين كورس وأسئلة الهيلب سشن واضمن لك قريد جبار.\nملاحظة:\nالدكتور مضيع شويتين\nيرسل شرح المد في نفس اليوم والدكاتره الثانين مرسلين لطلابهم قبلها بيومين والكوز يقولك في ٣ سكاشن وفي وسط الكوز تكتشف ان الكوز في سكشنين بس وانت ضيعت وقت في سكشن وماجاك في الكوز", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527704-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/brahim-mezerdi/181955/6", "user": "M.9", "ts": 1610147672000, "tid": 181955, "pn": 6}}]}', 1610147672000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-aomab-math201', 'stk-aomab', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m181956", "n": "Dr. Dhaker Kroumi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ترم 191 Math201\n\nالتحضير : افضل دكتور تحضير\nيسمح بالتأخير لكن بداية السمستر يدقر شوي\nقبل الفاينلات باسبوعين وقف تحضير وحذف\nغيابات الطلاب كلها\nطريقة الشرح :\nشرح بالسبورة جيد\nبس ما ينفع للكل شرحه شوي سريع\nويركز على حل الاسئلة اكثر من الكونسبت\nفإذا انت من النوع اللي يذاكر قبل الكلاس ينفع لك\n(زيادة عنده مشكلة مع حرف r يكتبه زي الباي π 🤪)\nالكويزات :\nسهلة لكن التصحيح يكون على الجواب النهائي فحاول تجي فاهم وحال كم سؤال\n+ اخر الترم اعطانا 3 كوزات عشان يرفع الافرج\n\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: B\nالصوت: واضح جدا\nإضافات :\nاذا انت من النوع اللي ما يعتمد على الدكتور في المذاكرة نزل عنده واضمن الكلاس وورك\nاذا تبي واحد يشرح فما راح يفيدك بالقدر الكافي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518072-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhaker-kroumi/181956/2", "user": "AOMAB", "ts": 1576609217000, "tid": 181956, "pn": 2}}]}', 1576609217000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-nasalmz-math201', 'stk-nasalmz', 'MATH 201', 'doc', '{"docs": [{"id": "stk-dr-m181956", "n": "Dr. Dhaker Kroumi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "math 201 term 191\n\nتحضير ما يعترف فيه بس يبري الذمه حضر مرتين لعيون أنظمة الجامعة\nتصحيحه عسل جدا ويدخل قروب الواتس ويرسلكم حل الميجر بعد دقائق من الاختبار.\nمع الاسف الطلاب ما يحضرون عنده بسبه انه ما يحضر لكن والله ثم والله شرحه ممتاز ويفصل في الامثلة ويرفع نوتته ف البلاك بورد بس انها مختصر للكتاب.\nتقييمه A+++\n\nاضافات:\nيعطيك حركات بركات مختصرة في 201 مره مفيدة.\nكوزاته لما تحل تكتشف الارقام غريبه لدرجة انك تشك بحلك.\n\nانصح فيه ججدا", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1522361-math201", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dhaker-kroumi/181956/4", "user": "Nasalmz", "ts": 1590422165000, "tid": 181956, "pn": 4}}]}', 1590422165000, 1794318292, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
